import"./chunk-7CGTOI24.js";var e={id:"p2ch18-intrapartum-assessment-b",order:9,code:"p2ch18",titleFa:"\u0627\u0631\u0632\u06CC\u0627\u0628\u06CC \u062D\u06CC\u0646 \u0632\u0627\u06CC\u0645\u0627\u0646",titleEn:"Intrapartum Assessment",summaryFa:"\u067E\u0627\u06CC\u0634 \u0627\u0644\u06A9\u062A\u0631\u0648\u0646\u06CC\u06A9 \u062C\u0646\u06CC\u0646\u060C \u0627\u0644\u06AF\u0648\u0647\u0627\u06CC \u0627\u0641\u062A \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628\u060C \u0648 \u0637\u0628\u0642\u0647\u200C\u0628\u0646\u062F\u06CC \u0633\u0647\u200C\u06AF\u0631\u0648\u0647\u06CC.",readingMinutes:28,sections:[{heading:"\u0631\u0648\u0634\u200C\u0647\u0627\u06CC \u067E\u0627\u06CC\u0634 \u0627\u0644\u06A9\u062A\u0631\u0648\u0646\u06CC\u06A9 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062C\u0646\u06CC\u0646",paragraphsHtml:["<p>\u0627\u062E\u062A\u0631\u0627\u0639 \u0645\u0627\u0646\u06CC\u062A\u0648\u0631\u06CC\u0646\u06AF \u0627\u0644\u06A9\u062A\u0631\u0648\u0646\u06CC\u06A9 \u062C\u0646\u06CC\u0646 \u062F\u0631 \u0627\u0648\u0627\u062E\u0631 \u062F\u0647\u0647\u200C\u06CC \u06F6\u06F0 \u0645\u06CC\u0644\u0627\u062F\u06CC \u062A\u0634\u062E\u06CC\u0635 \u062F\u06CC\u0633\u062A\u0631\u0633 \u062C\u0646\u06CC\u0646 \u0631\u0627 \u0627\u0632 \u06CC\u06A9 \u0641\u0631\u0636 \u0628\u0647 \u06CC\u06A9 \u06CC\u0627\u0641\u062A\u0647\u200C\u06CC \u0642\u0627\u0628\u0644 \u062B\u0628\u062A \u062A\u0628\u062F\u06CC\u0644 \u06A9\u0631\u062F \u0648 \u0627\u06A9\u0646\u0648\u0646 \u0634\u0627\u06CC\u0639\u200C\u062A\u0631\u06CC\u0646 \u067E\u0631\u0648\u0633\u0647\u200C\u06CC \u0645\u0627\u0645\u0627\u06CC\u06CC \u062F\u0631 \u0622\u0645\u0631\u06CC\u06A9\u0627\u0633\u062A.</p>",'<p><strong>\u0645\u0627\u0646\u06CC\u062A\u0648\u0631\u06CC\u0646\u06AF \u062F\u0627\u062E\u0644\u06CC:</strong> \u0628\u0627 \u0627\u062A\u0635\u0627\u0644 \u06CC\u06A9 \u0627\u0644\u06A9\u062A\u0631\u0648\u062F \u0645\u0627\u0631\u067E\u06CC\u0686\u06CC \u062F\u0648\u0642\u0637\u0628\u06CC \u0628\u0647 \u067E\u0648\u0633\u062A \u0633\u0631 \u062C\u0646\u06CC\u0646 \u0627\u0646\u062C\u0627\u0645 \u0645\u06CC\u200C\u0634\u0648\u062F\u061B \u0646\u06CC\u0627\u0632\u0645\u0646\u062F \u067E\u0627\u0631\u06AF\u06CC \u067E\u0631\u062F\u0647\u200C\u0647\u0627 \u0648 \u0648\u0631\u0648\u062F \u0628\u0647 \u06A9\u0627\u0648\u06CC\u062A\u0647\u200C\u06CC \u0631\u062D\u0645 \u0627\u0633\u062A. \u0627\u0644\u06A9\u062A\u0631\u0648\u062F\u0647\u0627\u06CC \u062F\u0648\u0642\u0637\u0628\u06CC \u0628\u0647 \u06CC\u06A9 \u0627\u0644\u06A9\u062A\u0631\u0648\u062F \u0645\u0631\u062C\u0639 \u0631\u0648\u06CC \u0631\u0627\u0646 \u0645\u0627\u062F\u0631 \u0645\u062A\u0635\u0644 \u0645\u06CC\u200C\u0634\u0648\u0646\u062F \u062A\u0627 \u0645\u0632\u0627\u062D\u0645\u062A \u0627\u0644\u06A9\u062A\u0631\u06CC\u06A9\u06CC \u06A9\u0645 \u0634\u0648\u062F. \u0641\u0627\u0635\u0644\u0647\u200C\u06CC \u0632\u0645\u0627\u0646\u06CC \u0628\u06CC\u0646 \u0645\u0648\u062C\u200C\u0647\u0627\u06CC <span class="en">R</span> \u067E\u06CC\u0627\u067E\u06CC <span class="en">ECG</span> \u062C\u0646\u06CC\u0646 \u062A\u0648\u0633\u0637 \u06A9\u0627\u0631\u062F\u06CC\u0648\u062A\u0627\u06A9\u0648\u0645\u062A\u0631 \u0628\u0631\u0627\u06CC \u0645\u062D\u0627\u0633\u0628\u0647\u200C\u06CC \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u0648 <strong>\u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0636\u0631\u0628\u0627\u0646 \u0628\u0647 \u0636\u0631\u0628\u0627\u0646</strong> \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F.</p>','<p><strong>\u0645\u0627\u0646\u06CC\u062A\u0648\u0631\u06CC\u0646\u06AF \u062E\u0627\u0631\u062C\u06CC:</strong> \u0646\u06CC\u0627\u0632\u06CC \u0628\u0647 \u067E\u0627\u0631\u06AF\u06CC \u067E\u0631\u062F\u0647\u200C\u0647\u0627 \u0646\u062F\u0627\u0631\u062F \u0627\u0645\u0627 \u062F\u0642\u062A \u06A9\u0645\u062A\u0631\u06CC \u0646\u0633\u0628\u062A \u0628\u0647 \u0645\u0627\u0646\u06CC\u062A\u0648\u0631\u06CC\u0646\u06AF \u062F\u0627\u062E\u0644\u06CC \u062F\u0627\u0631\u062F. \u0628\u0627 \u06CC\u06A9 \u0645\u0628\u062F\u0644 \u062F\u0627\u067E\u0644\u0631 \u0631\u0648\u06CC \u0634\u06A9\u0645 \u0645\u0627\u062F\u0631 (\u062A\u062B\u0628\u06CC\u062A\u200C\u0634\u062F\u0647 \u0628\u0627 \u06A9\u0645\u0631\u0628\u0646\u062F \u0648 \u0698\u0644)\u060C \u0627\u0645\u0648\u0627\u062C \u0627\u0648\u0644\u062A\u0631\u0627\u0633\u0648\u0646\u06CC\u06A9 \u0628\u0627\u0632\u062A\u0627\u0628\u06CC\u062F\u0647 \u0627\u0632 \u0642\u0644\u0628 \u062C\u0646\u06CC\u0646 \u062F\u0631\u06CC\u0627\u0641\u062A \u0648 \u0628\u0627 \u06CC\u06A9 \u0627\u0644\u06AF\u0648\u0631\u06CC\u062A\u0645 \u0645\u0642\u0627\u06CC\u0633\u0647\u200C\u0627\u06CC (<span class="en">autocorrelation</span>) \u067E\u0631\u062F\u0627\u0632\u0634 \u0645\u06CC\u200C\u0634\u0648\u062F \u062A\u0627 \u0627\u0632 \u062B\u0628\u062A \u0627\u0634\u062A\u0628\u0627\u0647 \u0636\u0631\u0628\u0627\u0646 \u0622\u0626\u0648\u0631\u062A \u0645\u0627\u062F\u0631 \u062C\u0644\u0648\u06AF\u06CC\u0631\u06CC \u0634\u0648\u062F.</p>'],figures:[{src:"figures/165_internal-fhr-monitoring.jpg",captionFa:"\u0645\u0627\u0646\u06CC\u062A\u0648\u0631\u06CC\u0646\u06AF \u062F\u0627\u062E\u0644\u06CC \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062C\u0646\u06CC\u0646 \u0628\u0627 \u0627\u0644\u06A9\u062A\u0631\u0648\u062F \u0645\u062A\u0635\u0644 \u0628\u0647 \u067E\u0648\u0633\u062A \u0633\u0631 \u062C\u0646\u06CC\u0646."},{src:"figures/165_external-fhr-monitoring.jpg",captionFa:"\u0645\u0627\u0646\u06CC\u062A\u0648\u0631\u06CC\u0646\u06AF \u062E\u0627\u0631\u062C\u06CC \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062C\u0646\u06CC\u0646 \u0628\u0627 \u0645\u0628\u062F\u0644 \u062F\u0627\u067E\u0644\u0631 \u0631\u0648\u06CC \u0634\u06A9\u0645 \u0645\u0627\u062F\u0631."},{src:"figures/165_fhr-variability-ecg-diagram.jpg",captionFa:"\u0646\u0645\u0627\u06CC \u0634\u0645\u0627\u062A\u06CC\u06A9 \u0645\u062D\u0627\u0633\u0628\u0647\u200C\u06CC \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u0627\u0632 \u0641\u0648\u0627\u0635\u0644 \u0632\u0645\u0627\u0646\u06CC (t1\u060C t2\u060C t3) \u0628\u06CC\u0646 \u0627\u0645\u0648\u0627\u062C R \u067E\u06CC\u0627\u067E\u06CC\u061B PAC = \u0627\u0646\u0642\u0628\u0627\u0636 \u067E\u06CC\u0634\u200C\u0631\u0633 \u062F\u0647\u0644\u06CC\u0632\u06CC."}]},{heading:"\u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u067E\u0627\u06CC\u0647: \u0628\u0631\u0627\u062F\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC \u0648 \u062A\u0627\u06A9\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC",paragraphsHtml:["<p><strong>\u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u067E\u0627\u06CC\u0647</strong> \u0645\u06CC\u0627\u0646\u06AF\u06CC\u0646 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u0637\u06CC \u06CC\u06A9 \u067E\u0646\u062C\u0631\u0647\u200C\u06CC \u06F1\u06F0 \u062F\u0642\u06CC\u0642\u0647\u200C\u0627\u06CC \u0627\u0633\u062A (\u0628\u0647 \u0641\u0627\u0635\u0644\u0647\u200C\u06CC \u06F5 \u0636\u0631\u0628\u0647 \u06AF\u0631\u062F \u0645\u06CC\u200C\u0634\u0648\u062F)\u060C \u0628\u0647 \u062F\u0648\u0631 \u0627\u0632 \u062A\u063A\u06CC\u06CC\u0631\u0627\u062A \u062F\u0648\u0631\u0647\u200C\u0627\u06CC \u0648 \u0628\u0627 \u062D\u062F\u0627\u0642\u0644 \u06F2 \u062F\u0642\u06CC\u0642\u0647 \u0637\u0648\u0644 \u0642\u0627\u0628\u0644\u200C\u062A\u0641\u0633\u06CC\u0631. \u0636\u0631\u0628\u0627\u0646 \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F1\u06F1\u06F0 \u0636\u0631\u0628\u0647 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647 \u0628\u0631\u0627\u062F\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC \u0648 \u0628\u06CC\u0634\u062A\u0631 \u0627\u0632 \u06F1\u06F6\u06F0 \u0636\u0631\u0628\u0647 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647 \u062A\u0627\u06A9\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC \u0645\u062D\u0633\u0648\u0628 \u0645\u06CC\u200C\u0634\u0648\u062F. \u0637\u06CC \u062D\u0627\u0645\u0644\u06AF\u06CC\u060C \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u067E\u0627\u06CC\u0647 \u0628\u0647\u200C\u0637\u0648\u0631 \u0637\u0628\u06CC\u0639\u06CC \u0647\u0631 \u0647\u0641\u062A\u0647 \u062D\u062F\u0648\u062F \u06CC\u06A9 \u0636\u0631\u0628\u0647 \u06A9\u0627\u0647\u0634 \u0645\u06CC\u200C\u06CC\u0627\u0628\u062F (\u06A9\u0627\u0647\u0634 \u06F2\u06F4 \u0636\u0631\u0628\u0647 \u0627\u0632 \u0647\u0641\u062A\u0647\u200C\u06CC \u06F1\u06F6 \u062A\u0627 \u062A\u0631\u0645) \u06A9\u0647 \u0628\u0647 \u0628\u0644\u0648\u063A \u062A\u062F\u0631\u06CC\u062C\u06CC \u0633\u06CC\u0633\u062A\u0645 \u067E\u0627\u0631\u0627\u0633\u0645\u067E\u0627\u062A\u06CC\u06A9 \u0646\u0633\u0628\u062A \u062F\u0627\u062F\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F.</p>",'<p>\u062A\u0627\u06A9\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC \u062E\u0641\u06CC\u0641 \u0628\u06CC\u0646 \u06F1\u06F6\u06F1 \u062A\u0627 \u06F1\u06F8\u06F0 \u0648 \u0634\u062F\u06CC\u062F \u0628\u06CC\u0634 \u0627\u0632 \u06F1\u06F8\u06F0 \u0636\u0631\u0628\u0647 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647 \u0627\u0633\u062A\u061B \u0634\u0627\u06CC\u0639\u200C\u062A\u0631\u06CC\u0646 \u0639\u0644\u062A \u0622\u0646 \u062A\u0628 \u0645\u0627\u062F\u0631 (\u0627\u063A\u0644\u0628 \u0646\u0627\u0634\u06CC \u0627\u0632 \u0622\u0645\u0646\u06CC\u0648\u0646\u06CC\u062A) \u0627\u0633\u062A. \u0628\u0631\u0627\u062F\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC \u0628\u06CC\u0646 \u06F1\u06F0\u06F0 \u062A\u0627 \u06F1\u06F1\u06F9 \u0636\u0631\u0628\u0647 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647 \u0628\u062F\u0648\u0646 \u0633\u0627\u06CC\u0631 \u062A\u063A\u06CC\u06CC\u0631\u0627\u062A\u060C \u0645\u0639\u0645\u0648\u0644\u0627\u064B \u0628\u06CC\u200C\u062E\u0637\u0631 \u0627\u0633\u062A \u0648 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u062F \u0646\u0627\u0634\u06CC \u0627\u0632 \u0641\u0634\u0627\u0631 \u0631\u0648\u06CC \u0633\u0631 \u062F\u0631 \u0648\u0636\u0639\u06CC\u062A\u200C\u0647\u0627\u06CC <span class="en">OP</span> \u06CC\u0627 \u0639\u0631\u0636\u06CC \u0628\u0647\u200C\u062E\u0635\u0648\u0635 \u062F\u0631 \u0645\u0631\u062D\u0644\u0647\u200C\u06CC \u062F\u0648\u0645 \u0628\u0627\u0634\u062F. \u06F8\u06F0 \u062A\u0627 \u06F1\u06F2\u06F0 \u0636\u0631\u0628\u0647 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647 \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u062E\u0648\u0628 \u0627\u0637\u0645\u06CC\u0646\u0627\u0646\u200C\u0628\u062E\u0634 \u0627\u0633\u062A\u061B \u0633\u0627\u06CC\u0631 \u0639\u0644\u0644 \u0628\u0631\u0627\u062F\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC \u0634\u0627\u0645\u0644 \u0628\u0644\u0648\u06A9 \u0642\u0644\u0628\u06CC \u0645\u0627\u062F\u0631\u0632\u0627\u062F\u06CC\u060C \u0628\u062F\u062D\u0627\u0644\u06CC \u0634\u062F\u06CC\u062F \u062C\u0646\u06CC\u0646\u060C \u0647\u06CC\u067E\u0648\u062A\u0631\u0645\u06CC \u06CC\u0627 \u067E\u06CC\u0644\u0648\u0646\u0641\u0631\u06CC\u062A \u0645\u0627\u062F\u0631 \u0627\u0633\u062A.</p>'],table:{caption:"\u062E\u0644\u0627\u0635\u0647\u200C\u06CC \u062A\u0639\u0627\u0631\u06CC\u0641 NICHD \u0628\u0631\u0627\u06CC \u0627\u0644\u06AF\u0648\u0647\u0627\u06CC \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062C\u0646\u06CC\u0646",headers:["\u0627\u0644\u06AF\u0648","\u062A\u0639\u0631\u06CC\u0641 \u062E\u0644\u0627\u0635\u0647"],rows:[["\u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u067E\u0627\u06CC\u0647","\u0645\u06CC\u0627\u0646\u06AF\u06CC\u0646 FHR \u0637\u06CC \u06F1\u06F0 \u062F\u0642\u06CC\u0642\u0647\u060C \u06AF\u0631\u062F\u0634\u062F\u0647 \u0628\u0647 \u0645\u0636\u0631\u0628 \u06F5 bpm"],["\u0628\u0631\u0627\u062F\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC","\u0636\u0631\u0628\u0627\u0646 \u067E\u0627\u06CC\u0647 \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F1\u06F1\u06F0 bpm"],["\u062A\u0627\u06A9\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC","\u0636\u0631\u0628\u0627\u0646 \u067E\u0627\u06CC\u0647 \u0628\u06CC\u0634\u062A\u0631 \u0627\u0632 \u06F1\u06F6\u06F0 bpm"],["\u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u067E\u0627\u06CC\u0647","\u0646\u0648\u0633\u0627\u0646\u0627\u062A \u2265 \u06F2 \u0633\u06CC\u06A9\u0644/\u062F\u0642\u06CC\u0642\u0647\u061B \u0641\u0642\u062F\u0627\u0646 (\u063A\u06CC\u0631\u0642\u0627\u0628\u0644\u200C\u06A9\u0634\u0641)\u060C \u062C\u0632\u0626\u06CC (\u2264\u06F5 bpm)\u060C \u0645\u062A\u0648\u0633\u0637/\u0637\u0628\u06CC\u0639\u06CC (\u06F6 \u062A\u0627 \u06F2\u06F5 bpm)\u060C \u0634\u062F\u06CC\u062F (>\u06F2\u06F5 bpm)"],["\u062A\u0633\u0631\u06CC\u0639 (Acceleration)","\u0627\u0641\u0632\u0627\u06CC\u0634 \u2265\u06F1\u06F5 bpm \u0628\u0647 \u0645\u062F\u062A \u2265\u06F1\u06F5 \u062B\u0627\u0646\u06CC\u0647 \u0627\u0645\u0627 <\u06F2 \u062F\u0642\u06CC\u0642\u0647 (\u0628\u0639\u062F \u0627\u0632 \u0647\u0641\u062A\u0647\u200C\u06CC \u06F3\u06F2\u061B \u0642\u0628\u0644 \u0627\u0632 \u0622\u0646 \u2265\u06F1\u06F0 bpm \u0648 \u2265\u06F1\u06F0 \u062B\u0627\u0646\u06CC\u0647)"],["\u0627\u0641\u062A \u0632\u0648\u062F\u0631\u0633","\u062A\u062F\u0631\u06CC\u062C\u06CC\u060C \u0647\u0645\u200C\u0632\u0645\u0627\u0646 \u0628\u0627 \u0634\u0631\u0648\u0639/\u0627\u0648\u062C/\u067E\u0627\u06CC\u0627\u0646 \u0627\u0646\u0642\u0628\u0627\u0636"],["\u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633","\u062A\u062F\u0631\u06CC\u062C\u06CC\u060C \u0634\u0631\u0648\u0639/\u062D\u062F\u0627\u0642\u0644/\u0628\u0627\u0632\u06AF\u0634\u062A \u067E\u0633 \u0627\u0632 \u0634\u0631\u0648\u0639/\u0627\u0648\u062C/\u067E\u0627\u06CC\u0627\u0646 \u0627\u0646\u0642\u0628\u0627\u0636"],["\u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631","\u0634\u0631\u0648\u0639 \u0646\u0627\u06AF\u0647\u0627\u0646\u06CC (<\u06F3\u06F0 \u062B\u0627\u0646\u06CC\u0647)\u060C \u06A9\u0627\u0647\u0634 \u2265\u06F1\u06F5 bpm \u0628\u0647 \u0645\u062F\u062A \u2265\u06F1\u06F5 \u062B\u0627\u0646\u06CC\u0647 \u0627\u0645\u0627 <\u06F2 \u062F\u0642\u06CC\u0642\u0647"],["\u0627\u0641\u062A \u0637\u0648\u0644\u0627\u0646\u06CC\u200C\u0645\u062F\u062A","\u06A9\u0627\u0647\u0634 \u2265\u06F1\u06F5 bpm \u0628\u0647 \u0645\u062F\u062A \u2265\u06F2 \u062F\u0642\u06CC\u0642\u0647 \u0627\u0645\u0627 <\u06F1\u06F0 \u062F\u0642\u06CC\u0642\u0647"]]}},{heading:"\u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0636\u0631\u0628\u0627\u0646 \u0628\u0647 \u0636\u0631\u0628\u0627\u0646 \u0648 \u0622\u0631\u06CC\u062A\u0645\u06CC",paragraphsHtml:["<p>\u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u067E\u0627\u06CC\u0647\u200C\u0627\u06CC \u0646\u0634\u0627\u0646\u06AF\u0631 \u0645\u0647\u0645 \u0639\u0645\u0644\u06A9\u0631\u062F \u0642\u0644\u0628\u06CC\u200C\u0639\u0631\u0648\u0642\u06CC \u062C\u0646\u06CC\u0646 \u0627\u0633\u062A \u0648 \u0639\u0645\u062F\u062A\u0627\u064B \u062A\u062D\u062A \u06A9\u0646\u062A\u0631\u0644 \u0633\u06CC\u0633\u062A\u0645 \u0627\u062A\u0648\u0646\u0648\u0645 \u0627\u0633\u062A. <strong>\u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u06A9\u0648\u062A\u0627\u0647\u200C\u0645\u062F\u062A</strong> \u062A\u063A\u06CC\u06CC\u0631 \u0644\u062D\u0638\u0647\u200C\u0627\u06CC \u0628\u06CC\u0646 \u0645\u0648\u062C\u200C\u0647\u0627\u06CC R \u067E\u06CC\u0627\u067E\u06CC \u0627\u0633\u062A \u0648 \u062A\u0646\u0647\u0627 \u0628\u0627 \u0627\u0644\u06A9\u062A\u0631\u0648\u062F \u0645\u062A\u0635\u0644 \u0628\u0647 \u0633\u0631 \u062C\u0646\u06CC\u0646 \u0642\u0627\u0628\u0644 \u062A\u0639\u06CC\u06CC\u0646 \u0627\u0633\u062A. <strong>\u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u062F\u0631\u0627\u0632\u0645\u062F\u062A</strong> \u0646\u0648\u0633\u0627\u0646\u0627\u062A \u0638\u0631\u0641 \u06CC\u06A9 \u062F\u0642\u06CC\u0642\u0647 \u0628\u0627 \u0641\u0631\u06A9\u0627\u0646\u0633 \u0637\u0628\u06CC\u0639\u06CC \u06F3 \u062A\u0627 \u06F5 \u0633\u06CC\u06A9\u0644 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647 \u0627\u0633\u062A.</p>","<p>\u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0637\u0628\u06CC\u0639\u06CC \u06F6 \u062A\u0627 \u06F2\u06F5 \u0636\u0631\u0628\u0647 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647 \u0627\u0633\u062A. \u06A9\u0627\u0647\u0634 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0645\u0639\u0645\u0648\u0644\u0627\u064B \u0645\u0646\u0639\u06A9\u0633\u200C\u06A9\u0646\u0646\u062F\u0647\u200C\u06CC \u0627\u0633\u06CC\u062F\u0645\u06CC (\u0646\u0647 \u0635\u0631\u0641\u0627\u064B \u0647\u06CC\u067E\u0648\u06A9\u0633\u06CC) \u0627\u0633\u062A\u060C \u0632\u06CC\u0631\u0627 \u0646\u0627\u0634\u06CC \u0627\u0632 \u0627\u062B\u0631 \u0645\u0647\u0627\u0631\u06CC \u0627\u0633\u06CC\u062F\u0648\u0632 \u0645\u062A\u0627\u0628\u0648\u0644\u06CC\u06A9 \u0631\u0648\u06CC \u0633\u0627\u0642\u0647\u200C\u06CC \u0645\u063A\u0632 \u06CC\u0627 \u062E\u0648\u062F \u0642\u0644\u0628 \u0627\u0633\u062A. \u0639\u0644\u0644 \u0634\u0627\u06CC\u0639 \u06A9\u0627\u0647\u0634 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0634\u0627\u0645\u0644 \u062F\u0627\u0631\u0648\u0647\u0627\u06CC \u0636\u062F\u062F\u0631\u062F \u0632\u0627\u06CC\u0645\u0627\u0646\u06CC (\u0646\u0627\u0631\u06A9\u0648\u062A\u06CC\u06A9\u200C\u0647\u0627\u060C \u0628\u0627\u0631\u0628\u06CC\u062A\u0648\u0631\u0627\u062A\u200C\u0647\u0627\u060C \u0641\u0646\u0648\u062A\u06CC\u0627\u0632\u06CC\u0646\u200C\u0647\u0627\u060C \u0622\u0631\u0627\u0645\u200C\u0628\u062E\u0634\u200C\u0647\u0627\u060C \u0628\u06CC\u0647\u0648\u0634\u200C\u06A9\u0646\u0646\u062F\u0647\u200C\u0647\u0627\u06CC \u0639\u0645\u0648\u0645\u06CC)\u060C \u0633\u0648\u0644\u0641\u0627\u062A \u0645\u0646\u06CC\u0632\u06CC\u0645\u060C \u0648 \u062E\u0648\u0627\u0628 \u062C\u0646\u06CC\u0646 \u0627\u0633\u062A.</p>","<p><strong>\u0622\u0631\u06CC\u062A\u0645\u06CC \u0642\u0644\u0628 \u062C\u0646\u06CC\u0646</strong> \u0645\u0645\u06A9\u0646 \u0627\u0633\u062A \u0628\u0647\u200C\u0635\u0648\u0631\u062A \u0628\u0631\u0627\u062F\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC\u060C \u062A\u0627\u06A9\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC \u06CC\u0627 \u0634\u0627\u06CC\u0639\u200C\u062A\u0631 spiking \u0646\u0627\u06AF\u0647\u0627\u0646\u06CC \u0628\u0631\u0648\u0632 \u06A9\u0646\u062F. \u0634\u0627\u06CC\u0639\u200C\u062A\u0631\u06CC\u0646 \u0639\u0644\u062A \u0627\u06A9\u0633\u062A\u0631\u0627\u0633\u06CC\u0633\u062A\u0648\u0644 \u062F\u0647\u0644\u06CC\u0632\u06CC \u0627\u0633\u062A\u061B \u0627\u06A9\u0633\u062A\u0631\u0627\u0633\u06CC\u0633\u062A\u0648\u0644 \u0628\u0637\u0646\u06CC \u0646\u0642\u0634 \u06A9\u0645\u062A\u0631\u06CC \u062F\u0627\u0631\u062F. \u0628\u06CC\u0634\u062A\u0631 \u0622\u0631\u06CC\u062A\u0645\u06CC\u200C\u0647\u0627\u06CC \u0641\u0648\u0642\u200C\u0628\u0637\u0646\u06CC \u062E\u0648\u0634\u200C\u062E\u06CC\u0645 \u0647\u0633\u062A\u0646\u062F \u0645\u06AF\u0631 \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u0646\u0627\u0631\u0633\u0627\u06CC\u06CC \u0642\u0644\u0628\u06CC \u0646\u0627\u0634\u06CC \u0627\u0632 \u0647\u06CC\u062F\u0631\u0648\u067E\u0633 \u0628\u0627\u0634\u0646\u062F.</p>"],figures:[{src:"figures/167_short-term-variability-graph.jpg",captionFa:"\u0646\u0645\u0627\u06CC \u0634\u0645\u0627\u062A\u06CC\u06A9 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0636\u0631\u0628\u0627\u0646 \u0628\u0647 \u0636\u0631\u0628\u0627\u0646 \u062F\u0631 \u06A9\u0648\u062A\u0627\u0647\u200C\u0645\u062F\u062A."},{src:"figures/167_long-term-variability-graph.jpg",captionFa:"\u0646\u0645\u0627\u06CC \u0634\u0645\u0627\u062A\u06CC\u06A9 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0636\u0631\u0628\u0627\u0646 \u0628\u0647 \u0636\u0631\u0628\u0627\u0646 \u062F\u0631 \u062F\u0631\u0627\u0632\u0645\u062F\u062A."},{src:"figures/168_fhr-variability-degrees-1-5.jpg",captionFa:"\u062F\u0631\u062C\u0627\u062A \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u067E\u0627\u06CC\u0647\u200C\u0627\u06CC \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628: \u06F1) \u0641\u0642\u062F\u0627\u0646 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC\u060C \u06F2) \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u062C\u0632\u0626\u06CC (<\u06F5 bpm)\u060C \u06F3) \u0645\u062A\u0648\u0633\u0637 (\u06F6 \u062A\u0627 \u06F2\u06F5 bpm)\u060C \u06F4) \u0634\u062F\u06CC\u062F (>\u06F2\u06F5 bpm)\u060C \u06F5) \u0646\u0645\u0627\u06CC \u0633\u06CC\u0646\u0648\u0633\u06CC."},{src:"figures/169_arrhythmia-spiking-tracing.jpg",captionFa:"\u0646\u0648\u0627\u0631 \u0645\u0627\u0646\u06CC\u062A\u0648\u0631\u06CC\u0646\u06AF \u062F\u0627\u062E\u0644\u06CC \u0628\u0627 \u0627\u0633\u067E\u0627\u06CC\u06A9\u200C\u0647\u0627\u06CC \u0646\u0627\u06AF\u0647\u0627\u0646\u06CC \u0636\u0631\u0628\u0647\u200C\u0628\u0647\u200C\u0636\u0631\u0628\u0647 \u0646\u0627\u0634\u06CC \u0627\u0632 \u0627\u06A9\u0633\u062A\u0631\u0627\u0633\u06CC\u0633\u062A\u0648\u0644\u200C\u0647\u0627\u06CC \u062F\u0647\u0644\u06CC\u0632\u06CC\u061B \u0632\u0627\u06CC\u0645\u0627\u0646 \u0648 \u0631\u06CC\u062A\u0645 \u0642\u0644\u0628 \u0646\u0648\u0632\u0627\u062F \u0637\u0628\u06CC\u0639\u06CC \u0628\u0648\u062F."}],callouts:[{kind:"key",label:"\u062F\u0631\u062C\u0627\u062A \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u067E\u0627\u06CC\u0647",html:"<p>\u0641\u0642\u062F\u0627\u0646: \u063A\u06CC\u0631\u0642\u0627\u0628\u0644\u200C\u06A9\u0634\u0641. \u062C\u0632\u0626\u06CC: \u0642\u0627\u0628\u0644\u200C\u06A9\u0634\u0641 \u0627\u0645\u0627 \u2264\u06F5 \u0636\u0631\u0628\u0647 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647. \u0645\u062A\u0648\u0633\u0637 (\u0637\u0628\u06CC\u0639\u06CC): \u06F6 \u062A\u0627 \u06F2\u06F5 \u0636\u0631\u0628\u0647 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647. \u0634\u062F\u06CC\u062F: \u0628\u06CC\u0634 \u0627\u0632 \u06F2\u06F5 \u0636\u0631\u0628\u0647 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647. \u06A9\u0627\u0647\u0634 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0642\u0627\u0628\u0644\u200C\u0627\u0639\u062A\u0645\u0627\u062F\u062A\u0631\u06CC\u0646 \u0639\u0644\u0627\u0645\u062A \u0628\u062F\u062D\u0627\u0644\u06CC \u062C\u0646\u06CC\u0646 \u062A\u0644\u0642\u06CC \u0645\u06CC\u200C\u0634\u0648\u062F.</p>"}]},{heading:"\u0627\u0644\u06AF\u0648\u06CC \u0633\u06CC\u0646\u0648\u0633\u06CC \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628",paragraphsHtml:["<p>\u0627\u0644\u06AF\u0648\u06CC \u0633\u06CC\u0646\u0648\u0633\u06CC \u0648\u0627\u0642\u0639\u06CC \u0628\u0627 \u0646\u0648\u0633\u0627\u0646\u0627\u062A \u0645\u0646\u0638\u0645 \u0648 \u0635\u0627\u0641 \u0628\u0627 \u062A\u0648\u0627\u062A\u0631 \u06F2 \u062A\u0627 \u06F5 \u0633\u06CC\u06A9\u0644 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647\u060C \u062F\u0627\u0645\u0646\u0647\u200C\u06CC \u06F5 \u062A\u0627 \u06F1\u06F5 \u0636\u0631\u0628\u0647 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647\u060C \u0641\u0642\u062F\u0627\u0646 \u062A\u0633\u0631\u06CC\u0639\u060C \u0648 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u06A9\u0648\u062A\u0627\u0647\u200C\u0645\u062F\u062A \u062B\u0627\u0628\u062A \u06CC\u0627 \u0645\u062E\u062A\u0635\u0631 \u0645\u0634\u062E\u0635 \u0645\u06CC\u200C\u0634\u0648\u062F \u0648 \u0628\u0627\u06CC\u062F \u0627\u0632 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0645\u0639\u0645\u0648\u0644\u06CC \u0627\u0641\u062A\u0631\u0627\u0642 \u062F\u0627\u062F\u0647 \u0634\u0648\u062F. \u0627\u06CC\u0646 \u0627\u0644\u06AF\u0648 \u062F\u0631 \u0622\u0646\u0645\u06CC \u0634\u062F\u06CC\u062F \u062C\u0646\u06CC\u0646\u060C \u0627\u06CC\u0632\u0648\u0627\u06CC\u0645\u0648\u0646\u06CC\u0632\u0627\u0633\u06CC\u0648\u0646 D\u060C \u067E\u0627\u0631\u06AF\u06CC \u0631\u06AF \u0633\u0631\u0631\u0627\u0647\u06CC\u060C \u062E\u0648\u0646\u0631\u06CC\u0632\u06CC \u062C\u0646\u06CC\u0646 \u0628\u0647 \u0645\u0627\u062F\u0631 \u06CC\u0627 \u0642\u0644\u200C\u0628\u0647\u200C\u0642\u0644\u060C \u0622\u0645\u0646\u06CC\u0648\u0646\u06CC\u062A\u060C \u062F\u06CC\u0633\u062A\u0631\u0633 \u062C\u0646\u06CC\u0646 \u0648 \u0627\u0646\u0633\u062F\u0627\u062F \u06A9\u0648\u0631\u062F \u062F\u06CC\u062F\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F\u061B \u0647\u0645\u0686\u0646\u06CC\u0646 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u062F \u0628\u0647\u200C\u062F\u0646\u0628\u0627\u0644 \u062A\u062C\u0648\u06CC\u0632 \u0645\u067E\u0631\u06CC\u062F\u06CC\u0646\u060C \u0645\u0648\u0631\u0641\u06CC\u0646\u060C \u0622\u0644\u0641\u0627\u067E\u0631\u0648\u062F\u06CC\u0646 \u06CC\u0627 \u0628\u0648\u062A\u0648\u0631\u0641\u0627\u0646\u0648\u0644 \u0628\u0647 \u0645\u0627\u062F\u0631 \u0631\u062E \u062F\u0647\u062F (\u062F\u0631 \u0627\u06CC\u0646 \u062D\u0627\u0644\u062A \u062A\u0648\u0627\u062A\u0631 \u0627\u0645\u0648\u0627\u062C \u0645\u0639\u0645\u0648\u0644\u0627\u064B \u06F6 \u0633\u06CC\u06A9\u0644 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647 \u0627\u0633\u062A).</p>"],figures:[{src:"figures/170_sinusoidal-fhr-tracing.jpg",captionFa:"\u0646\u0645\u0627\u06CC \u0633\u06CC\u0646\u0648\u0632\u0648\u0626\u06CC\u062F\u0627\u0644 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062C\u0646\u06CC\u0646 \u0646\u0627\u0634\u06CC \u0627\u0632 \u062A\u062C\u0648\u06CC\u0632 \u0645\u067E\u0631\u06CC\u062F\u06CC\u0646 \u0628\u0647 \u0645\u0627\u062F\u0631\u061B \u0627\u0645\u0648\u0627\u062C \u0633\u06CC\u0646\u0648\u0633\u06CC \u0628\u0627 \u0633\u0631\u0639\u062A \u062D\u062F\u0648\u062F \u06F6 \u0633\u06CC\u06A9\u0644 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647."}]},{heading:"\u062A\u063A\u06CC\u06CC\u0631\u0627\u062A \u062F\u0648\u0631\u0647\u200C\u0627\u06CC: \u0627\u0641\u062A \u0632\u0648\u062F\u0631\u0633\u060C \u062F\u06CC\u0631\u0631\u0633\u060C \u0645\u062A\u063A\u06CC\u0631 \u0648 \u0637\u0648\u0644\u0627\u0646\u06CC\u200C\u0645\u062F\u062A",paragraphsHtml:["<p><strong>\u062A\u0633\u0631\u06CC\u0639 \u0636\u0631\u0628\u0627\u0646 (Acceleration):</strong> \u0627\u0641\u0632\u0627\u06CC\u0634 \u0646\u0627\u06AF\u0647\u0627\u0646\u06CC \u0648 \u0648\u0627\u0636\u062D \u0636\u0631\u0628\u0627\u0646 \u0627\u0632 \u062E\u0637 \u067E\u0627\u06CC\u0647 \u0627\u0633\u062A. \u062A\u0642\u0631\u06CC\u0628\u0627\u064B \u0647\u0645\u06CC\u0634\u0647 \u062F\u0627\u0644 \u0628\u0631 \u0633\u0644\u0627\u0645\u062A \u062C\u0646\u06CC\u0646 \u0648 \u0639\u062F\u0645 \u0627\u0633\u06CC\u062F\u0645\u06CC \u0627\u0633\u062A. \u0641\u0642\u062F\u0627\u0646 \u062A\u0633\u0631\u06CC\u0639 \u062F\u0631 \u0646\u0628\u0648\u062F \u0633\u0627\u06CC\u0631 \u06CC\u0627\u0641\u062A\u0647\u200C\u0647\u0627\u06CC \u063A\u06CC\u0631\u0639\u0627\u062F\u06CC \u0628\u0647\u200C\u062A\u0646\u0647\u0627\u06CC\u06CC \u0645\u0634\u06A9\u0644\u200C\u0633\u0627\u0632 \u0646\u06CC\u0633\u062A\u060C \u0627\u0645\u0627 \u062F\u0631 \u06A9\u0646\u0627\u0631 \u06CC\u06A9 \u0627\u0644\u06AF\u0648\u06CC \u0646\u0627\u0645\u0637\u0645\u0626\u0646 \u062F\u06CC\u06AF\u0631\u060C \u0634\u0627\u0646\u0633 \u0627\u0633\u06CC\u062F\u0645\u06CC \u0631\u0627 \u062A\u0627 \u06F5\u06F0\u066A \u0627\u0641\u0632\u0627\u06CC\u0634 \u0645\u06CC\u200C\u062F\u0647\u062F.</p>","<p><strong>\u0627\u0641\u062A \u0632\u0648\u062F\u0631\u0633 (Early deceleration):</strong> \u06A9\u0627\u0647\u0634 \u062A\u062F\u0631\u06CC\u062C\u06CC \u0648 \u0645\u062A\u0642\u0627\u0631\u0646 \u0636\u0631\u0628\u0627\u0646 \u06A9\u0647 \u0628\u0627 \u0634\u0631\u0648\u0639/\u0627\u0648\u062C/\u067E\u0627\u06CC\u0627\u0646 \u0627\u0646\u0642\u0628\u0627\u0636 \u0647\u0645\u200C\u0632\u0645\u0627\u0646 \u0627\u0633\u062A. \u0645\u0639\u0645\u0648\u0644\u0627\u064B \u062F\u0631 \u062F\u06CC\u0644\u0627\u062A\u0627\u0633\u06CC\u0648\u0646 \u06F4 \u062A\u0627 \u06F7 \u0633\u0627\u0646\u062A\u06CC\u200C\u0645\u062A\u0631 \u062F\u06CC\u062F\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F \u0648 \u0645\u06A9\u0627\u0646\u06CC\u0633\u0645 \u0622\u0646 \u0641\u0634\u0627\u0631 \u0628\u0647 \u0633\u0631 \u0648 \u062A\u062D\u0631\u06CC\u06A9 \u0648\u0627\u06AF \u0627\u0632 \u0637\u0631\u06CC\u0642 \u062A\u062D\u0631\u06CC\u06A9 \u062F\u0648\u0631\u0627 \u0627\u0633\u062A\u061B \u0641\u06CC\u0632\u06CC\u0648\u0644\u0648\u0698\u06CC\u06A9 \u062A\u0644\u0642\u06CC \u0645\u06CC\u200C\u0634\u0648\u062F \u0648 \u0628\u0627 \u0647\u06CC\u067E\u0648\u06A9\u0633\u06CC\u060C \u0627\u0633\u06CC\u062F\u0645\u06CC \u06CC\u0627 \u0622\u067E\u06AF\u0627\u0631 \u067E\u0627\u06CC\u06CC\u0646 \u0647\u0645\u0631\u0627\u0647 \u0646\u06CC\u0633\u062A.</p>","<p><strong>\u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633 (Late deceleration):</strong> \u06A9\u0627\u0647\u0634 \u062A\u062F\u0631\u06CC\u062C\u06CC \u0648 \u0645\u062A\u0642\u0627\u0631\u0646 \u06A9\u0647 \u0634\u0631\u0648\u0639\u060C \u062D\u062F\u0627\u0642\u0644 \u0648 \u0628\u0627\u0632\u06AF\u0634\u062A \u0622\u0646 \u0628\u0647\u200C\u062A\u0631\u062A\u06CC\u0628 \u067E\u0633 \u0627\u0632 \u0634\u0631\u0648\u0639\u060C \u0627\u0648\u062C \u0648 \u067E\u0627\u06CC\u0627\u0646 \u0627\u0646\u0642\u0628\u0627\u0636 \u0631\u062E \u0645\u06CC\u200C\u062F\u0647\u062F. \u0627\u06CC\u0646 \u0627\u0644\u06AF\u0648 \u067E\u0627\u0633\u062E \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u0628\u0647 \u06A9\u0627\u0647\u0634 \u0627\u06A9\u0633\u06CC\u0698\u0646\u0627\u0633\u06CC\u0648\u0646 \u0627\u0632 \u0637\u0631\u06CC\u0642 \u0648\u0627\u062D\u062F \u0631\u062D\u0645\u06CC-\u062C\u0641\u062A\u06CC \u0627\u0633\u062A \u0648 \u0627\u0648\u0644\u06CC\u0646 \u067E\u06CC\u0627\u0645\u062F \u0647\u06CC\u067E\u0648\u06A9\u0633\u06CC \u062C\u0646\u06CC\u0646\u06CC \u0646\u0627\u0634\u06CC \u0627\u0632 \u0646\u0627\u0631\u0633\u0627\u06CC\u06CC \u062C\u0641\u062A\u06CC \u0645\u062D\u0633\u0648\u0628 \u0645\u06CC\u200C\u0634\u0648\u062F. \u0634\u0627\u06CC\u0639\u200C\u062A\u0631\u06CC\u0646 \u0639\u0644\u0644 \u0622\u0646 \u0647\u06CC\u067E\u0648\u062A\u0627\u0646\u0633\u06CC\u0648\u0646 \u0646\u0627\u0634\u06CC \u0627\u0632 \u0628\u06CC\u200C\u062D\u0633\u06CC \u0627\u067E\u06CC\u062F\u0648\u0631\u0627\u0644 \u0648 \u0647\u06CC\u067E\u0631\u0627\u06A9\u062A\u06CC\u0648\u06CC\u062A\u06CC \u0631\u062D\u0645 \u0646\u0627\u0634\u06CC \u0627\u0632 \u0627\u06A9\u0633\u06CC\u200C\u062A\u0648\u0633\u06CC\u0646 \u0627\u0633\u062A\u061B \u06A9\u0646\u062F\u06AF\u06CC \u062C\u0641\u062A \u0646\u06CC\u0632 \u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633 \u062D\u0627\u062F \u0627\u06CC\u062C\u0627\u062F \u0645\u06CC\u200C\u06A9\u0646\u062F.</p>","<p><strong>\u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631 (Variable deceleration):</strong> \u0634\u0627\u06CC\u0639\u200C\u062A\u0631\u06CC\u0646 \u0646\u0648\u0639 \u06A9\u0646\u062F\u06CC \u062D\u06CC\u0646 \u0632\u0627\u06CC\u0645\u0627\u0646 \u0627\u0633\u062A \u0648 \u0628\u0647 \u0627\u0646\u0633\u062F\u0627\u062F \u0628\u0646\u062F\u0646\u0627\u0641 \u0646\u0633\u0628\u062A \u062F\u0627\u062F\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F (\u062F\u0631 \u06CC\u06A9 \u0645\u0637\u0627\u0644\u0639\u0647 \u062F\u0631 \u06F8\u06F3\u066A \u0632\u0627\u06CC\u0645\u0627\u0646\u200C\u0647\u0627 \u0628\u0627 \u062F\u06CC\u0644\u0627\u062A\u0627\u0633\u06CC\u0648\u0646 \u06F5cm \u062F\u06CC\u062F\u0647 \u0634\u062F). \u0634\u0631\u0648\u0639 \u0646\u0627\u06AF\u0647\u0627\u0646\u06CC \u062F\u0627\u0631\u062F\u060C \u0628\u0627 \u0632\u0645\u0627\u0646 \u0627\u0646\u0642\u0628\u0627\u0636 \u0627\u0631\u062A\u0628\u0627\u0637 \u062B\u0627\u0628\u062A\u06CC \u0646\u062F\u0627\u0631\u062F \u0648 \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F2 \u062F\u0642\u06CC\u0642\u0647 \u0637\u0648\u0644 \u0645\u06CC\u200C\u06A9\u0634\u062F. \u0645\u06A9\u0627\u0646\u06CC\u0633\u0645 \u0622\u0646 \u062A\u062D\u0631\u06CC\u06A9 \u0628\u0627\u0631\u0648\u0631\u0633\u067E\u062A\u0648\u0631 (\u0641\u0634\u0627\u0631 \u062E\u0648\u0646 \u0628\u0627\u0644\u0627\u06CC \u0645\u0648\u0636\u0639\u06CC \u0628\u0647\u200C\u062F\u0646\u0628\u0627\u0644 \u0627\u0646\u0633\u062F\u0627\u062F \u06A9\u0627\u0645\u0644 \u06A9\u0648\u0631\u062F) \u0648 \u0633\u067E\u0633 \u06A9\u0645\u0648\u0633\u0631\u067E\u062A\u0648\u0631 \u0627\u0632 \u0637\u0631\u06CC\u0642 \u0639\u0635\u0628 \u0648\u0627\u06AF \u0627\u0633\u062A. \u0646\u0648\u0639 \u062E\u0637\u06CC\u0631 \u0622\u0646 \u0648\u0642\u062A\u06CC \u0627\u0633\u062A \u06A9\u0647 \u0636\u0631\u0628\u0627\u0646 \u0628\u0647 \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F7\u06F0 \u0636\u0631\u0628\u0647 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647 \u0628\u0631\u0633\u062F \u0648 \u0628\u06CC\u0634 \u0627\u0632 \u06F6\u06F0 \u062B\u0627\u0646\u06CC\u0647 \u0628\u0627\u0642\u06CC \u0628\u0645\u0627\u0646\u062F.</p>","<p><strong>\u0627\u0641\u062A \u0637\u0648\u0644\u0627\u0646\u06CC\u200C\u0645\u062F\u062A (Prolonged deceleration):</strong> \u06A9\u0646\u062F\u06CC \u0628\u0647 \u0645\u062F\u062A \u2265\u06F2 \u0627\u0645\u0627 <\u06F1\u06F0 \u062F\u0642\u06CC\u0642\u0647 \u0627\u0633\u062A \u0648 \u062A\u0641\u0633\u06CC\u0631 \u0622\u0646 \u062F\u0634\u0648\u0627\u0631 \u0627\u0633\u062A \u0632\u06CC\u0631\u0627 \u062F\u0631 \u0634\u0631\u0627\u06CC\u0637 \u0628\u0627\u0644\u06CC\u0646\u06CC \u0645\u062A\u0646\u0648\u0639\u06CC \u0631\u062E \u0645\u06CC\u200C\u062F\u0647\u062F: \u0645\u0639\u0627\u06CC\u0646\u0647\u200C\u06CC \u0633\u0631\u0648\u06CC\u06A9\u0633\u060C \u0628\u06CC\u0634\u200C\u0641\u0639\u0627\u0644\u06CC \u0631\u062D\u0645\u060C \u0647\u06CC\u067E\u0648\u062A\u0627\u0646\u0633\u06CC\u0648\u0646 \u0645\u0627\u062F\u0631 \u062F\u0631 \u0648\u0636\u0639\u06CC\u062A \u062E\u0648\u0627\u0628\u06CC\u062F\u0647 \u0628\u0647 \u067E\u0634\u062A\u060C \u0628\u06CC\u200C\u062D\u0633\u06CC \u0627\u0633\u067E\u06CC\u0646\u0627\u0644/\u0627\u067E\u06CC\u062F\u0648\u0631\u0627\u0644/\u067E\u0627\u0631\u0627\u0633\u0631\u0648\u06CC\u06A9\u0627\u0644\u060C \u06A9\u0646\u062F\u06AF\u06CC \u062C\u0641\u062A\u060C \u06AF\u0631\u0647 \u06CC\u0627 \u067E\u0631\u0648\u0644\u0627\u067E\u0633 \u0628\u0646\u062F\u0646\u0627\u0641\u060C \u0648 \u062A\u0634\u0646\u062C \u0645\u0627\u062F\u0631.</p>"],figures:[{src:"figures/170_early-deceleration-schematic.jpg",captionFa:"\u0646\u0645\u0648\u062F\u0627\u0631 \u0634\u0645\u0627\u062A\u06CC\u06A9 \u0627\u0641\u062A \u0632\u0648\u062F\u0631\u0633 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628: \u06A9\u0627\u0647\u0634 \u062A\u062F\u0631\u06CC\u062C\u06CC \u0647\u0645\u200C\u0632\u0645\u0627\u0646 \u0628\u0627 \u0634\u0631\u0648\u0639 \u0648 \u067E\u0627\u06CC\u0627\u0646 \u0627\u0646\u0642\u0628\u0627\u0636."},{src:"figures/171_late-deceleration-schematic.jpg",captionFa:"\u0646\u0645\u0648\u062F\u0627\u0631 \u0634\u0645\u0627\u062A\u06CC\u06A9 \u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628: \u0634\u0631\u0648\u0639\u060C \u062D\u062F\u0627\u0642\u0644 \u0648 \u0628\u0627\u0632\u06AF\u0634\u062A \u067E\u0633 \u0627\u0632 \u0634\u0631\u0648\u0639\u060C \u0627\u0648\u062C \u0648 \u067E\u0627\u06CC\u0627\u0646 \u0627\u0646\u0642\u0628\u0627\u0636."},{src:"figures/172_variable-deceleration-schematic.jpg",captionFa:"\u0646\u0645\u0648\u062F\u0627\u0631 \u0634\u0645\u0627\u062A\u06CC\u06A9 \u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628: \u0634\u0631\u0648\u0639 \u0646\u0627\u06AF\u0647\u0627\u0646\u06CC (<\u06F3\u06F0 \u062B\u0627\u0646\u06CC\u0647)\u060C \u06A9\u0627\u0647\u0634 \u2265\u06F1\u06F5 bpm \u0628\u0647 \u0645\u062F\u062A \u2265\u06F1\u06F5 \u062B\u0627\u0646\u06CC\u0647."},{src:"figures/170_variable-deceleration-patterns-BC.jpg",captionFa:"\u062F\u0648 \u0627\u0644\u06AF\u0648\u06CC \u0645\u062A\u0641\u0627\u0648\u062A \u0627\u0641\u062A \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062D\u06CC\u0646 \u0632\u0627\u06CC\u0645\u0627\u0646 \u0641\u0639\u0627\u0644\u060C \u0647\u0631 \u062F\u0648 \u0645\u0631\u062A\u0628\u0637 \u0628\u0627 \u0641\u0634\u0627\u0631 \u0628\u0647 \u0633\u0631 \u0648 \u06A9\u0648\u0631\u062F."},{src:"figures/172_variable-deceleration-shoulders-AB.jpg",captionFa:"\u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u0628\u0627 \xAB\u0634\u0627\u0646\u0647\xBB\u0647\u0627\u06CC \u062A\u0633\u0631\u06CC\u0639 \u0642\u0628\u0644 \u0648 \u0628\u0639\u062F \u0627\u0632 \u0627\u0641\u062A (\u067E\u0627\u0646\u0644 B) \u062F\u0631 \u0645\u0642\u0627\u06CC\u0633\u0647 \u0628\u0627 \u0628\u062F\u0648\u0646 \u0634\u0627\u0646\u0647 (\u067E\u0627\u0646\u0644 A)\u060C \u0646\u0627\u0634\u06CC \u0627\u0632 \u0627\u0646\u0633\u062F\u0627\u062F \u0646\u0627\u06A9\u0627\u0645\u0644 (\u0648\u0631\u06CC\u062F\u06CC) \u0628\u0646\u062F\u0646\u0627\u0641."},{src:"figures/172_cord-compression-fhr-A-B.jpg",captionFa:"\u062A\u0623\u062B\u06CC\u0631 \u0641\u0634\u0627\u0631 \u0628\u0631 \u0628\u0646\u062F\u0646\u0627\u0641 \u0628\u0631 \u0633\u0631\u0639\u062A \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062C\u0646\u06CC\u0646 \u062F\u0631 \u062F\u0648 \u0646\u0645\u0627\u06CC \u0645\u062E\u062A\u0644\u0641."},{src:"figures/173_cord-occlusion-physiology-diagram.jpg",captionFa:"\u0646\u0645\u0627\u06CC \u0634\u0645\u0627\u062A\u06CC\u06A9 \u0647\u0645\u200C\u0632\u0645\u0627\u0646 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062C\u0646\u06CC\u0646\u060C \u0627\u0646\u0642\u0628\u0627\u0636 \u0631\u062D\u0645\u06CC\u060C \u0641\u0634\u0627\u0631 \u0648\u0631\u06CC\u062F\u06CC/\u0634\u0631\u06CC\u0627\u0646\u06CC \u0646\u0627\u0641\u06CC \u0648 \u0641\u0634\u0627\u0631 \u0633\u06CC\u0633\u062A\u0648\u0644\u06CC\u06A9 \u062C\u0646\u06CC\u0646 \u0637\u06CC \u0627\u0646\u0633\u062F\u0627\u062F \u062C\u0632\u0626\u06CC \u0648 \u06A9\u0627\u0645\u0644 \u0628\u0646\u062F\u0646\u0627\u0641."}],callouts:[{kind:"note",label:"\u0645\u06A9\u0627\u0646\u06CC\u0633\u0645 \u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631",html:"<p>\u0627\u0646\u0633\u062F\u0627\u062F \u0646\u0633\u0628\u06CC \u06CC\u0627 \u06A9\u0627\u0645\u0644 \u0628\u0646\u062F\u0646\u0627\u0641 \u0627\u0628\u062A\u062F\u0627 \u0627\u0641\u0632\u0627\u06CC\u0634 \u067E\u0633\u200C\u0628\u0627\u0631 \u0648 \u0641\u0634\u0627\u0631 \u062E\u0648\u0646 \u0634\u0631\u06CC\u0627\u0646\u06CC \u0627\u06CC\u062C\u0627\u062F \u06A9\u0631\u062F\u0647 (\u062A\u062D\u0631\u06CC\u06A9 \u0628\u0627\u0631\u0648\u0631\u0633\u067E\u062A\u0648\u0631) \u0648 \u0633\u067E\u0633 \u0628\u0627 \u06A9\u0627\u0647\u0634 \u0627\u06A9\u0633\u06CC\u0698\u0646 \u0634\u0631\u06CC\u0627\u0646\u06CC\u060C \u06A9\u0645\u0648\u0633\u0631\u067E\u062A\u0648\u0631\u0647\u0627 \u0631\u0627 \u062A\u062D\u0631\u06CC\u06A9 \u0645\u06CC\u200C\u06A9\u0646\u062F\u061B \u0647\u0631 \u062F\u0648 \u0645\u0633\u06CC\u0631 \u0627\u0632 \u0637\u0631\u06CC\u0642 \u0639\u0635\u0628 \u0648\u0627\u06AF \u0627\u0641\u062A \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u0627\u06CC\u062C\u0627\u062F \u0645\u06CC\u200C\u06A9\u0646\u0646\u062F.</p>"}]},{heading:"\u0637\u0628\u0642\u0647\u200C\u0628\u0646\u062F\u06CC \u0633\u0647\u200C\u06AF\u0631\u0648\u0647\u06CC NICHD",paragraphsHtml:['<p>\u0628\u0631 \u0627\u0633\u0627\u0633 \u0646\u0634\u0633\u062A \u06F2\u06F0\u06F0\u06F8 <span class="en">NICHD</span>\u060C \u0627\u0644\u06AF\u0648\u0647\u0627\u06CC \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062C\u0646\u06CC\u0646 \u0628\u0647 \u0633\u0647 \u062F\u0633\u062A\u0647 \u062A\u0642\u0633\u06CC\u0645 \u0645\u06CC\u200C\u0634\u0648\u0646\u062F. \u062F\u0633\u062A\u0647\u200C\u06CC <span class="en">I (\u0637\u0628\u06CC\u0639\u06CC)</span> \u067E\u06CC\u0634\u200C\u0628\u06CC\u0646\u06CC\u200C\u06A9\u0646\u0646\u062F\u0647\u200C\u06CC \u0648\u0636\u0639\u06CC\u062A \u0627\u0633\u06CC\u062F-\u0628\u0627\u0632 \u0637\u0628\u06CC\u0639\u06CC \u062C\u0646\u06CC\u0646 \u062F\u0631 \u0632\u0645\u0627\u0646 \u0645\u0634\u0627\u0647\u062F\u0647 \u0627\u0633\u062A. \u062F\u0633\u062A\u0647\u200C\u06CC <span class="en">II (\u0646\u0627\u0645\u0634\u062E\u0635)</span> \u0634\u0627\u0645\u0644 \u0647\u0645\u0647\u200C\u06CC \u0646\u0648\u0627\u0631\u0647\u0627\u06CC\u06CC \u0627\u0633\u062A \u06A9\u0647 \u062F\u0631 \u062F\u0633\u062A\u0647\u200C\u06CC I \u06CC\u0627 III \u0642\u0631\u0627\u0631 \u0646\u0645\u06CC\u200C\u06AF\u06CC\u0631\u0646\u062F \u0648 \u0628\u062E\u0634 \u0642\u0627\u0628\u0644\u200C\u062A\u0648\u062C\u0647\u06CC \u0627\u0632 \u0646\u0648\u0627\u0631\u0647\u0627\u06CC \u0628\u0627\u0644\u06CC\u0646\u06CC \u0631\u0627 \u062A\u0634\u06A9\u06CC\u0644 \u0645\u06CC\u200C\u062F\u0647\u0646\u062F. \u062F\u0633\u062A\u0647\u200C\u06CC <span class="en">III (\u063A\u06CC\u0631\u0637\u0628\u06CC\u0639\u06CC)</span> \u0628\u0627 \u067E\u06CC\u0627\u0645\u062F\u0647\u0627\u06CC \u0646\u0627\u0645\u0637\u0644\u0648\u0628 \u0645\u0631\u062A\u0628\u0637 \u0627\u0633\u062A \u0648 \u0646\u06CC\u0627\u0632\u0645\u0646\u062F \u0627\u0631\u0632\u06CC\u0627\u0628\u06CC \u0648 \u0645\u062F\u0627\u062E\u0644\u0647\u200C\u06CC \u0641\u0648\u0631\u06CC \u0627\u0633\u062A.</p>'],table:{caption:"\u0637\u0628\u0642\u0647\u200C\u0628\u0646\u062F\u06CC \u0633\u0647\u200C\u06AF\u0631\u0648\u0647\u06CC NICHD (\u06F2\u06F0\u06F0\u06F8)",headers:["\u062F\u0633\u062A\u0647","\u0645\u0639\u06CC\u0627\u0631\u0647\u0627"],rows:[["I \u2014 \u0637\u0628\u06CC\u0639\u06CC","\u0636\u0631\u0628\u0627\u0646 \u067E\u0627\u06CC\u0647 \u06F1\u06F1\u06F0 \u062A\u0627 \u06F1\u06F6\u06F0\u061B \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0645\u062A\u0648\u0633\u0637\u061B \u0641\u0642\u062F\u0627\u0646 \u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633 \u06CC\u0627 \u0645\u062A\u063A\u06CC\u0631\u061B \u0627\u0641\u062A \u0632\u0648\u062F\u0631\u0633 \u0648 \u062A\u0633\u0631\u06CC\u0639 \u0645\u0645\u06A9\u0646 \u0627\u0633\u062A \u0648\u062C\u0648\u062F \u062F\u0627\u0634\u062A\u0647 \u06CC\u0627 \u0646\u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u0646\u062F"],["II \u2014 \u0646\u0627\u0645\u0634\u062E\u0635","\u0634\u0627\u0645\u0644 \u0647\u0645\u0647\u200C\u06CC \u0646\u0648\u0627\u0631\u0647\u0627\u06CC\u06CC \u06A9\u0647 \u062F\u0631 \u062F\u0633\u062A\u0647 I \u06CC\u0627 III \u0646\u0645\u06CC\u200C\u06AF\u0646\u062C\u0646\u062F\u061B \u0645\u062B\u0627\u0644\u200C\u0647\u0627: \u0628\u0631\u0627\u062F\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC \u0628\u062F\u0648\u0646 \u0641\u0642\u062F\u0627\u0646 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC\u060C \u062A\u0627\u06A9\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC\u060C \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u062C\u0632\u0626\u06CC \u06CC\u0627 \u0634\u062F\u06CC\u062F\u060C \u0641\u0642\u062F\u0627\u0646 \u062A\u0633\u0631\u06CC\u0639 \u067E\u0633 \u0627\u0632 \u062A\u062D\u0631\u06CC\u06A9\u060C \u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631 \u0645\u06A9\u0631\u0631 \u0628\u0627 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u062C\u0632\u0626\u06CC/\u0645\u062A\u0648\u0633\u0637\u060C \u0627\u0641\u062A \u0637\u0648\u0644\u0627\u0646\u06CC\u200C\u0645\u062F\u062A (\u06F2 \u062A\u0627 <\u06F1\u06F0 \u062F\u0642\u06CC\u0642\u0647)\u060C \u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633 \u0645\u06A9\u0631\u0631 \u0628\u0627 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0645\u062A\u0648\u0633\u0637"],["III \u2014 \u063A\u06CC\u0631\u0637\u0628\u06CC\u0639\u06CC","\u0641\u0642\u062F\u0627\u0646 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u067E\u0627\u06CC\u0647 \u0628\u0647\u200C\u0647\u0645\u0631\u0627\u0647 \u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633 \u0645\u06A9\u0631\u0631\u060C \u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631 \u0645\u06A9\u0631\u0631\u060C \u06CC\u0627 \u0628\u0631\u0627\u062F\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC\u061B \u06CC\u0627 \u0627\u0644\u06AF\u0648\u06CC \u0633\u06CC\u0646\u0648\u0633\u06CC"]]}},{heading:"\u0627\u0631\u0632\u06CC\u0627\u0628\u06CC \u0632\u062C\u0631 \u062C\u0646\u06CC\u0646 \u0648 \u0645\u062F\u06CC\u0631\u06CC\u062A \u0627\u0644\u06AF\u0648\u0647\u0627\u06CC \u063A\u06CC\u0631\u0637\u0628\u06CC\u0639\u06CC",paragraphsHtml:["<p>\u0627\u0635\u0637\u0644\u0627\u062D \xAB\u0632\u062C\u0631 \u062C\u0646\u06CC\u0646\xBB \u0645\u0628\u0647\u0645 \u0648 \u063A\u06CC\u0631\u062F\u0642\u06CC\u0642 \u0627\u0633\u062A \u0648 \u0627\u06A9\u0646\u0648\u0646 \u0628\u0647\u200C\u062C\u0627\u06CC \u0622\u0646 \u0627\u0635\u0637\u0644\u0627\u062D\u0627\u062A \xAB\u0627\u0637\u0645\u06CC\u0646\u0627\u0646\u200C\u0628\u062E\u0634\xBB \u0648 \xAB\u0639\u062F\u0645 \u0627\u0637\u0645\u06CC\u0646\u0627\u0646\u200C\u0628\u062E\u0634\xBB \u0628\u0647\u200C\u06A9\u0627\u0631 \u0645\u06CC\u200C\u0631\u0648\u062F. \u0645\u062A\u062E\u0635\u0635\u0627\u0646 \u062A\u0646\u0647\u0627 \u062F\u0631 \u062D\u062F\u0648\u062F \u06F2\u06F5\u066A \u0645\u0648\u0627\u0631\u062F \u0631\u0648\u06CC \u0627\u0644\u06AF\u0648\u0647\u0627\u06CC \u067E\u0627\u062A\u0648\u0644\u0648\u0698\u06CC\u06A9 \u062A\u0648\u0627\u0641\u0642 \u062F\u0627\u0631\u0646\u062F. \u062E\u0644\u0627\u0635\u0647\u200C\u06CC \u0627\u0644\u06AF\u0648\u06CC \u0648\u0627\u0642\u0639\u06CC \u062F\u06CC\u0633\u062A\u0631\u0633 \u062C\u0646\u06CC\u0646: \u0641\u0642\u062F\u0627\u0646 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633 \u06CC\u0627 \u0645\u062A\u063A\u06CC\u0631 \u0634\u062F\u06CC\u062F\u060C \u06CC\u0627 \u0636\u0631\u0628\u0627\u0646 \u067E\u0627\u06CC\u0647 \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F1\u06F1\u06F0 \u0636\u0631\u0628\u0647 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647 \u0628\u0647 \u0645\u062F\u062A \u06F5 \u062F\u0642\u06CC\u0642\u0647 \u06CC\u0627 \u0628\u06CC\u0634\u062A\u0631.</p>","<p>\u062F\u0631 \u0628\u0631\u062E\u0648\u0631\u062F \u0628\u0627 \u0627\u0644\u06AF\u0648\u06CC \u063A\u06CC\u0631\u0645\u0637\u0645\u0626\u0646\u060C \u0627\u0642\u062F\u0627\u0645\u0627\u062A \u0627\u0648\u0644\u06CC\u0647 \u0634\u0627\u0645\u0644 \u0642\u0637\u0639 \u0647\u0631 \u0639\u0627\u0645\u0644 \u062A\u062D\u0631\u06CC\u06A9\u200C\u06A9\u0646\u0646\u062F\u0647\u200C\u06CC \u0632\u0627\u06CC\u0645\u0627\u0646 (\u0627\u06A9\u0633\u06CC\u200C\u062A\u0648\u0633\u06CC\u0646)\u060C \u0645\u0639\u0627\u06CC\u0646\u0647\u200C\u06CC \u0633\u0631\u0648\u06CC\u06A9\u0633 \u0628\u0631\u0627\u06CC \u0628\u0631\u0631\u0633\u06CC \u067E\u0631\u0648\u0644\u0627\u067E\u0633 \u06A9\u0648\u0631\u062F \u06CC\u0627 \u0646\u0632\u0648\u0644 \u0633\u0631\u06CC\u0639 \u0633\u0631\u060C \u062A\u063A\u06CC\u06CC\u0631 \u0648\u0636\u0639\u06CC\u062A \u0645\u0627\u062F\u0631 \u0628\u0647 \u067E\u0647\u0644\u0648\u06CC \u0686\u067E \u06CC\u0627 \u0631\u0627\u0633\u062A (\u06A9\u0627\u0647\u0634 \u0641\u0634\u0627\u0631 \u0631\u0648\u06CC \u0648\u0631\u06CC\u062F \u0627\u062C\u0648\u0641 \u0648 \u0628\u0647\u0628\u0648\u062F \u062C\u0631\u06CC\u0627\u0646 \u062E\u0648\u0646 \u0631\u062D\u0645\u06CC-\u062C\u0641\u062A\u06CC)\u060C \u0628\u0631\u0631\u0633\u06CC \u0641\u0634\u0627\u0631 \u062E\u0648\u0646 \u0645\u0627\u062F\u0631 (\u062F\u0631\u0645\u0627\u0646 \u0647\u06CC\u067E\u0648\u062A\u0627\u0646\u0633\u06CC\u0648\u0646 \u0646\u0627\u0634\u06CC \u0627\u0632 \u0628\u06CC\u200C\u062D\u0633\u06CC \u0645\u0646\u0637\u0642\u0647\u200C\u0627\u06CC \u0628\u0627 \u0627\u0641\u062F\u0631\u06CC\u0646 \u06CC\u0627 \u0641\u0646\u06CC\u0644\u200C\u0627\u0641\u0631\u06CC\u0646)\u060C \u0648 \u0627\u0631\u0632\u06CC\u0627\u0628\u06CC \u0628\u06CC\u0634\u200C\u0641\u0639\u0627\u0644\u06CC \u0631\u062D\u0645 \u0627\u0633\u062A. \u062A\u0648\u06A9\u0648\u0644\u06CC\u0632 \u062D\u0627\u062F \u0628\u0627 \u062A\u0631\u0628\u0648\u062A\u0627\u0644\u06CC\u0646 (\u06F0.\u06F2\u06F5 \u0645\u06CC\u0644\u06CC\u200C\u06AF\u0631\u0645) \u06CC\u0627 \u0646\u06CC\u062A\u0631\u0648\u06AF\u0644\u06CC\u0633\u06CC\u0631\u06CC\u0646 (\u06F6\u06F0 \u062A\u0627 \u06F1\u06F8\u06F0 \u0645\u06CC\u06A9\u0631\u0648\u06AF\u0631\u0645) \u0628\u0631\u0627\u06CC \u0634\u0644\u200C\u06A9\u0631\u062F\u0646 \u0631\u062D\u0645 \u0648 \u0628\u0647\u0628\u0648\u062F \u0627\u06A9\u0633\u06CC\u0698\u0646\u0627\u0633\u06CC\u0648\u0646 \u062C\u0646\u06CC\u0646 \u0642\u0627\u0628\u0644 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0627\u0633\u062A.</p>"],table:{caption:"\u0627\u0642\u062F\u0627\u0645\u0627\u062A \u0627\u0648\u0644\u06CC\u0647 \u062F\u0631 \u0627\u0644\u06AF\u0648\u06CC \u063A\u06CC\u0631\u0645\u0637\u0645\u0626\u0646 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062C\u0646\u06CC\u0646",headers:["\u0627\u0642\u062F\u0627\u0645","\u0647\u062F\u0641"],rows:[["\u0642\u0637\u0639 \u0639\u0627\u0645\u0644 \u062A\u062D\u0631\u06CC\u06A9\u200C\u06A9\u0646\u0646\u062F\u0647\u200C\u06CC \u0632\u0627\u06CC\u0645\u0627\u0646","\u06A9\u0627\u0647\u0634 \u0647\u06CC\u067E\u0631\u0627\u0633\u062A\u06CC\u0645\u0648\u0644\u0627\u0633\u06CC\u0648\u0646 \u0631\u062D\u0645"],["\u0645\u0639\u0627\u06CC\u0646\u0647\u200C\u06CC \u0633\u0631\u0648\u06CC\u06A9\u0633","\u0628\u0631\u0631\u0633\u06CC \u067E\u0631\u0648\u0644\u0627\u067E\u0633 \u0628\u0646\u062F\u0646\u0627\u0641 \u06CC\u0627 \u0646\u0632\u0648\u0644 \u0633\u0631\u06CC\u0639 \u0633\u0631"],["\u062A\u063A\u06CC\u06CC\u0631 \u0648\u0636\u0639\u06CC\u062A \u0628\u0647 \u067E\u0647\u0644\u0648\u06CC \u0686\u067E/\u0631\u0627\u0633\u062A","\u06A9\u0627\u0647\u0634 \u0641\u0634\u0627\u0631 \u0631\u0648\u06CC \u0648\u0631\u06CC\u062F \u0627\u062C\u0648\u0641\u060C \u0628\u0647\u0628\u0648\u062F \u062C\u0631\u06CC\u0627\u0646 \u062E\u0648\u0646 \u0631\u062D\u0645\u06CC-\u062C\u0641\u062A\u06CC"],["\u0628\u0631\u0631\u0633\u06CC \u0641\u0634\u0627\u0631 \u062E\u0648\u0646 \u0645\u0627\u062F\u0631","\u06A9\u0634\u0641 \u0648 \u062F\u0631\u0645\u0627\u0646 \u0647\u06CC\u067E\u0648\u062A\u0627\u0646\u0633\u06CC\u0648\u0646 (\u0627\u0641\u062F\u0631\u06CC\u0646/\u0641\u0646\u06CC\u0644\u200C\u0627\u0641\u0631\u06CC\u0646) \u0628\u0647\u200C\u062E\u0635\u0648\u0635 \u0628\u0627 \u0628\u06CC\u200C\u062D\u0633\u06CC \u0645\u0646\u0637\u0642\u0647\u200C\u0627\u06CC"],["\u0627\u0631\u0632\u06CC\u0627\u0628\u06CC \u0641\u0631\u06A9\u0627\u0646\u0633/\u0645\u062F\u062A \u0627\u0646\u0642\u0628\u0627\u0636\u0627\u062A","\u06A9\u0634\u0641 \u0647\u06CC\u067E\u0631\u0627\u0633\u062A\u06CC\u0645\u0648\u0644\u0627\u0633\u06CC\u0648\u0646 \u0631\u062D\u0645"]],note:"\u0628\u0631\u06AF\u0631\u0641\u062A\u0647 \u0627\u0632 \u0631\u0627\u0647\u0646\u0645\u0627\u06CC ACOG \u0628\u0631\u0627\u06CC \u0645\u0627\u0646\u06CC\u062A\u0648\u0631\u06CC\u0646\u06AF \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062D\u06CC\u0646 \u0632\u0627\u06CC\u0645\u0627\u0646."}},{heading:"\u0631\u0648\u0634\u200C\u0647\u0627\u06CC \u062A\u06A9\u0645\u06CC\u0644\u06CC \u0627\u0631\u0632\u06CC\u0627\u0628\u06CC \u062C\u0646\u06CC\u0646",paragraphsHtml:["<p><strong>\u0646\u0645\u0648\u0646\u0647\u200C\u06AF\u06CC\u0631\u06CC \u0627\u0632 \u067E\u0648\u0633\u062A \u0633\u0631 \u062C\u0646\u06CC\u0646:</strong> \u0627\u0646\u062F\u0627\u0632\u0647\u200C\u06AF\u06CC\u0631\u06CC pH \u062E\u0648\u0646 \u0645\u0648\u06CC\u0631\u06AF\u06CC \u067E\u0648\u0633\u062A \u0633\u0631 \u0628\u0647 \u062A\u0634\u062E\u06CC\u0635 \u062C\u0646\u06CC\u0646\u200C\u0647\u0627\u06CC \u062F\u0686\u0627\u0631 \u062F\u06CC\u0633\u062A\u0631\u0633 \u0634\u062F\u06CC\u062F \u06A9\u0645\u06A9 \u0645\u06CC\u200C\u06A9\u0646\u062F\u060C \u0647\u0631\u0686\u0646\u062F \u0627\u0645\u0631\u0648\u0632\u0647 \u06A9\u0645\u062A\u0631 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F. \u0637\u0628\u0642 \u062F\u0633\u062A\u0648\u0631\u0627\u0644\u0639\u0645\u0644 \u06A9\u0644\u0627\u0633\u06CC\u06A9: pH \u0628\u06CC\u0634\u062A\u0631 \u0627\u0632 \u06F7.\u06F2\u06F5 \u0641\u0642\u0637 \u0646\u06CC\u0627\u0632 \u0628\u0647 \u067E\u06CC\u06AF\u06CC\u0631\u06CC \u062F\u0627\u0631\u062F\u061B pH \u0628\u06CC\u0646 \u06F7.\u06F2\u06F0 \u062A\u0627 \u06F7.\u06F2\u06F5 \u0646\u06CC\u0627\u0632 \u0628\u0647 \u062A\u06A9\u0631\u0627\u0631 \u0646\u0645\u0648\u0646\u0647\u200C\u06AF\u06CC\u0631\u06CC \u0638\u0631\u0641 \u06F3\u06F0 \u062F\u0642\u06CC\u0642\u0647 \u062F\u0627\u0631\u062F\u061B pH \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F7.\u06F2\u06F0 \u0646\u06CC\u0627\u0632\u0645\u0646\u062F \u0646\u0645\u0648\u0646\u0647\u200C\u06AF\u06CC\u0631\u06CC \u0641\u0648\u0631\u06CC \u0628\u0639\u062F\u06CC \u0648 \u0622\u0645\u0627\u062F\u0647\u200C\u0633\u0627\u0632\u06CC \u0628\u0631\u0627\u06CC \u0632\u0627\u06CC\u0645\u0627\u0646 \u0627\u0633\u062A.</p>","<p><strong>\u062A\u062D\u0631\u06CC\u06A9 \u0627\u0631\u062A\u0639\u0627\u0634\u06CC \u0635\u0648\u062A\u06CC (Vibroacoustic stimulation):</strong> \u0627\u06AF\u0631 \u0638\u0631\u0641 \u06F1\u06F5 \u062B\u0627\u0646\u06CC\u0647 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u06F1\u06F5 \u0636\u0631\u0628\u0647 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647 \u0627\u0641\u0632\u0627\u06CC\u0634 \u06CC\u0627\u0628\u062F \u0648 \u0628\u0647 \u0645\u062F\u062A \u06F1\u06F5 \u062B\u0627\u0646\u06CC\u0647 \u0628\u0627\u0642\u06CC \u0628\u0645\u0627\u0646\u062F\u060C \u0637\u0628\u06CC\u0639\u06CC \u062A\u0644\u0642\u06CC \u0645\u06CC\u200C\u0634\u0648\u062F. \u062C\u0627\u06CC\u06AF\u0632\u06CC\u0646\u06CC \u0628\u0631\u0627\u06CC \u062E\u0648\u0646\u200C\u06AF\u06CC\u0631\u06CC \u0627\u0633\u06A9\u0627\u0644\u067E \u0627\u0633\u062A.</p>","<p><strong>\u067E\u0627\u0644\u0633 \u0627\u06A9\u0633\u06CC\u200C\u0645\u062A\u0631\u06CC \u062C\u0646\u06CC\u0646:</strong> \u0628\u0627 \u0642\u0631\u0627\u0631 \u062F\u0627\u062F\u0646 \u06CC\u06A9 \u067E\u062F \u062D\u0633\u0627\u0633 \u0631\u0648\u06CC \u0635\u0648\u0631\u062A \u062C\u0646\u06CC\u0646 \u0627\u0632 \u0637\u0631\u06CC\u0642 \u0633\u0631\u0648\u06CC\u06A9\u0633\u060C \u0627\u0634\u0628\u0627\u0639 \u0627\u06A9\u0633\u06CC\u0698\u0646 \u062C\u0646\u06CC\u0646 \u0627\u0646\u062F\u0627\u0632\u0647\u200C\u06AF\u06CC\u0631\u06CC \u0645\u06CC\u200C\u0634\u0648\u062F\u061B \u062D\u062F \u067E\u0627\u06CC\u06CC\u0646 \u0642\u0627\u0628\u0644\u200C\u0642\u0628\u0648\u0644 \u06F3\u06F0\u066A \u0627\u0633\u062A \u0648 \u0627\u06AF\u0631 \u2264\u06F2 \u062F\u0642\u06CC\u0642\u0647 \u0628\u0627\u0642\u06CC \u0628\u0645\u0627\u0646\u062F \u0628\u0627 \u0627\u0641\u0632\u0627\u06CC\u0634 \u062E\u0637\u0631 \u0628\u062F\u062D\u0627\u0644\u06CC \u062C\u0646\u06CC\u0646 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062A.</p>",'<p><strong>\u0627\u0644\u06A9\u062A\u0631\u0648\u06A9\u0627\u0631\u062F\u06CC\u0648\u06AF\u0631\u0627\u0641\u06CC \u062C\u0646\u06CC\u0646 \u0648 \u062F\u0627\u067E\u0644\u0631:</strong> \u0628\u0631\u0631\u0633\u06CC \u062A\u063A\u06CC\u06CC\u0631\u0627\u062A <span class="en">ST</span> \u0646\u062A\u0627\u06CC\u062C \u0631\u0627 \u0628\u0647\u0628\u0648\u062F \u0646\u062F\u0627\u062F \u0627\u0645\u0627 \u0645\u06CC\u0632\u0627\u0646 \u0633\u0632\u0627\u0631\u06CC\u0646 \u0646\u0627\u0634\u06CC \u0627\u0632 \u062F\u06CC\u0633\u062A\u0631\u0633 \u0631\u0627 \u06A9\u0627\u0647\u0634 \u062F\u0627\u062F\u061B \u0627\u0645\u0648\u0627\u062C \u062F\u0627\u067E\u0644\u0631 \u063A\u06CC\u0631\u0639\u0627\u062F\u06CC \u0639\u0631\u0648\u0642 \u0628\u0646\u062F \u0646\u0627\u0641 \u062F\u0627\u0644 \u0628\u0631 \u0645\u0642\u0627\u0648\u0645\u062A \u067E\u0627\u062A\u0648\u0644\u0648\u0698\u06CC\u06A9 \u0639\u0631\u0648\u0642\u06CC \u062C\u0641\u062A-\u0628\u0646\u062F\u0646\u0627\u0641 \u0627\u0633\u062A \u0627\u0645\u0627 \u067E\u06CC\u0634\u200C\u06AF\u0648\u06CC\u06CC\u200C\u06A9\u0646\u0646\u062F\u0647\u200C\u06CC \u0636\u0639\u06CC\u0641\u06CC \u0628\u0631\u0627\u06CC \u0639\u0648\u0627\u0631\u0636 \u067E\u0631\u06CC\u200C\u0646\u0627\u062A\u0627\u0644 \u0627\u0633\u062A.</p>'],figures:[{src:"figures/179_pulse-oximeter-placement.jpg",captionFa:"\u0646\u0645\u0627\u06CC \u0634\u0645\u0627\u062A\u06CC\u06A9 \u0642\u0631\u0627\u0631\u06AF\u06CC\u0631\u06CC \u0639\u0636\u0648 \u062D\u0633\u06AF\u0631 \u067E\u0627\u0644\u0633\u200C\u0627\u06A9\u0633\u06CC\u200C\u0645\u062A\u0631\u06CC \u062C\u0646\u06CC\u0646 \u0631\u0648\u06CC \u0635\u0648\u0631\u062A \u062C\u0646\u06CC\u0646 \u0627\u0632 \u0637\u0631\u06CC\u0642 \u0633\u0631\u0648\u06CC\u06A9\u0633."}],callouts:[{kind:"key",label:"\u0622\u0633\u062A\u0627\u0646\u0647\u200C\u0647\u0627\u06CC pH \u0627\u0633\u06A9\u0627\u0644\u067E",html:"<p>pH > \u06F7.\u06F2\u06F5: \u067E\u06CC\u06AF\u06CC\u0631\u06CC \u0633\u06CC\u0631 \u0632\u0627\u06CC\u0645\u0627\u0646. pH \u06F7.\u06F2\u06F0 \u062A\u0627 \u06F7.\u06F2\u06F5: \u062A\u06A9\u0631\u0627\u0631 \u0646\u0645\u0648\u0646\u0647\u200C\u06AF\u06CC\u0631\u06CC \u0638\u0631\u0641 \u06F3\u06F0 \u062F\u0642\u06CC\u0642\u0647. pH < \u06F7.\u06F2\u06F0: \u0646\u0645\u0648\u0646\u0647\u200C\u06AF\u06CC\u0631\u06CC \u0641\u0648\u0631\u06CC \u0628\u0639\u062F\u06CC \u0648 \u0622\u0645\u0627\u062F\u0647\u200C\u0633\u0627\u0632\u06CC \u0628\u0631\u0627\u06CC \u0632\u0627\u06CC\u0645\u0627\u0646 \u0627\u0648\u0631\u0698\u0627\u0646\u0633\u06CC.</p>"}]},{heading:"\u0645\u06A9\u0648\u0646\u06CC\u0648\u0645 \u062F\u0631 \u0645\u0627\u06CC\u0639 \u0622\u0645\u0646\u06CC\u0648\u062A\u06CC\u06A9",paragraphsHtml:["<p>\u062F\u0641\u0639 \u0645\u06A9\u0648\u0646\u06CC\u0648\u0645 \u062F\u0631 \u06F1\u06F2 \u062A\u0627 \u06F2\u06F2\u066A \u0632\u0627\u06CC\u0645\u0627\u0646\u200C\u0647\u0627\u06CC \u0627\u0646\u0633\u0627\u0646\u06CC \u0631\u062E \u0645\u06CC\u200C\u062F\u0647\u062F \u0627\u0645\u0627 \u062A\u0646\u0647\u0627 \u0628\u062E\u0634 \u06A9\u0648\u0686\u06A9\u06CC \u0627\u0632 \u0622\u0646\u200C\u0647\u0627 \u0628\u0627 \u0645\u0631\u06AF\u200C\u0648\u0645\u06CC\u0631 \u062C\u0646\u06CC\u0646\u06CC \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062A (\u06F1 \u062F\u0631 \u0647\u0632\u0627\u0631 \u062A\u0648\u0644\u062F \u0632\u0646\u062F\u0647). \u0633\u0647 \u062A\u0648\u062C\u06CC\u0647 \u0628\u0631\u0627\u06CC \u062F\u0641\u0639 \u0645\u06A9\u0648\u0646\u06CC\u0648\u0645 \u0645\u0637\u0631\u062D \u0634\u062F\u0647: \u067E\u0627\u0633\u062E \u0628\u0647 \u0647\u06CC\u067E\u0648\u06A9\u0633\u06CC \u0648 \u0634\u0644\u200C\u0634\u062F\u0646 \u0627\u0633\u0641\u0646\u06A9\u062A\u0631 \u0622\u0646\u0627\u0644\u060C \u06A9\u0627\u0631\u06A9\u0631\u062F \u0637\u0628\u06CC\u0639\u06CC \u06AF\u0648\u0627\u0631\u0634\u06CC \u0646\u0627\u0634\u06CC \u0627\u0632 \u0628\u0644\u0648\u063A\u060C \u0648 \u062A\u062D\u0631\u06CC\u06A9 \u0648\u0627\u06AF \u0646\u0627\u0634\u06CC \u0627\u0632 \u0627\u0646\u0633\u062F\u0627\u062F \u06A9\u0648\u0631\u062F \u0648 \u0627\u0641\u0632\u0627\u06CC\u0634 \u067E\u0631\u06CC\u0633\u062A\u0627\u0644\u062A\u06CC\u0633\u0645. \u0628\u0646\u0627\u0628\u0631\u0627\u06CC\u0646 \u0648\u062C\u0648\u062F \u0645\u06A9\u0648\u0646\u06CC\u0648\u0645 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u062F \u067E\u062F\u06CC\u062F\u0647\u200C\u0627\u06CC \u0641\u06CC\u0632\u06CC\u0648\u0644\u0648\u0698\u06CC\u06A9 \u0647\u0645 \u0628\u0627\u0634\u062F.</p>","<p>\u0634\u0641\u0627\u0641 \u0628\u0648\u062F\u0646 \u0645\u0627\u06CC\u0639 \u0622\u0645\u0646\u06CC\u0648\u062A\u06CC\u06A9 \u062A\u0636\u0645\u06CC\u0646 \u0633\u0644\u0627\u0645\u062A \u062C\u0646\u06CC\u0646 \u0646\u06CC\u0633\u062A\u061B \u062F\u0631 \u062D\u062F\u0648\u062F \u06F6\u06F0\u066A \u0646\u0648\u0632\u0627\u062F\u0627\u0646\u06CC \u06A9\u0647 \u0633\u0646\u062F\u0631\u0645 \u0622\u0633\u067E\u06CC\u0631\u0627\u0633\u06CC\u0648\u0646 \u0645\u06A9\u0648\u0646\u06CC\u0648\u0645 \u062F\u0627\u0634\u062A\u0646\u062F\u060C pH \u062E\u0648\u0646 \u0634\u0631\u06CC\u0627\u0646 \u0628\u0646\u062F \u0646\u0627\u0641 \u2264\u06F7.\u06F2 \u0646\u0628\u0648\u062F\u0647 \u0627\u0633\u062A. \u0633\u0646\u062F\u0631\u0645 \u0622\u0633\u067E\u06CC\u0631\u0627\u0633\u06CC\u0648\u0646 \u0645\u06A9\u0648\u0646\u06CC\u0648\u0645 \u0631\u0648\u06CC\u062F\u0627\u062F\u06CC \u062D\u0627\u062F \u0648 \u0639\u0645\u062F\u062A\u0627\u064B \u063A\u06CC\u0631\u0642\u0627\u0628\u0644\u200C\u067E\u06CC\u0634\u200C\u0628\u06CC\u0646\u06CC/\u067E\u06CC\u0634\u06AF\u06CC\u0631\u06CC \u0627\u0633\u062A\u060C \u0647\u0631\u0686\u0646\u062F \u0634\u0648\u0627\u0647\u062F\u06CC \u0627\u0632 \u0627\u0631\u062A\u0628\u0627\u0637 \u0622\u0646 \u0628\u0627 \u0647\u06CC\u067E\u0648\u06A9\u0633\u06CC \u0645\u0632\u0645\u0646 (\u0645\u062B\u0644\u0627\u064B \u0627\u0641\u0632\u0627\u06CC\u0634 \u0627\u0631\u06CC\u062A\u0631\u0648\u067E\u0648\u0626\u062A\u06CC\u0646 \u062C\u0646\u06CC\u0646\u06CC) \u0646\u06CC\u0632 \u0648\u062C\u0648\u062F \u062F\u0627\u0631\u062F.</p>"]},{heading:"\u0622\u0633\u0641\u06CC\u06A9\u0633\u06CC \u062D\u06CC\u0646 \u0632\u0627\u06CC\u0645\u0627\u0646 \u0648 \u0641\u0644\u062C \u0645\u063A\u0632\u06CC",paragraphsHtml:["<p>\u0627\u0644\u06AF\u0648\u06CC \u062E\u0627\u0635 \u0642\u0644\u0628\u06CC \u06A9\u0647 \u0628\u0647\u200C\u0637\u0648\u0631 \u0627\u062E\u062A\u0635\u0627\u0635\u06CC \u0628\u0627 \u0622\u0633\u06CC\u0628 \u0645\u063A\u0632\u06CC \u062C\u0646\u06CC\u0646 \u0647\u0645\u0631\u0627\u0647 \u0628\u0627\u0634\u062F\u060C \u0634\u0646\u0627\u0633\u0627\u06CC\u06CC \u0646\u0634\u062F\u0647 \u0627\u0633\u062A. \u0645\u0637\u0627\u0644\u0639\u0627\u062A \u062D\u06CC\u0648\u0627\u0646\u06CC \u0646\u0634\u0627\u0646 \u0645\u06CC\u200C\u062F\u0647\u062F \u0622\u0633\u0641\u06CC\u06A9\u0633\u06CC \u06A9\u0627\u0645\u0644 \u0628\u0647 \u0639\u0644\u062A \u0627\u0646\u0633\u062F\u0627\u062F \u06A9\u0627\u0645\u0644 \u06A9\u0648\u0631\u062F \u0628\u0627\u0639\u062B \u0627\u0641\u062A \u0637\u0648\u0644\u0627\u0646\u06CC\u200C\u0645\u062F\u062A \u0636\u0631\u0628\u0627\u0646 \u0645\u06CC\u200C\u0634\u0648\u062F\u060C \u0627\u0645\u0627 pH \u062A\u0627 \u062D\u062F\u0648\u062F \u06F8 \u062F\u0642\u06CC\u0642\u0647 \u0628\u0639\u062F \u0627\u0632 \u0627\u0646\u0633\u062F\u0627\u062F \u0628\u0647 \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F7 \u0646\u0645\u06CC\u200C\u0631\u0633\u062F \u0648 \u062D\u062F\u0627\u0642\u0644 \u06F1\u06F0 \u062F\u0642\u06CC\u0642\u0647 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u063A\u06CC\u0631\u0637\u0628\u06CC\u0639\u06CC \u067E\u06CC\u0634 \u0627\u0632 \u0628\u0631\u0648\u0632 \u0634\u0648\u0627\u0647\u062F \u0622\u0633\u06CC\u0628 \u0645\u063A\u0632\u06CC \u0644\u0627\u0632\u0645 \u0627\u0633\u062A. \u0628\u06CC\u0634\u062A\u0631 \u0645\u0648\u0627\u0631\u062F \u0641\u0644\u062C \u0645\u063A\u0632\u06CC \u0627\u0631\u062A\u0628\u0627\u0637\u06CC \u0628\u0627 \u0627\u062A\u0641\u0627\u0642\u0627\u062A \u062D\u06CC\u0646 \u0632\u0627\u06CC\u0645\u0627\u0646 \u0646\u062F\u0627\u0631\u0646\u062F.</p>","<p>\u0628\u0631\u0627\u06CC \u0627\u06CC\u0646\u06A9\u0647 \u0635\u062F\u0645\u0647\u200C\u06CC \u0646\u0648\u0631\u0648\u0644\u0648\u0698\u06CC\u06A9 \u0648 \u0641\u0644\u062C \u0645\u063A\u0632\u06CC \u0628\u0647 \u0622\u0633\u0641\u06CC\u06A9\u0633\u06CC \u0632\u0645\u0627\u0646 \u062A\u0648\u0644\u062F \u0646\u0633\u0628\u062A \u062F\u0627\u062F\u0647 \u0634\u0648\u062F\u060C \u0637\u0628\u0642 \u0645\u0639\u06CC\u0627\u0631\u0647\u0627\u06CC \u0632\u06CC\u0631\u060C \u0647\u0645\u0647\u200C\u06CC \u0645\u0639\u06CC\u0627\u0631\u0647\u0627\u06CC \u0627\u0633\u0627\u0633\u06CC \u0628\u0627\u06CC\u062F \u062D\u0636\u0648\u0631 \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u0646\u062F.</p>"],table:{caption:"\u0645\u0639\u06CC\u0627\u0631\u0647\u0627\u06CC \u0627\u0633\u0627\u0633\u06CC \u0628\u0631\u0627\u06CC \u0646\u0633\u0628\u062A\u200C\u062F\u0627\u062F\u0646 \u0641\u0644\u062C \u0645\u063A\u0632\u06CC \u0628\u0647 \u0631\u0648\u06CC\u062F\u0627\u062F \u0647\u06CC\u067E\u0648\u06A9\u0633\u06CC\u06A9 \u062D\u0627\u062F \u062D\u06CC\u0646 \u062A\u0648\u0644\u062F (\u0647\u0631 \u0686\u0647\u0627\u0631 \u0645\u0648\u0631\u062F \u0628\u0627\u06CC\u062F \u0645\u0648\u062C\u0648\u062F \u0628\u0627\u0634\u062F)",headers:["\u0634\u0645\u0627\u0631\u0647","\u0645\u0639\u06CC\u0627\u0631"],rows:[["\u06F1","\u0634\u0648\u0627\u0647\u062F \u0627\u0633\u06CC\u062F\u0648\u0632 \u0645\u062A\u0627\u0628\u0648\u0644\u06CC\u06A9 \u062F\u0631 \u062E\u0648\u0646 \u0634\u0631\u06CC\u0627\u0646 \u0628\u0646\u062F\u0646\u0627\u0641 \u062F\u0631 \u0632\u0645\u0627\u0646 \u0632\u0627\u06CC\u0645\u0627\u0646 (pH < \u06F7 \u0648 \u06A9\u0645\u0628\u0648\u062F \u0628\u0627\u0632 \u2265 \u06F1\u06F2 mmol/L)"],["\u06F2","\u0634\u0631\u0648\u0639 \u0632\u0648\u062F\u0631\u0633 \u0627\u0646\u0633\u0641\u0627\u0644\u0648\u067E\u0627\u062A\u06CC \u0645\u062A\u0648\u0633\u0637 \u062A\u0627 \u0634\u062F\u06CC\u062F \u0646\u0648\u0632\u0627\u062F\u06CC \u062F\u0631 \u0627\u0637\u0641\u0627\u0644 \u2265 \u06F3\u06F4 \u0647\u0641\u062A\u0647"],["\u06F3","\u0646\u0648\u0639 \u06A9\u0648\u0627\u062F\u0631\u06CC\u200C\u067E\u0644\u0698\u06CC \u0627\u0633\u067E\u0627\u0633\u062A\u06CC\u06A9 \u06CC\u0627 \u062F\u06CC\u0633\u200C\u06A9\u06CC\u0646\u062A\u06CC\u06A9 \u0627\u0632 \u0641\u0644\u062C \u0645\u063A\u0632\u06CC"],["\u06F4","\u0631\u062F \u0633\u0627\u06CC\u0631 \u0627\u062A\u06CC\u0648\u0644\u0648\u0698\u06CC\u200C\u0647\u0627\u06CC \u0642\u0627\u0628\u0644\u200C\u062A\u0634\u062E\u06CC\u0635 (\u0636\u0631\u0628\u0647\u060C \u0627\u062E\u062A\u0644\u0627\u0644\u0627\u062A \u0627\u0646\u0639\u0642\u0627\u062F\u06CC\u060C \u0639\u0641\u0648\u0646\u062A\u060C \u0627\u062E\u062A\u0644\u0627\u0644\u0627\u062A \u0698\u0646\u062A\u06CC\u06A9)"]]},callouts:[{kind:"warn",label:"\u0645\u062D\u062F\u0648\u062F\u06CC\u062A \u0645\u0627\u0646\u06CC\u062A\u0648\u0631\u06CC\u0646\u06AF \u0627\u0644\u06A9\u062A\u0631\u0648\u0646\u06CC\u06A9",html:"<p>\u0627\u0641\u0632\u0627\u06CC\u0634 \u0627\u0637\u0644\u0627\u0639\u0627\u062A \u062D\u0627\u0635\u0644 \u0627\u0632 \u0645\u0627\u0646\u06CC\u062A\u0648\u0631\u06CC\u0646\u06AF \u0627\u0644\u06A9\u062A\u0631\u0648\u0646\u06CC\u06A9 \u0644\u0632\u0648\u0645\u0627\u064B \u0628\u0647 \u0628\u0647\u0628\u0648\u062F \u067E\u06CC\u0627\u0645\u062F \u062C\u0646\u06CC\u0646 \u0645\u0646\u062C\u0631 \u0646\u0645\u06CC\u200C\u0634\u0648\u062F\u061B \u062F\u0631 \u062A\u0641\u0633\u06CC\u0631 \u0646\u0648\u0627\u0631\u0647\u0627\u06CC \u0642\u0644\u0628\u06CC\u060C \u0627\u062E\u062A\u0644\u0627\u0641\u200C\u0646\u0638\u0631 \u0642\u0627\u0628\u0644\u200C\u062A\u0648\u062C\u0647\u06CC \u0628\u06CC\u0646 \u0645\u062A\u062E\u0635\u0635\u0627\u0646 \u0648\u062C\u0648\u062F \u062F\u0627\u0631\u062F \u0648 \u062D\u062A\u06CC \u06CC\u06A9 \u0641\u0631\u062F \u0645\u0645\u06A9\u0646 \u0627\u0633\u062A \u0638\u0631\u0641 \u06CC\u06A9 \u0645\u0627\u0647 \u0646\u0638\u0631 \u062E\u0648\u062F \u0631\u0627 \u062F\u0631\u0628\u0627\u0631\u0647\u200C\u06CC \u0647\u0645\u0627\u0646 \u0646\u0648\u0627\u0631 \u062A\u063A\u06CC\u06CC\u0631 \u062F\u0647\u062F.</p>"}]},{heading:"\u0641\u0639\u0627\u0644\u06CC\u062A \u0631\u062D\u0645\u06CC \u0648 \u0627\u0646\u0642\u0628\u0627\u0636\u0627\u062A \u062D\u06CC\u0646 \u0632\u0627\u06CC\u0645\u0627\u0646",paragraphsHtml:['<p>\u0648\u0627\u062D\u062F \u0645\u0648\u0646\u062A\u0647\u200C\u0648\u06CC\u062F\u0626\u0648 (<span class="en">Montevideo unit</span>) \u0627\u0632 \u062D\u0627\u0635\u0644\u200C\u0636\u0631\u0628 \u0634\u062F\u062A \u0627\u0646\u0642\u0628\u0627\u0636 \u0631\u062D\u0645 (\u0628\u0631 \u062D\u0633\u0628 \u0645\u06CC\u0644\u06CC\u200C\u0645\u062A\u0631 \u062C\u06CC\u0648\u0647) \u062F\u0631 \u0641\u0631\u06A9\u0627\u0646\u0633 \u0627\u0646\u0642\u0628\u0627\u0636\u0627\u062A \u0637\u06CC \u06F1\u06F0 \u062F\u0642\u06CC\u0642\u0647 \u0628\u0647 \u062F\u0633\u062A \u0645\u06CC\u200C\u0622\u06CC\u062F. \u0637\u0648\u0644 \u0627\u0646\u0642\u0628\u0627\u0636\u0627\u062A \u0631\u062D\u0645\u06CC \u0627\u0632 \u0627\u0628\u062A\u062F\u0627\u06CC \u0641\u0627\u0632 \u0641\u0639\u0627\u0644 \u062A\u0627 \u0627\u0646\u062A\u0647\u0627\u06CC \u0645\u0631\u062D\u0644\u0647\u200C\u06CC \u062F\u0648\u0645 \u0646\u0633\u0628\u062A\u0627\u064B \u062B\u0627\u0628\u062A (\u06F6\u06F0 \u062A\u0627 \u06F8\u06F0 \u062B\u0627\u0646\u06CC\u0647) \u0628\u0627\u0642\u06CC \u0645\u06CC\u200C\u0645\u0627\u0646\u062F.</p>',"<p>\u062F\u0631 \u0632\u0646\u0627\u0646\u06CC \u06A9\u0647 \u0627\u06A9\u0633\u06CC\u200C\u062A\u0648\u0633\u06CC\u0646 \u062F\u0631\u06CC\u0627\u0641\u062A \u0645\u06CC\u200C\u06A9\u0646\u0646\u062F\u060C \u0641\u0639\u0627\u0644\u06CC\u062A \u0631\u062D\u0645\u06CC \u0645\u0639\u0645\u0648\u0644\u0627\u064B \u06F2\u06F0\u06F0 \u062A\u0627 \u06F2\u06F2\u06F5 \u0648\u0627\u062D\u062F \u0645\u0648\u0646\u062A\u0647\u200C\u0648\u06CC\u062F\u0626\u0648 \u0627\u06CC\u062C\u0627\u062F \u0645\u06CC\u200C\u0634\u0648\u062F (\u062F\u0631 \u06F4\u06F0\u066A \u0645\u0648\u0627\u0631\u062F \u062A\u0627 \u06F3\u06F0\u06F0 \u0648\u0627\u062D\u062F)\u061B \u0627\u06CC\u0646 \u0633\u0637\u062D \u0628\u0627\u06CC\u062F \u067E\u06CC\u0634 \u0627\u0632 \u062A\u0634\u062E\u06CC\u0635 \u062F\u06CC\u0633\u062A\u0648\u0634\u06CC \u0628\u0631\u0642\u0631\u0627\u0631 \u0634\u062F\u0647 \u0628\u0627\u0634\u062F. \u0627\u0646\u0642\u0628\u0627\u0636\u0627\u062A \u0645\u0646\u0638\u0645 \u0627\u0645\u0627 \u0647\u06CC\u067E\u0648\u062A\u0648\u0646\u06CC\u06A9 (\u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F2 \u0627\u0646\u0642\u0628\u0627\u0636 \u062F\u0631 \u06F1\u06F0 \u062F\u0642\u06CC\u0642\u0647 \u0628\u0627 \u0634\u062F\u062A \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F2\u06F5 \u0645\u06CC\u0644\u06CC\u200C\u0645\u062A\u0631 \u062C\u06CC\u0648\u0647) \u0628\u0627 \u06A9\u0646\u062F\u06CC \u0633\u06CC\u0631 \u0632\u0627\u06CC\u0645\u0627\u0646 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062A.</p>"],table:{caption:"\u0627\u0631\u062A\u0628\u0627\u0637 \u0641\u0634\u0627\u0631 \u062F\u0627\u062E\u0644 \u0631\u062D\u0645\u06CC \u0628\u0627 \u067E\u062F\u06CC\u062F\u0647\u200C\u0647\u0627\u06CC \u0628\u0627\u0644\u06CC\u0646\u06CC",headers:["\u0641\u0634\u0627\u0631","\u067E\u062F\u06CC\u062F\u0647"],rows:[["\u06F8\u06F0 \u062A\u0627 \u06F1\u06F2\u06F0 \u0648\u0627\u062D\u062F \u0645\u0648\u0646\u062A\u0647\u200C\u0648\u06CC\u062F\u0626\u0648","\u0632\u0627\u06CC\u0645\u0627\u0646 \u0628\u0627\u0644\u06CC\u0646\u06CC"],["\u06F1\u06F0 mmHg","\u0642\u0627\u0628\u0644\u06CC\u062A \u0644\u0645\u0633 \u0628\u0627\u0644\u06CC\u0646\u06CC \u0627\u0646\u0642\u0628\u0627\u0636\u0627\u062A"],["\u06F1\u06F5 mmHg","\u0627\u06CC\u062C\u0627\u062F \u062F\u0631\u062F"],["\u06F4\u06F0 mmHg","\u0627\u0632 \u0628\u06CC\u0646 \u0631\u0641\u062A\u0646 \u0642\u0627\u0628\u0644\u06CC\u062A \u06AF\u0648\u062F\u0647\u200C\u06AF\u0630\u0627\u0631\u06CC \u0631\u0648\u06CC \u0631\u062D\u0645"],["\u06F2\u06F5 \u062A\u0627 \u06F5\u06F0 mmHg","\u0634\u062F\u062A \u0627\u0646\u0642\u0628\u0627\u0636\u0627\u062A \u2014 \u0645\u0631\u062D\u0644\u0647\u200C\u06CC \u0627\u0648\u0644 \u0632\u0627\u06CC\u0645\u0627\u0646"],["\u06F8 \u062A\u0627 \u06F1\u06F2 mmHg","\u062A\u0648\u0646 \u0628\u0627\u0632\u0627\u0644 \u0631\u062D\u0645 \u2014 \u0645\u0631\u062D\u0644\u0647\u200C\u06CC \u0627\u0648\u0644 \u0632\u0627\u06CC\u0645\u0627\u0646"],["\u06F8\u06F0 \u062A\u0627 \u06F1\u06F0\u06F0 mmHg","\u0634\u062F\u062A \u0627\u0646\u0642\u0628\u0627\u0636\u0627\u062A \u2014 \u0645\u0631\u062D\u0644\u0647\u200C\u06CC \u062F\u0648\u0645 \u0632\u0627\u06CC\u0645\u0627\u0646"]]},figures:[{src:"figures/180_uterine-contraction-wave-intensity.jpg",captionFa:"\u0646\u0645\u0627\u06CC \u0634\u0645\u0627\u062A\u06CC\u06A9 \u0645\u0648\u062C \u0637\u0628\u06CC\u0639\u06CC \u0627\u0646\u0642\u0628\u0627\u0636\u06CC \u0631\u062D\u0645\u06CC: \u0634\u062F\u062A \u0627\u0646\u0642\u0628\u0627\u0636 \u062F\u0631 \u0641\u0648\u0646\u062F\u0648\u0633 \u0628\u06CC\u0634\u062A\u0631 \u0627\u0632 \u0633\u06AF\u0645\u0627\u0646 \u062A\u062D\u062A\u0627\u0646\u06CC \u0627\u0633\u062A \u0627\u0645\u0627 \u0647\u0645\u0647\u200C\u06CC \u0646\u0648\u0627\u062D\u06CC \u0647\u0645\u200C\u0632\u0645\u0627\u0646 \u0628\u0647 \u0641\u0634\u0627\u0631 \u062D\u062F\u0627\u06A9\u062B\u0631 \u0645\u06CC\u200C\u0631\u0633\u0646\u062F."}]},{heading:"\u0622\u0645\u0646\u06CC\u0648\u0627\u0646\u0641\u0648\u0632\u06CC\u0648\u0646",paragraphsHtml:["<p>\u062A\u0632\u0631\u06CC\u0642 \u0633\u0627\u0644\u06CC\u0646 \u0628\u0647 \u062F\u0627\u062E\u0644 \u062D\u0641\u0631\u0647\u200C\u06CC \u0622\u0645\u0646\u06CC\u0648\u0646\u06CC \u0627\u0632 \u0631\u0627\u0647 \u0648\u0627\u0698\u0646 \u0628\u0627 \u0633\u0647 \u0647\u062F\u0641 \u0627\u0646\u062C\u0627\u0645 \u0645\u06CC\u200C\u0634\u0648\u062F: \u062F\u0631\u0645\u0627\u0646 \u0627\u0641\u062A\u200C\u0647\u0627\u06CC \u0645\u062A\u063A\u06CC\u0631 \u06CC\u0627 \u0637\u0648\u0644\u0627\u0646\u06CC\u200C\u0645\u062F\u062A \u0646\u0627\u0634\u06CC \u0627\u0632 \u06AF\u06CC\u0631\u0627\u0641\u062A\u0627\u062F\u0646 \u0628\u0646\u062F\u0646\u0627\u0641\u060C \u067E\u06CC\u0634\u06AF\u06CC\u0631\u06CC \u062F\u0631 \u0627\u0648\u0644\u06CC\u06AF\u0648\u0647\u06CC\u062F\u0631\u0622\u0645\u0646\u06CC\u0648\u0633 \u0634\u0646\u0627\u062E\u062A\u0647\u200C\u0634\u062F\u0647 (\u0645\u0627\u0646\u0646\u062F \u067E\u0627\u0631\u06AF\u06CC \u0637\u0648\u0644\u0627\u0646\u06CC \u067E\u0631\u062F\u0647\u200C\u0647\u0627)\u060C \u0648 \u0631\u0642\u06CC\u0642\u200C\u06A9\u0631\u062F\u0646 \u06CC\u0627 \u062E\u0627\u0631\u062C\u200C\u06A9\u0631\u062F\u0646 \u0645\u06A9\u0648\u0646\u06CC\u0648\u0645 \u063A\u0644\u06CC\u0638. \u0627\u06A9\u062B\u0631 \u067E\u0631\u0648\u062A\u06A9\u0644\u200C\u0647\u0627 \u0634\u0627\u0645\u0644 \u062A\u0632\u0631\u06CC\u0642 \u06F5\u06F0\u06F0 \u062A\u0627 \u06F8\u06F0\u06F0 \u0645\u06CC\u0644\u06CC\u200C\u0644\u06CC\u062A\u0631 \u0646\u0631\u0645\u0627\u0644\u200C\u0633\u0627\u0644\u06CC\u0646 \u0648\u0644\u0631\u0645 \u0648 \u0633\u067E\u0633 \u0627\u0646\u0641\u0648\u0632\u06CC\u0648\u0646 \u0645\u062F\u0627\u0648\u0645 \u0627\u0633\u062A.</p>","<p>\u0639\u0648\u0627\u0631\u0636 \u0628\u0627\u0644\u0642\u0648\u0647\u200C\u06CC \u0622\u0645\u0646\u06CC\u0648\u0627\u0646\u0641\u0648\u0632\u06CC\u0648\u0646 \u0634\u0627\u0645\u0644 \u0647\u06CC\u067E\u0631\u062A\u0648\u0646\u06CC\u0633\u06CC\u062A\u0647\u200C\u06CC \u0631\u062D\u0645\u06CC\u060C \u0622\u0631\u06CC\u062A\u0645\u06CC \u0642\u0644\u0628\u06CC \u062C\u0646\u06CC\u0646\u060C \u06A9\u0648\u0631\u06CC\u0648\u0622\u0645\u0646\u06CC\u0648\u0646\u06CC\u062A\u060C \u067E\u0631\u0648\u0644\u0627\u067E\u0633 \u0628\u0646\u062F\u0646\u0627\u0641\u060C \u067E\u0627\u0631\u06AF\u06CC \u0631\u062D\u0645\u060C \u0627\u062E\u062A\u0644\u0627\u0644\u0627\u062A \u0642\u0644\u0628\u06CC-\u062A\u0646\u0641\u0633\u06CC \u0645\u0627\u062F\u0631\u060C \u06A9\u0646\u062F\u06AF\u06CC \u062C\u0641\u062A \u0648 \u062F\u0631 \u0645\u0648\u0627\u0631\u062F \u0646\u0627\u062F\u0631 \u0645\u0631\u06AF \u0645\u0627\u062F\u0631 \u0627\u0633\u062A. \u0646\u062A\u0627\u06CC\u062C \u0645\u0637\u0627\u0644\u0639\u0627\u062A \u062F\u0631\u0628\u0627\u0631\u0647\u200C\u06CC \u0627\u062B\u0631 \u0622\u0645\u0646\u06CC\u0648\u0627\u0646\u0641\u0648\u0632\u06CC\u0648\u0646 \u062F\u0631 \u0645\u06A9\u0648\u0646\u06CC\u0648\u0645 \u063A\u0644\u06CC\u0638 \u0645\u062A\u0646\u0627\u0642\u0636 \u0628\u0648\u062F\u0647 \u0648 \u0647\u0645\u06CC\u0634\u0647 \u0633\u0628\u0628 \u0628\u0647\u0628\u0648\u062F \u0642\u0637\u0639\u06CC \u067E\u06CC\u0627\u0645\u062F \u0646\u0648\u0632\u0627\u062F\u06CC \u0646\u0634\u062F\u0647 \u0627\u0633\u062A.</p>"]}],quiz:[{id:"p2ch18-q1",type:"mcq",question:"\u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u067E\u0627\u06CC\u0647\u200C\u06CC \u062C\u0646\u06CC\u0646 \u0637\u0628\u0642 \u062A\u0639\u0631\u06CC\u0641 NICHD \u062F\u0631 \u0686\u0647 \u0628\u0627\u0632\u0647\u200C\u0627\u06CC \u0637\u0628\u06CC\u0639\u06CC \u0645\u062D\u0633\u0648\u0628 \u0645\u06CC\u200C\u0634\u0648\u062F\u061F",choices:["\u06F1\u06F0\u06F0 \u062A\u0627 \u06F1\u06F5\u06F0 bpm","\u06F1\u06F1\u06F0 \u062A\u0627 \u06F1\u06F6\u06F0 bpm","\u06F1\u06F2\u06F0 \u062A\u0627 \u06F1\u06F8\u06F0 bpm","\u06F9\u06F0 \u062A\u0627 \u06F1\u06F4\u06F0 bpm"],correctIndex:1,explanation:"\u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u067E\u0627\u06CC\u0647 \u0628\u06CC\u0646 \u06F1\u06F1\u06F0 \u062A\u0627 \u06F1\u06F6\u06F0 \u0636\u0631\u0628\u0647 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647 \u0637\u0628\u06CC\u0639\u06CC \u0627\u0633\u062A\u061B \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F1\u06F1\u06F0 \u0628\u0631\u0627\u062F\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC \u0648 \u0628\u06CC\u0634\u062A\u0631 \u0627\u0632 \u06F1\u06F6\u06F0 \u062A\u0627\u06A9\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC \u0645\u062D\u0633\u0648\u0628 \u0645\u06CC\u200C\u0634\u0648\u062F."},{id:"p2ch18-q2",type:"mcq",question:"\u0634\u0627\u06CC\u0639\u200C\u062A\u0631\u06CC\u0646 \u0639\u0644\u062A \u062A\u0627\u06A9\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC \u062C\u0646\u06CC\u0646 \u06A9\u062F\u0627\u0645 \u0627\u0633\u062A\u061F",choices:["\u0628\u0644\u0648\u06A9 \u0642\u0644\u0628\u06CC \u0645\u0627\u062F\u0631\u0632\u0627\u062F\u06CC","\u062A\u0628 \u0645\u0627\u062F\u0631 \u0646\u0627\u0634\u06CC \u0627\u0632 \u0622\u0645\u0646\u06CC\u0648\u0646\u06CC\u062A","\u0647\u06CC\u067E\u0648\u062A\u0631\u0645\u06CC \u0645\u0627\u062F\u0631","\u0645\u0635\u0631\u0641 \u0633\u0648\u0644\u0641\u0627\u062A \u0645\u0646\u06CC\u0632\u06CC\u0645"],correctIndex:1,explanation:"\u0634\u0627\u06CC\u0639\u200C\u062A\u0631\u06CC\u0646 \u0639\u0644\u062A \u062A\u0627\u06A9\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC \u062C\u0646\u06CC\u0646\u060C \u062A\u0628 \u0645\u0627\u062F\u0631 \u0627\u0633\u062A \u06A9\u0647 \u063A\u0627\u0644\u0628\u0627\u064B \u0646\u0627\u0634\u06CC \u0627\u0632 \u0622\u0645\u0646\u06CC\u0648\u0646\u06CC\u062A \u0627\u0633\u062A."},{id:"p2ch18-q3",type:"mcq",question:"\u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u067E\u0627\u06CC\u0647\u200C\u0627\u06CC \xAB\u0645\u062A\u0648\u0633\u0637\xBB \u06CC\u0627 \u0637\u0628\u06CC\u0639\u06CC \u0637\u0628\u0642 \u0637\u0628\u0642\u0647\u200C\u0628\u0646\u062F\u06CC NICHD \u062F\u0631 \u0686\u0647 \u0628\u0627\u0632\u0647\u200C\u0627\u06CC \u0642\u0631\u0627\u0631 \u062F\u0627\u0631\u062F\u061F",choices:["\u06F0 \u062A\u0627 \u06F5 bpm","\u06F6 \u062A\u0627 \u06F2\u06F5 bpm","\u06F2\u06F6 \u062A\u0627 \u06F4\u06F0 bpm","\u0628\u06CC\u0634\u062A\u0631 \u0627\u0632 \u06F4\u06F0 bpm"],correctIndex:1,explanation:"\u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0645\u062A\u0648\u0633\u0637 (\u0637\u0628\u06CC\u0639\u06CC) \u062F\u0627\u0645\u0646\u0647\u200C\u06CC \u06F6 \u062A\u0627 \u06F2\u06F5 \u0636\u0631\u0628\u0647 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647 \u062F\u0627\u0631\u062F\u061B \u062C\u0632\u0626\u06CC \u2264\u06F5\u060C \u0634\u062F\u06CC\u062F >\u06F2\u06F5 \u0648 \u0641\u0642\u062F\u0627\u0646 \u06CC\u0639\u0646\u06CC \u063A\u06CC\u0631\u0642\u0627\u0628\u0644\u200C\u06A9\u0634\u0641 \u0627\u0633\u062A."},{id:"p2ch18-q4",type:"mcq",question:"\u06A9\u0627\u0647\u0634 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0636\u0631\u0628\u0627\u0646 \u0628\u0647 \u0636\u0631\u0628\u0627\u0646 \u062C\u0646\u06CC\u0646\u060C \u0627\u0632 \u0646\u0638\u0631 \u067E\u0627\u062A\u0648\u0641\u06CC\u0632\u06CC\u0648\u0644\u0648\u0698\u06CC\u06A9 \u0628\u06CC\u0634\u062A\u0631 \u0645\u0646\u0639\u06A9\u0633\u200C\u06A9\u0646\u0646\u062F\u0647\u200C\u06CC \u06A9\u062F\u0627\u0645 \u0627\u0633\u062A\u061F",choices:["\u0647\u06CC\u067E\u0648\u06A9\u0633\u06CC \u062E\u0641\u06CC\u0641 \u0627\u0648\u0644\u06CC\u0647","\u0627\u0633\u06CC\u062F\u0645\u06CC \u0645\u062A\u0627\u0628\u0648\u0644\u06CC\u06A9 \u0648 \u0627\u062B\u0631 \u0645\u0647\u0627\u0631\u06CC \u0622\u0646 \u0628\u0631 \u0633\u0627\u0642\u0647\u200C\u06CC \u0645\u063A\u0632/\u0642\u0644\u0628","\u0627\u0641\u0632\u0627\u06CC\u0634 \u0641\u0639\u0627\u0644\u06CC\u062A \u067E\u0627\u0631\u0627\u0633\u0645\u067E\u0627\u062A\u06CC\u06A9 \u0637\u0628\u06CC\u0639\u06CC","\u062E\u0648\u0627\u0628 \u0641\u06CC\u0632\u06CC\u0648\u0644\u0648\u0698\u06CC\u06A9 \u062C\u0646\u06CC\u0646 \u0628\u0647\u200C\u062A\u0646\u0647\u0627\u06CC\u06CC"],correctIndex:1,explanation:"\u0627\u0632 \u062F\u0633\u062A \u0631\u0641\u062A\u0646 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u062F\u0631 \u062C\u0646\u06CC\u0646 \u0628\u062F\u062D\u0627\u0644 \u0645\u062D\u062A\u0645\u0644\u0627\u064B \u0628\u0627\u0632\u062A\u0627\u0628 \u0627\u0633\u06CC\u062F\u0645\u06CC \u0627\u0633\u062A\u060C \u0628\u0647 \u0639\u0644\u062A \u0627\u062B\u0631 \u0645\u0647\u0627\u0631\u06CC \u0627\u0633\u06CC\u062F\u0648\u0632 \u0645\u062A\u0627\u0628\u0648\u0644\u06CC\u06A9 \u0628\u0631 \u0633\u0627\u0642\u0647\u200C\u06CC \u0645\u063A\u0632 \u06CC\u0627 \u0645\u06CC\u0648\u06A9\u0627\u0631\u062F\u061B \u0647\u06CC\u067E\u0648\u06A9\u0633\u0645\u06CC \u062E\u0641\u06CC\u0641 \u062F\u0631 \u0627\u0628\u062A\u062F\u0627 \u062D\u062A\u06CC \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u062F \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0631\u0627 \u0627\u0641\u0632\u0627\u06CC\u0634 \u062F\u0647\u062F."},{id:"p2ch18-q5",type:"mcq",question:"\u0628\u0631\u0627\u06CC \u06CC\u06A9 \u062C\u0646\u06CC\u0646 \u0628\u0627\u0644\u0627\u06CC \u0647\u0641\u062A\u0647\u200C\u06CC \u06F3\u06F2 \u062D\u0627\u0645\u0644\u06AF\u06CC\u060C \u0645\u0639\u06CC\u0627\u0631 \u062A\u0633\u0631\u06CC\u0639 (acceleration) \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u06A9\u062F\u0627\u0645 \u0627\u0633\u062A\u061F",choices:["\u0627\u0641\u0632\u0627\u06CC\u0634 \u2265\u06F5 bpm \u0628\u0647 \u0645\u062F\u062A \u2265\u06F5 \u062B\u0627\u0646\u06CC\u0647","\u0627\u0641\u0632\u0627\u06CC\u0634 \u2265\u06F1\u06F0 bpm \u0628\u0647 \u0645\u062F\u062A \u2265\u06F1\u06F0 \u062B\u0627\u0646\u06CC\u0647","\u0627\u0641\u0632\u0627\u06CC\u0634 \u2265\u06F1\u06F5 bpm \u0628\u0647 \u0645\u062F\u062A \u2265\u06F1\u06F5 \u062B\u0627\u0646\u06CC\u0647 \u0627\u0645\u0627 \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F2 \u062F\u0642\u06CC\u0642\u0647","\u0627\u0641\u0632\u0627\u06CC\u0634 \u2265\u06F2\u06F5 bpm \u0628\u0647 \u0645\u062F\u062A \u2265\u06F3\u06F0 \u062B\u0627\u0646\u06CC\u0647"],correctIndex:2,explanation:"\u0628\u0639\u062F \u0627\u0632 \u0647\u0641\u062A\u0647\u200C\u06CC \u06F3\u06F2\u060C \u062A\u0633\u0631\u06CC\u0639 \u0628\u0627\u06CC\u062F \u0627\u0648\u062C\u06CC \u2265\u06F1\u06F5 bpm \u0628\u0627\u0644\u0627\u06CC \u062E\u0637 \u067E\u0627\u06CC\u0647 \u0648 \u0645\u062F\u062A \u2265\u06F1\u06F5 \u062B\u0627\u0646\u06CC\u0647 \u0627\u0645\u0627 \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F2 \u062F\u0642\u06CC\u0642\u0647 \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u062F (\u0642\u0628\u0644 \u0627\u0632 \u06F3\u06F2 \u0647\u0641\u062A\u0647: \u2265\u06F1\u06F0 bpm \u0648 \u2265\u06F1\u06F0 \u062B\u0627\u0646\u06CC\u0647)."},{id:"p2ch18-q6",type:"mcq",question:"\u062F\u0631 \u06CC\u06A9 \u0646\u0648\u0627\u0631 \u0645\u0627\u0646\u06CC\u062A\u0648\u0631\u06CC\u0646\u06AF\u060C \u0627\u0641\u062A \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u0647\u0645\u200C\u0632\u0645\u0627\u0646 \u0628\u0627 \u0634\u0631\u0648\u0639 \u0627\u0646\u0642\u0628\u0627\u0636 \u0634\u0631\u0648\u0639 \u0634\u062F\u0647\u060C \u062A\u062F\u0631\u06CC\u062C\u06CC \u0648 \u0645\u062A\u0642\u0627\u0631\u0646 \u0627\u0633\u062A \u0648 \u0628\u0627 \u067E\u0627\u06CC\u0627\u0646 \u0627\u0646\u0642\u0628\u0627\u0636 \u0628\u0647 \u062E\u0637 \u067E\u0627\u06CC\u0647 \u0628\u0631\u0645\u06CC\u200C\u06AF\u0631\u062F\u062F. \u0627\u06CC\u0646 \u0627\u0644\u06AF\u0648 \u0686\u0647 \u0646\u0627\u0645 \u062F\u0627\u0631\u062F \u0648 \u0645\u06A9\u0627\u0646\u06CC\u0633\u0645 \u0622\u0646 \u06A9\u062F\u0627\u0645 \u0627\u0633\u062A\u061F",choices:["\u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633\u061B \u0646\u0627\u0631\u0633\u0627\u06CC\u06CC \u0631\u062D\u0645\u06CC-\u062C\u0641\u062A\u06CC","\u0627\u0641\u062A \u0632\u0648\u062F\u0631\u0633\u061B \u0641\u0634\u0627\u0631 \u0628\u0647 \u0633\u0631 \u0648 \u062A\u062D\u0631\u06CC\u06A9 \u0648\u0627\u06AF","\u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631\u061B \u0627\u0646\u0633\u062F\u0627\u062F \u0628\u0646\u062F\u0646\u0627\u0641","\u0627\u0641\u062A \u0637\u0648\u0644\u0627\u0646\u06CC\u200C\u0645\u062F\u062A\u061B \u0647\u06CC\u067E\u0648\u062A\u0627\u0646\u0633\u06CC\u0648\u0646 \u0645\u0627\u062F\u0631"],correctIndex:1,explanation:"\u0627\u0641\u062A \u0632\u0648\u062F\u0631\u0633 \u0628\u0627 \u0634\u0631\u0648\u0639/\u0627\u0648\u062C/\u067E\u0627\u06CC\u0627\u0646 \u0627\u0646\u0642\u0628\u0627\u0636 \u0647\u0645\u200C\u0632\u0645\u0627\u0646 \u0627\u0633\u062A \u0648 \u0645\u06A9\u0627\u0646\u06CC\u0633\u0645 \u0622\u0646 \u0641\u0634\u0627\u0631 \u0628\u0647 \u0633\u0631 \u062C\u0646\u06CC\u0646 \u0648 \u062A\u062D\u0631\u06CC\u06A9 \u0648\u0627\u06AF \u0627\u0632 \u0637\u0631\u06CC\u0642 \u062A\u062D\u0631\u06CC\u06A9 \u062F\u0648\u0631\u0627 \u0627\u0633\u062A\u061B \u0641\u06CC\u0632\u06CC\u0648\u0644\u0648\u0698\u06CC\u06A9 \u0648 \u0628\u06CC\u200C\u062E\u0637\u0631 \u062A\u0644\u0642\u06CC \u0645\u06CC\u200C\u0634\u0648\u062F."},{id:"p2ch18-q7",type:"mcq",question:"\u062F\u0631 \u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628\u060C \u0634\u0631\u0648\u0639\u060C \u062D\u062F\u0627\u0642\u0644 \u0648 \u0628\u0627\u0632\u06AF\u0634\u062A \u0622\u0646 \u0646\u0633\u0628\u062A \u0628\u0647 \u0627\u0646\u0642\u0628\u0627\u0636 \u0631\u062D\u0645\u06CC \u0686\u06AF\u0648\u0646\u0647 \u0627\u0633\u062A\u061F",choices:["\u0647\u0645\u200C\u0632\u0645\u0627\u0646 \u0628\u0627 \u0634\u0631\u0648\u0639\u060C \u0627\u0648\u062C \u0648 \u067E\u0627\u06CC\u0627\u0646 \u0627\u0646\u0642\u0628\u0627\u0636","\u0647\u0645\u0647 \u067E\u0633 \u0627\u0632 \u0634\u0631\u0648\u0639\u060C \u0627\u0648\u062C \u0648 \u067E\u0627\u06CC\u0627\u0646 \u0627\u0646\u0642\u0628\u0627\u0636 \u0631\u062E \u0645\u06CC\u200C\u062F\u0647\u0646\u062F","\u0647\u0645\u0647 \u067E\u06CC\u0634 \u0627\u0632 \u0634\u0631\u0648\u0639 \u0627\u0646\u0642\u0628\u0627\u0636 \u0631\u062E \u0645\u06CC\u200C\u062F\u0647\u0646\u062F","\u0627\u0631\u062A\u0628\u0627\u0637\u06CC \u0628\u0627 \u0632\u0645\u0627\u0646 \u0627\u0646\u0642\u0628\u0627\u0636 \u0646\u062F\u0627\u0631\u0646\u062F"],correctIndex:1,explanation:"\u062F\u0631 \u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633\u060C \u0634\u0631\u0648\u0639\u060C \u062D\u062F\u0627\u0642\u0644 \u0648 \u0628\u0627\u0632\u06AF\u0634\u062A \u0628\u0647\u200C\u062A\u0631\u062A\u06CC\u0628 \u067E\u0633 \u0627\u0632 \u0634\u0631\u0648\u0639\u060C \u0627\u0648\u062C \u0648 \u067E\u0627\u06CC\u0627\u0646 \u0627\u0646\u0642\u0628\u0627\u0636 \u0631\u062D\u0645\u06CC \u0631\u062E \u0645\u06CC\u200C\u062F\u0647\u0646\u062F \u06A9\u0647 \u0646\u0634\u0627\u0646\u200C\u062F\u0647\u0646\u062F\u0647\u200C\u06CC \u062A\u0623\u062E\u06CC\u0631 \u062F\u0631 \u067E\u0627\u0633\u062E \u0628\u0647 \u06A9\u0627\u0647\u0634 \u0627\u06A9\u0633\u06CC\u0698\u0646\u0627\u0633\u06CC\u0648\u0646 \u0631\u062D\u0645\u06CC-\u062C\u0641\u062A\u06CC \u0627\u0633\u062A."},{id:"p2ch18-q8",type:"mcq",question:"\u0634\u0627\u06CC\u0639\u200C\u062A\u0631\u06CC\u0646 \u0639\u0644\u0644 \u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633 \u06A9\u062F\u0627\u0645\u200C\u0627\u0646\u062F\u061F",choices:["\u0647\u06CC\u067E\u0648\u062A\u0627\u0646\u0633\u06CC\u0648\u0646 \u0646\u0627\u0634\u06CC \u0627\u0632 \u0628\u06CC\u200C\u062D\u0633\u06CC \u0627\u067E\u06CC\u062F\u0648\u0631\u0627\u0644 \u0648 \u0647\u06CC\u067E\u0631\u0627\u0633\u062A\u06CC\u0645\u0648\u0644\u0627\u0633\u06CC\u0648\u0646 \u0631\u062D\u0645 \u0628\u0627 \u0627\u06A9\u0633\u06CC\u200C\u062A\u0648\u0633\u06CC\u0646","\u0627\u0646\u0633\u062F\u0627\u062F \u0628\u0646\u062F\u0646\u0627\u0641 \u0648 \u0641\u0634\u0627\u0631 \u0628\u0647 \u0633\u0631 \u062C\u0646\u06CC\u0646","\u062E\u0648\u0627\u0628 \u0641\u06CC\u0632\u06CC\u0648\u0644\u0648\u0698\u06CC\u06A9 \u062C\u0646\u06CC\u0646","\u0645\u0635\u0631\u0641 \u06A9\u0627\u0641\u0626\u06CC\u0646 \u0645\u0627\u062F\u0631"],correctIndex:0,explanation:"\u0634\u0627\u06CC\u0639\u200C\u062A\u0631\u06CC\u0646 \u0639\u0644\u0644 \u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633\u060C \u0647\u06CC\u067E\u0648\u062A\u0627\u0646\u0633\u06CC\u0648\u0646 \u0646\u0627\u0634\u06CC \u0627\u0632 \u0628\u06CC\u200C\u062D\u0633\u06CC \u0627\u067E\u06CC\u062F\u0648\u0631\u0627\u0644 \u0648 \u0647\u06CC\u067E\u0631\u0627\u06A9\u062A\u06CC\u0648\u06CC\u062A\u06CC \u0631\u062D\u0645 \u0628\u0647 \u0639\u0644\u062A \u062A\u062D\u0631\u06CC\u06A9 \u0628\u0627 \u0633\u0646\u062A\u0648\u0633\u06CC\u0646\u0648\u0646 \u0647\u0633\u062A\u0646\u062F."},{id:"p2ch18-q9",type:"mcq",question:"\u0634\u0627\u06CC\u0639\u200C\u062A\u0631\u06CC\u0646 \u0646\u0648\u0639 \u0627\u0641\u062A \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062D\u06CC\u0646 \u0632\u0627\u06CC\u0645\u0627\u0646 \u06A9\u062F\u0627\u0645 \u0627\u0633\u062A \u0648 \u0628\u0647 \u0686\u0647 \u0639\u0644\u062A\u06CC \u0646\u0633\u0628\u062A \u062F\u0627\u062F\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F\u061F",choices:["\u0627\u0641\u062A \u0632\u0648\u062F\u0631\u0633\u061B \u0641\u0634\u0627\u0631 \u0628\u0647 \u0633\u0631","\u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633\u061B \u0646\u0627\u0631\u0633\u0627\u06CC\u06CC \u062C\u0641\u062A\u06CC","\u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631\u061B \u0627\u0646\u0633\u062F\u0627\u062F \u0628\u0646\u062F\u0646\u0627\u0641","\u0627\u0641\u062A \u0637\u0648\u0644\u0627\u0646\u06CC\u200C\u0645\u062F\u062A\u061B \u062A\u0634\u0646\u062C \u0645\u0627\u062F\u0631"],correctIndex:2,explanation:"\u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631 \u0634\u0627\u06CC\u0639\u200C\u062A\u0631\u06CC\u0646 \u0646\u0648\u0639 \u06A9\u0646\u062F\u06CC \u062D\u06CC\u0646 \u0632\u0627\u06CC\u0645\u0627\u0646 \u0627\u0633\u062A \u0648 \u0628\u0647 \u0627\u0646\u0633\u062F\u0627\u062F \u06A9\u0648\u0631\u062F \u0646\u0633\u0628\u062A \u062F\u0627\u062F\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F\u061B \u062F\u0631 \u06CC\u06A9 \u0645\u0637\u0627\u0644\u0639\u0647 \u062F\u0631 \u06F8\u06F3\u066A \u0632\u0627\u06CC\u0645\u0627\u0646\u200C\u0647\u0627 \u0628\u0627 \u062F\u06CC\u0644\u0627\u062A\u0627\u0633\u06CC\u0648\u0646 \u06F5cm \u062F\u06CC\u062F\u0647 \u0634\u062F\u0647 \u0627\u0633\u062A."},{id:"p2ch18-q10",type:"mcq",question:"\u06A9\u062F\u0627\u0645 \u0645\u0639\u06CC\u0627\u0631\u060C \u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631 \xAB\u062E\u0637\u06CC\u0631\xBB (\u0646\u06AF\u0631\u0627\u0646\u200C\u06A9\u0646\u0646\u062F\u0647) \u0631\u0627 \u062A\u0639\u0631\u06CC\u0641 \u0645\u06CC\u200C\u06A9\u0646\u062F\u061F",choices:["\u0636\u0631\u0628\u0627\u0646 \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F1\u06F0\u06F0 bpm \u0628\u0647 \u0645\u062F\u062A \u06F1\u06F0 \u062B\u0627\u0646\u06CC\u0647","\u0636\u0631\u0628\u0627\u0646 \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F7\u06F0 bpm \u0648 \u0628\u06CC\u0634 \u0627\u0632 \u06F6\u06F0 \u062B\u0627\u0646\u06CC\u0647 \u0637\u0648\u0644 \u06A9\u0634\u06CC\u062F\u0646","\u0647\u0631 \u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631 \u0628\u0627 \u0634\u0627\u0646\u0647\u200C\u06CC \u062A\u0633\u0631\u06CC\u0639","\u0627\u0641\u062A \u0628\u0627 \u0634\u0631\u0648\u0639 \u062A\u062F\u0631\u06CC\u062C\u06CC \u0628\u06CC\u0634 \u0627\u0632 \u06F3\u06F0 \u062B\u0627\u0646\u06CC\u0647"],correctIndex:1,explanation:"\u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631 \u0646\u06AF\u0631\u0627\u0646\u200C\u06A9\u0646\u0646\u062F\u0647 \u0648\u0642\u062A\u06CC \u0627\u0633\u062A \u06A9\u0647 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u0628\u0647 \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F7\u06F0 \u0636\u0631\u0628\u0647 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647 \u0628\u0631\u0633\u062F \u0648 \u0628\u06CC\u0634 \u0627\u0632 \u06F6\u06F0 \u062B\u0627\u0646\u06CC\u0647 \u062F\u0631 \u0627\u06CC\u0646 \u062D\u0627\u0644\u062A \u0628\u0627\u0642\u06CC \u0628\u0645\u0627\u0646\u062F."},{id:"p2ch18-q11",type:"mcq",question:"\u0627\u0641\u062A \u0637\u0648\u0644\u0627\u0646\u06CC\u200C\u0645\u062F\u062A (Prolonged deceleration) \u0637\u0628\u0642 \u062A\u0639\u0631\u06CC\u0641 NICHD \u0686\u0647 \u0645\u062F\u062A \u0637\u0648\u0644 \u0645\u06CC\u200C\u06A9\u0634\u062F\u061F",choices:["\u06F1\u06F5 \u062B\u0627\u0646\u06CC\u0647 \u062A\u0627 \u06F2 \u062F\u0642\u06CC\u0642\u0647","\u06F2 \u062F\u0642\u06CC\u0642\u0647 \u062A\u0627 \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F1\u06F0 \u062F\u0642\u06CC\u0642\u0647","\u06F1\u06F0 \u062A\u0627 \u06F2\u06F0 \u062F\u0642\u06CC\u0642\u0647","\u0628\u06CC\u0634\u062A\u0631 \u0627\u0632 \u06F2\u06F0 \u062F\u0642\u06CC\u0642\u0647"],correctIndex:1,explanation:"\u0627\u0641\u062A \u0637\u0648\u0644\u0627\u0646\u06CC\u200C\u0645\u062F\u062A \u06A9\u0627\u0647\u0634 \u2265\u06F1\u06F5 bpm \u0628\u0647 \u0645\u062F\u062A \u2265\u06F2 \u062F\u0642\u06CC\u0642\u0647 \u0627\u0645\u0627 \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F1\u06F0 \u062F\u0642\u06CC\u0642\u0647 \u0627\u0633\u062A\u061B \u0627\u06AF\u0631 \u2265\u06F1\u06F0 \u062F\u0642\u06CC\u0642\u0647 \u0637\u0648\u0644 \u0628\u06A9\u0634\u062F\u060C \u062A\u063A\u06CC\u06CC\u0631 \u062E\u0637 \u067E\u0627\u06CC\u0647 \u0645\u062D\u0633\u0648\u0628 \u0645\u06CC\u200C\u0634\u0648\u062F."},{id:"p2ch18-q12",type:"mcq",question:"\u06CC\u06A9 \u0646\u0648\u0627\u0631 FHR \u0628\u0627 \u0636\u0631\u0628\u0627\u0646 \u067E\u0627\u06CC\u0647\u200C\u06CC \u06F1\u06F4\u06F0\u060C \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0645\u062A\u0648\u0633\u0637\u060C \u0628\u062F\u0648\u0646 \u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633 \u06CC\u0627 \u0645\u062A\u063A\u06CC\u0631\u060C \u0648 \u0628\u0627 \u062A\u0633\u0631\u06CC\u0639\u200C\u0647\u0627\u06CC \u0645\u062A\u0646\u0627\u0648\u0628 \u062B\u0628\u062A \u0634\u062F\u0647 \u0627\u0633\u062A. \u0627\u06CC\u0646 \u0646\u0648\u0627\u0631 \u0637\u0628\u0642 \u0637\u0628\u0642\u0647\u200C\u0628\u0646\u062F\u06CC NICHD \u062F\u0631 \u06A9\u062F\u0627\u0645 \u062F\u0633\u062A\u0647 \u0642\u0631\u0627\u0631 \u0645\u06CC\u200C\u06AF\u06CC\u0631\u062F\u061F",choices:["\u062F\u0633\u062A\u0647 I (\u0637\u0628\u06CC\u0639\u06CC)","\u062F\u0633\u062A\u0647 II (\u0646\u0627\u0645\u0634\u062E\u0635)","\u062F\u0633\u062A\u0647 III (\u063A\u06CC\u0631\u0637\u0628\u06CC\u0639\u06CC)","\u0646\u0645\u06CC\u200C\u062A\u0648\u0627\u0646 \u0637\u0628\u0642\u0647\u200C\u0628\u0646\u062F\u06CC \u06A9\u0631\u062F"],correctIndex:0,explanation:"\u0636\u0631\u0628\u0627\u0646 \u067E\u0627\u06CC\u0647 \u062F\u0631 \u0645\u062D\u062F\u0648\u062F\u0647\u200C\u06CC \u0637\u0628\u06CC\u0639\u06CC\u060C \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0645\u062A\u0648\u0633\u0637\u060C \u0641\u0642\u062F\u0627\u0646 \u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633/\u0645\u062A\u063A\u06CC\u0631 \u0648 \u0648\u062C\u0648\u062F \u062A\u0633\u0631\u06CC\u0639\u060C \u0645\u0639\u06CC\u0627\u0631\u0647\u0627\u06CC \u062F\u0633\u062A\u0647\u200C\u06CC I (\u0637\u0628\u06CC\u0639\u06CC) \u0631\u0627 \u0628\u0631\u0622\u0648\u0631\u062F\u0647 \u0645\u06CC\u200C\u06A9\u0646\u062F."},{id:"p2ch18-q13",type:"mcq",question:"\u06A9\u062F\u0627\u0645 \u06CC\u0627\u0641\u062A\u0647 \u0628\u0647\u200C\u062A\u0646\u0647\u0627\u06CC\u06CC \u0646\u0648\u0627\u0631 FHR \u0631\u0627 \u062F\u0631 \u062F\u0633\u062A\u0647\u200C\u06CC III (\u063A\u06CC\u0631\u0637\u0628\u06CC\u0639\u06CC) \u0637\u0628\u0642\u0647\u200C\u0628\u0646\u062F\u06CC \u0645\u06CC\u200C\u06A9\u0646\u062F\u061F",choices:["\u062A\u0627\u06A9\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC \u0628\u0627 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0645\u062A\u0648\u0633\u0637","\u0627\u0644\u06AF\u0648\u06CC \u0633\u06CC\u0646\u0648\u0633\u06CC","\u0627\u0641\u062A \u0632\u0648\u062F\u0631\u0633 \u0645\u06A9\u0631\u0631","\u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u062C\u0632\u0626\u06CC \u0628\u0647\u200C\u062A\u0646\u0647\u0627\u06CC\u06CC"],correctIndex:1,explanation:"\u062F\u0633\u062A\u0647\u200C\u06CC III \u0634\u0627\u0645\u0644 \u0627\u0644\u06AF\u0648\u06CC \u0633\u06CC\u0646\u0648\u0633\u06CC\u060C \u06CC\u0627 \u0641\u0642\u062F\u0627\u0646 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u067E\u0627\u06CC\u0647 \u0628\u0647\u200C\u0647\u0645\u0631\u0627\u0647 \u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633 \u0645\u06A9\u0631\u0631\u060C \u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631 \u0645\u06A9\u0631\u0631 \u06CC\u0627 \u0628\u0631\u0627\u062F\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC \u0627\u0633\u062A."},{id:"p2ch18-q14",type:"mcq",question:"\u062F\u0631 \u067E\u0627\u0633\u062E \u0628\u0647 \u06CC\u06A9 \u0646\u0648\u0627\u0631 FHR \u0646\u0627\u0645\u0637\u0645\u0626\u0646\u060C \u06A9\u062F\u0627\u0645 \u0627\u0642\u062F\u0627\u0645 \u0627\u0648\u0644\u06CC\u0647 \u0645\u0639\u0645\u0648\u0644\u0627\u064B \u0628\u0627\u06CC\u062F \u0627\u0646\u062C\u0627\u0645 \u0634\u0648\u062F\u061F",choices:["\u0627\u0641\u0632\u0627\u06CC\u0634 \u0633\u0631\u0639\u062A \u0627\u0646\u0641\u0648\u0632\u06CC\u0648\u0646 \u0627\u06A9\u0633\u06CC\u200C\u062A\u0648\u0633\u06CC\u0646","\u0642\u0637\u0639 \u0627\u06A9\u0633\u06CC\u200C\u062A\u0648\u0633\u06CC\u0646 \u0648 \u062A\u063A\u06CC\u06CC\u0631 \u0648\u0636\u0639\u06CC\u062A \u0645\u0627\u062F\u0631 \u0628\u0647 \u067E\u0647\u0644\u0648","\u062A\u062C\u0648\u06CC\u0632 \u0641\u0648\u0631\u06CC \u0645\u062A\u06CC\u0644\u200C\u0627\u0631\u06AF\u0648\u0646\u0648\u06CC\u0646","\u0627\u0646\u062C\u0627\u0645 \u0622\u0645\u0646\u06CC\u0648\u062A\u0648\u0645\u06CC \u0628\u062F\u0648\u0646 \u0645\u0639\u0627\u06CC\u0646\u0647"],correctIndex:1,explanation:"\u0627\u0642\u062F\u0627\u0645\u0627\u062A \u0627\u0648\u0644\u06CC\u0647 \u0634\u0627\u0645\u0644 \u0642\u0637\u0639 \u0639\u0627\u0645\u0644 \u062A\u062D\u0631\u06CC\u06A9\u200C\u06A9\u0646\u0646\u062F\u0647\u200C\u06CC \u0632\u0627\u06CC\u0645\u0627\u0646 (\u0627\u06A9\u0633\u06CC\u200C\u062A\u0648\u0633\u06CC\u0646)\u060C \u062A\u063A\u06CC\u06CC\u0631 \u0648\u0636\u0639\u06CC\u062A \u0645\u0627\u062F\u0631 \u0628\u0647 \u067E\u0647\u0644\u0648\u06CC \u0686\u067E \u06CC\u0627 \u0631\u0627\u0633\u062A\u060C \u0628\u0631\u0631\u0633\u06CC \u0647\u06CC\u067E\u0648\u062A\u0627\u0646\u0633\u06CC\u0648\u0646 \u0648 \u0627\u0631\u0632\u06CC\u0627\u0628\u06CC \u0628\u06CC\u0634\u200C\u0641\u0639\u0627\u0644\u06CC \u0631\u062D\u0645 \u0627\u0633\u062A."},{id:"p2ch18-q15",type:"mcq",question:"\u062F\u0631 \u0646\u0645\u0648\u0646\u0647\u200C\u06AF\u06CC\u0631\u06CC \u0627\u0632 \u067E\u0648\u0633\u062A \u0633\u0631 \u062C\u0646\u06CC\u0646\u060C pH \u0628\u06CC\u0646 \u06F7.\u06F2\u06F0 \u062A\u0627 \u06F7.\u06F2\u06F5 \u0686\u0647 \u0627\u0642\u062F\u0627\u0645\u06CC \u0631\u0627 \u0627\u06CC\u062C\u0627\u0628 \u0645\u06CC\u200C\u06A9\u0646\u062F\u061F",choices:["\u0641\u0642\u0637 \u067E\u06CC\u06AF\u06CC\u0631\u06CC \u0633\u06CC\u0631 \u0632\u0627\u06CC\u0645\u0627\u0646","\u062A\u06A9\u0631\u0627\u0631 \u0646\u0645\u0648\u0646\u0647\u200C\u06AF\u06CC\u0631\u06CC \u0638\u0631\u0641 \u06F3\u06F0 \u062F\u0642\u06CC\u0642\u0647","\u0633\u0632\u0627\u0631\u06CC\u0646 \u0641\u0648\u0631\u06CC","\u0642\u0637\u0639 \u06A9\u0627\u0645\u0644 \u0645\u0627\u0646\u06CC\u062A\u0648\u0631\u06CC\u0646\u06AF"],correctIndex:1,explanation:"pH \u0628\u06CC\u0646 \u06F7.\u06F2\u06F0 \u062A\u0627 \u06F7.\u06F2\u06F5 \u0646\u06CC\u0627\u0632 \u0628\u0647 \u062A\u06A9\u0631\u0627\u0631 \u0646\u0645\u0648\u0646\u0647\u200C\u06AF\u06CC\u0631\u06CC \u0638\u0631\u0641 \u06F3\u06F0 \u062F\u0642\u06CC\u0642\u0647 \u062F\u0627\u0631\u062F\u061B pH \u0628\u06CC\u0634\u062A\u0631 \u0627\u0632 \u06F7.\u06F2\u06F5 \u0641\u0642\u0637 \u0646\u06CC\u0627\u0632 \u0628\u0647 \u067E\u06CC\u06AF\u06CC\u0631\u06CC \u0648 \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F7.\u06F2\u06F0 \u0646\u06CC\u0627\u0632\u0645\u0646\u062F \u0627\u0642\u062F\u0627\u0645 \u0641\u0648\u0631\u06CC \u0627\u0633\u062A."},{id:"p2ch18-q16",type:"mcq",question:"\u062F\u0631 \u067E\u0627\u0644\u0633\u200C\u0627\u06A9\u0633\u06CC\u200C\u0645\u062A\u0631\u06CC \u062C\u0646\u06CC\u0646\u060C \u062D\u062F \u067E\u0627\u06CC\u06CC\u0646 \u0642\u0627\u0628\u0644\u200C\u0642\u0628\u0648\u0644 \u0627\u0634\u0628\u0627\u0639 \u0627\u06A9\u0633\u06CC\u0698\u0646 \u06A9\u0647 \u0627\u06AF\u0631 \u2264\u06F2 \u062F\u0642\u06CC\u0642\u0647 \u0628\u0627\u0642\u06CC \u0628\u0645\u0627\u0646\u062F \u0628\u0627 \u0627\u0641\u0632\u0627\u06CC\u0634 \u062E\u0637\u0631 \u0628\u062F\u062D\u0627\u0644\u06CC \u062C\u0646\u06CC\u0646 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062A\u060C \u06A9\u062F\u0627\u0645 \u0627\u0633\u062A\u061F",choices:["\u06F1\u06F0\u066A","\u06F3\u06F0\u066A","\u06F5\u06F0\u066A","\u06F7\u06F0\u066A"],correctIndex:1,explanation:"\u062D\u062F \u067E\u0627\u06CC\u06CC\u0646 \u0642\u0627\u0628\u0644\u200C\u0642\u0628\u0648\u0644 \u0627\u0634\u0628\u0627\u0639 \u0627\u06A9\u0633\u06CC\u0698\u0646 \u062C\u0646\u06CC\u0646 \u06F3\u06F0\u066A \u062A\u0639\u06CC\u06CC\u0646 \u0634\u062F\u0647 \u0627\u0633\u062A\u061B \u0628\u0627\u0642\u06CC \u0645\u0627\u0646\u062F\u0646 \u062F\u0631 \u0627\u06CC\u0646 \u0633\u0637\u062D \u06CC\u0627 \u06A9\u0645\u062A\u0631 \u0628\u0647 \u0645\u062F\u062A \u2264\u06F2 \u062F\u0642\u06CC\u0642\u0647 \u0628\u0627 \u0627\u0641\u0632\u0627\u06CC\u0634 \u062E\u0637\u0631 \u0628\u062F\u062D\u0627\u0644\u06CC \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062A."},{id:"p2ch18-q17",type:"mcq",question:"\u0648\u0627\u062D\u062F \u0645\u0648\u0646\u062A\u0647\u200C\u0648\u06CC\u062F\u0626\u0648 (Montevideo unit) \u0686\u06AF\u0648\u0646\u0647 \u0645\u062D\u0627\u0633\u0628\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F\u061F",choices:["\u0645\u062C\u0645\u0648\u0639 \u0641\u0631\u06A9\u0627\u0646\u0633 \u0627\u0646\u0642\u0628\u0627\u0636\u0627\u062A \u062F\u0631 \u06CC\u06A9 \u0633\u0627\u0639\u062A","\u062D\u0627\u0635\u0644\u200C\u0636\u0631\u0628 \u0634\u062F\u062A \u0627\u0646\u0642\u0628\u0627\u0636 (mmHg) \u062F\u0631 \u0641\u0631\u06A9\u0627\u0646\u0633 \u0627\u0646\u0642\u0628\u0627\u0636\u0627\u062A \u0637\u06CC \u06F1\u06F0 \u062F\u0642\u06CC\u0642\u0647","\u0645\u06CC\u0627\u0646\u06AF\u06CC\u0646 \u062A\u0648\u0646 \u0628\u0627\u0632\u0627\u0644 \u0631\u062D\u0645 \u062F\u0631 \u06F2\u06F4 \u0633\u0627\u0639\u062A","\u0645\u062F\u062A\u200C\u0632\u0645\u0627\u0646 \u06A9\u0644\u06CC \u0645\u0631\u062D\u0644\u0647\u200C\u06CC \u0627\u0648\u0644 \u0632\u0627\u06CC\u0645\u0627\u0646"],correctIndex:1,explanation:"\u0648\u0627\u062D\u062F \u0645\u0648\u0646\u062A\u0647\u200C\u0648\u06CC\u062F\u0626\u0648 \u0627\u0632 \u062D\u0627\u0635\u0644\u200C\u0636\u0631\u0628 \u0634\u062F\u062A \u0627\u0646\u0642\u0628\u0627\u0636 \u0631\u062D\u0645 (\u0628\u0631 \u062D\u0633\u0628 \u0645\u06CC\u0644\u06CC\u200C\u0645\u062A\u0631 \u062C\u06CC\u0648\u0647) \u062F\u0631 \u0641\u0631\u06A9\u0627\u0646\u0633 \u0627\u0646\u0642\u0628\u0627\u0636\u0627\u062A \u0637\u06CC \u06F1\u06F0 \u062F\u0642\u06CC\u0642\u0647 \u0628\u0647 \u062F\u0633\u062A \u0645\u06CC\u200C\u0622\u06CC\u062F."},{id:"p2ch18-q18",type:"mcq",question:"\u06A9\u062F\u0627\u0645 \u06CC\u06A9 \u0627\u0632 \u0645\u0648\u0627\u0631\u062F \u0632\u06CC\u0631 \u062C\u0632\u0648 \u0645\u0639\u06CC\u0627\u0631\u0647\u0627\u06CC \u0627\u0633\u0627\u0633\u06CC (\u0647\u0631 \u0686\u0647\u0627\u0631 \u0645\u0648\u0631\u062F \u0644\u0627\u0632\u0645) \u0628\u0631\u0627\u06CC \u0646\u0633\u0628\u062A\u200C\u062F\u0627\u062F\u0646 \u0641\u0644\u062C \u0645\u063A\u0632\u06CC \u0628\u0647 \u06CC\u06A9 \u0631\u0648\u06CC\u062F\u0627\u062F \u0647\u06CC\u067E\u0648\u06A9\u0633\u06CC\u06A9 \u062D\u0627\u062F \u062D\u06CC\u0646 \u062A\u0648\u0644\u062F \u0646\u06CC\u0633\u062A\u061F",choices:["\u0627\u0633\u06CC\u062F\u0648\u0632 \u0645\u062A\u0627\u0628\u0648\u0644\u06CC\u06A9 \u0628\u0627 pH < \u06F7 \u062F\u0631 \u062E\u0648\u0646 \u0634\u0631\u06CC\u0627\u0646 \u0628\u0646\u062F\u0646\u0627\u0641","\u0627\u0646\u0633\u0641\u0627\u0644\u0648\u067E\u0627\u062A\u06CC \u0645\u062A\u0648\u0633\u0637 \u062A\u0627 \u0634\u062F\u06CC\u062F \u0646\u0648\u0632\u0627\u062F\u06CC \u0628\u0627 \u0634\u0631\u0648\u0639 \u0632\u0648\u062F\u0631\u0633","\u0646\u0648\u0639 \u06A9\u0648\u0627\u062F\u0631\u06CC\u200C\u067E\u0644\u0698\u06CC \u0627\u0633\u067E\u0627\u0633\u062A\u06CC\u06A9 \u06CC\u0627 \u062F\u06CC\u0633\u200C\u06A9\u06CC\u0646\u062A\u06CC\u06A9 \u0641\u0644\u062C \u0645\u063A\u0632\u06CC","\u0648\u062C\u0648\u062F \u0645\u06A9\u0648\u0646\u06CC\u0648\u0645 \u063A\u0644\u06CC\u0638 \u062F\u0631 \u0645\u0627\u06CC\u0639 \u0622\u0645\u0646\u06CC\u0648\u062A\u06CC\u06A9"],correctIndex:3,explanation:"\u0648\u062C\u0648\u062F \u0645\u06A9\u0648\u0646\u06CC\u0648\u0645 \u062C\u0632\u0648 \u0645\u0639\u06CC\u0627\u0631\u0647\u0627\u06CC \u0627\u0633\u0627\u0633\u06CC \u0686\u0647\u0627\u0631\u06AF\u0627\u0646\u0647 \u0646\u06CC\u0633\u062A. \u0645\u0639\u06CC\u0627\u0631\u0647\u0627 \u0634\u0627\u0645\u0644 \u0627\u0633\u06CC\u062F\u0648\u0632 \u0645\u062A\u0627\u0628\u0648\u0644\u06CC\u06A9 \u0634\u062F\u06CC\u062F\u060C \u0627\u0646\u0633\u0641\u0627\u0644\u0648\u067E\u0627\u062A\u06CC \u0632\u0648\u062F\u0631\u0633\u060C \u0646\u0648\u0639 \u062E\u0627\u0635 \u0641\u0644\u062C \u0645\u063A\u0632\u06CC\u060C \u0648 \u0631\u062F \u0633\u0627\u06CC\u0631 \u0639\u0644\u0644 \u0642\u0627\u0628\u0644\u200C\u062A\u0634\u062E\u06CC\u0635 \u0627\u0633\u062A."},{id:"p2ch18-q19",type:"mcq",question:"\u0622\u0645\u0646\u06CC\u0648\u0627\u0646\u0641\u0648\u0632\u06CC\u0648\u0646 \u0645\u0639\u0645\u0648\u0644\u0627\u064B \u0628\u0631\u0627\u06CC \u06A9\u062F\u0627\u0645 \u0647\u062F\u0641 \u0628\u0647 \u06A9\u0627\u0631 \u0646\u0645\u06CC\u200C\u0631\u0648\u062F\u061F",choices:["\u062F\u0631\u0645\u0627\u0646 \u0627\u0641\u062A\u200C\u0647\u0627\u06CC \u0645\u062A\u063A\u06CC\u0631 \u06CC\u0627 \u0637\u0648\u0644\u0627\u0646\u06CC\u200C\u0645\u062F\u062A \u0646\u0627\u0634\u06CC \u0627\u0632 \u0641\u0634\u0627\u0631 \u0628\u0647 \u0628\u0646\u062F\u0646\u0627\u0641","\u0631\u0642\u06CC\u0642\u200C\u06A9\u0631\u062F\u0646 \u06CC\u0627 \u062E\u0627\u0631\u062C\u200C\u06A9\u0631\u062F\u0646 \u0645\u06A9\u0648\u0646\u06CC\u0648\u0645 \u063A\u0644\u06CC\u0638","\u067E\u06CC\u0634\u06AF\u06CC\u0631\u06CC \u062F\u0631 \u0627\u0648\u0644\u06CC\u06AF\u0648\u0647\u06CC\u062F\u0631\u0622\u0645\u0646\u06CC\u0648\u0633 \u0634\u0646\u0627\u062E\u062A\u0647\u200C\u0634\u062F\u0647","\u0627\u0641\u0632\u0627\u06CC\u0634 \u0645\u0633\u062A\u0642\u06CC\u0645 \u0641\u0634\u0627\u0631 \u062E\u0648\u0646 \u0633\u06CC\u0633\u062A\u0645\u06CC\u06A9 \u0645\u0627\u062F\u0631"],correctIndex:3,explanation:"\u0622\u0645\u0646\u06CC\u0648\u0627\u0646\u0641\u0648\u0632\u06CC\u0648\u0646 \u0628\u0631\u0627\u06CC \u062F\u0631\u0645\u0627\u0646 \u0627\u0641\u062A\u200C\u0647\u0627\u06CC \u0645\u062A\u063A\u06CC\u0631/\u0637\u0648\u0644\u0627\u0646\u06CC \u0646\u0627\u0634\u06CC \u0627\u0632 \u0641\u0634\u0627\u0631 \u0628\u0647 \u0628\u0646\u062F\u0646\u0627\u0641\u060C \u0631\u0642\u06CC\u0642\u200C\u06A9\u0631\u062F\u0646 \u0645\u06A9\u0648\u0646\u06CC\u0648\u0645 \u063A\u0644\u06CC\u0638\u060C \u0648 \u067E\u06CC\u0634\u06AF\u06CC\u0631\u06CC \u062F\u0631 \u0627\u0648\u0644\u06CC\u06AF\u0648\u0647\u06CC\u062F\u0631\u0622\u0645\u0646\u06CC\u0648\u0633 \u0628\u0647 \u06A9\u0627\u0631 \u0645\u06CC\u200C\u0631\u0648\u062F\u061B \u062A\u0623\u062B\u06CC\u0631\u06CC \u0628\u0631 \u0641\u0634\u0627\u0631 \u062E\u0648\u0646 \u0645\u0627\u062F\u0631 \u0646\u062F\u0627\u0631\u062F."},{id:"p2ch18-q20",type:"mcq",question:"\u062F\u0631 \u0632\u0646\u0627\u0646\u06CC \u06A9\u0647 \u0627\u06A9\u0633\u06CC\u200C\u062A\u0648\u0633\u06CC\u0646 \u062F\u0631\u06CC\u0627\u0641\u062A \u0645\u06CC\u200C\u06A9\u0646\u0646\u062F\u060C \u0641\u0639\u0627\u0644\u06CC\u062A \u0631\u062D\u0645\u06CC \u0645\u0639\u0645\u0648\u0644\u0627\u064B \u0628\u0647 \u0686\u0647 \u0645\u06CC\u0632\u0627\u0646\u06CC (\u0648\u0627\u062D\u062F \u0645\u0648\u0646\u062A\u0647\u200C\u0648\u06CC\u062F\u0626\u0648) \u0645\u06CC\u200C\u0631\u0633\u062F\u061F",choices:["\u06F5\u06F0 \u062A\u0627 \u06F1\u06F0\u06F0","\u06F1\u06F0\u06F0 \u062A\u0627 \u06F1\u06F5\u06F0","\u06F2\u06F0\u06F0 \u062A\u0627 \u06F2\u06F2\u06F5","\u06F3\u06F5\u06F0 \u062A\u0627 \u06F4\u06F0\u06F0"],correctIndex:2,explanation:"\u062F\u0631 \u0632\u0646\u0627\u0646\u06CC \u06A9\u0647 \u0627\u06A9\u0633\u06CC\u200C\u062A\u0648\u0633\u06CC\u0646 \u062F\u0631\u06CC\u0627\u0641\u062A \u0645\u06CC\u200C\u06A9\u0646\u0646\u062F\u060C \u0641\u0639\u0627\u0644\u06CC\u062A \u0631\u062D\u0645\u06CC \u0645\u0639\u0645\u0648\u0644\u0627\u064B \u06F2\u06F0\u06F0 \u062A\u0627 \u06F2\u06F2\u06F5 \u0648\u0627\u062D\u062F \u0645\u0648\u0646\u062A\u0647\u200C\u0648\u06CC\u062F\u0626\u0648 \u0627\u06CC\u062C\u0627\u062F \u0645\u06CC\u200C\u0634\u0648\u062F (\u062F\u0631 \u06F4\u06F0\u066A \u0645\u0648\u0627\u0631\u062F \u062A\u0627 \u06F3\u06F0\u06F0 \u0648\u0627\u062D\u062F)."},{id:"p2ch18-q21",type:"short",prompt:"\u062A\u0641\u0627\u0648\u062A \u0645\u06A9\u0627\u0646\u06CC\u0633\u0645 \u0627\u0641\u062A \u0632\u0648\u062F\u0631\u0633 \u0648 \u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062C\u0646\u06CC\u0646 \u0631\u0627 \u062A\u0648\u0636\u06CC\u062D \u062F\u0647\u06CC\u062F.",answer:"\u0627\u0641\u062A \u0632\u0648\u062F\u0631\u0633 \u0628\u0647\u200C\u062F\u0644\u06CC\u0644 \u0641\u0634\u0627\u0631 \u0645\u0633\u062A\u0642\u06CC\u0645 \u0628\u0647 \u0633\u0631 \u062C\u0646\u06CC\u0646 \u0648 \u062A\u062D\u0631\u06CC\u06A9 \u0648\u0627\u06AF (\u062A\u062D\u0631\u06CC\u06A9 \u062F\u0648\u0631\u0627) \u0631\u062E \u0645\u06CC\u200C\u062F\u0647\u062F \u0648 \u0641\u06CC\u0632\u06CC\u0648\u0644\u0648\u0698\u06CC\u06A9 \u0648 \u0628\u06CC\u200C\u062E\u0637\u0631 \u0627\u0633\u062A\u061B \u0632\u0645\u0627\u0646 \u0622\u0646 \u0647\u0645\u200C\u0632\u0645\u0627\u0646 \u0628\u0627 \u0627\u0646\u0642\u0628\u0627\u0636 \u0627\u0633\u062A. \u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633 \u0646\u0627\u0634\u06CC \u0627\u0632 \u06A9\u0627\u0647\u0634 \u0627\u06A9\u0633\u06CC\u0698\u0646\u0627\u0633\u06CC\u0648\u0646 \u0648\u0627\u062D\u062F \u0631\u062D\u0645\u06CC-\u062C\u0641\u062A\u06CC (\u0646\u0627\u0631\u0633\u0627\u06CC\u06CC \u062C\u0641\u062A\u06CC\u060C \u0647\u06CC\u067E\u0648\u062A\u0627\u0646\u0633\u06CC\u0648\u0646\u060C \u0647\u06CC\u067E\u0631\u0627\u0633\u062A\u06CC\u0645\u0648\u0644\u0627\u0633\u06CC\u0648\u0646 \u0631\u062D\u0645) \u0627\u0633\u062A \u0648 \u0627\u0648\u0644\u06CC\u0646 \u067E\u06CC\u0627\u0645\u062F \u0647\u06CC\u067E\u0648\u06A9\u0633\u06CC \u062C\u0646\u06CC\u0646\u06CC \u0645\u062D\u0633\u0648\u0628 \u0645\u06CC\u200C\u0634\u0648\u062F\u061B \u0632\u0645\u0627\u0646 \u0622\u0646 \u067E\u0633 \u0627\u0632 \u0627\u0646\u0642\u0628\u0627\u0636 \u0631\u062E \u0645\u06CC\u200C\u062F\u0647\u062F."},{id:"p2ch18-q22",type:"short",prompt:"\u0627\u0644\u06AF\u0648\u06CC \u0648\u0627\u0642\u0639\u06CC \u062F\u06CC\u0633\u062A\u0631\u0633 \u062C\u0646\u06CC\u0646 \u0628\u0631 \u0627\u0633\u0627\u0633 \u062A\u0631\u06A9\u06CC\u0628 \u0686\u0647 \u06CC\u0627\u0641\u062A\u0647\u200C\u0647\u0627\u06CC\u06CC \u062A\u0639\u0631\u06CC\u0641 \u0645\u06CC\u200C\u0634\u0648\u062F\u061F",answer:"\u0641\u0642\u062F\u0627\u0646 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u067E\u0627\u06CC\u0647 \u0628\u0647\u200C\u0647\u0645\u0631\u0627\u0647 \u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633 \u06CC\u0627 \u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631 \u0634\u062F\u06CC\u062F\u060C \u06CC\u0627 \u0636\u0631\u0628\u0627\u0646 \u067E\u0627\u06CC\u0647 \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F1\u06F1\u06F0 \u0636\u0631\u0628\u0647 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647 \u0628\u0647 \u0645\u062F\u062A \u06F5 \u062F\u0642\u06CC\u0642\u0647 \u06CC\u0627 \u0628\u06CC\u0634\u062A\u0631. \u0627\u06CC\u0646 \u0627\u0644\u06AF\u0648 \u062E\u0648\u0634\u0628\u062E\u062A\u0627\u0646\u0647 \u0646\u0627\u062F\u0631 \u0627\u0633\u062A."},{id:"p2ch18-q23",type:"short",prompt:"\u0686\u0631\u0627 \u0648\u062C\u0648\u062F \u0645\u06A9\u0648\u0646\u06CC\u0648\u0645 \u062F\u0631 \u0645\u0627\u06CC\u0639 \u0622\u0645\u0646\u06CC\u0648\u062A\u06CC\u06A9 \u0631\u0627 \u0628\u0647\u200C\u062A\u0646\u0647\u0627\u06CC\u06CC \u0646\u0645\u06CC\u200C\u062A\u0648\u0627\u0646 \u0645\u0639\u06CC\u0627\u0631 \u0642\u0637\u0639\u06CC \u062F\u06CC\u0633\u062A\u0631\u0633 \u062C\u0646\u06CC\u0646 \u062F\u0627\u0646\u0633\u062A\u061F",answer:"\u062F\u0641\u0639 \u0645\u06A9\u0648\u0646\u06CC\u0648\u0645 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u062F \u067E\u062F\u06CC\u062F\u0647\u200C\u0627\u06CC \u0641\u06CC\u0632\u06CC\u0648\u0644\u0648\u0698\u06CC\u06A9 \u0628\u0627\u0634\u062F (\u0628\u0644\u0648\u063A \u06AF\u0648\u0627\u0631\u0634\u06CC \u06CC\u0627 \u062A\u062D\u0631\u06CC\u06A9 \u0648\u0627\u06AF \u0646\u0627\u0634\u06CC \u0627\u0632 \u0641\u0634\u0627\u0631 \u062E\u0641\u06CC\u0641 \u0628\u0647 \u0628\u0646\u062F\u0646\u0627\u0641) \u0648 \u062F\u0631 \u06F1\u06F2 \u062A\u0627 \u06F2\u06F2\u066A \u0632\u0627\u06CC\u0645\u0627\u0646\u200C\u0647\u0627\u06CC \u0637\u0628\u06CC\u0639\u06CC \u0631\u062E \u0645\u06CC\u200C\u062F\u0647\u062F\u061B \u062A\u0646\u0647\u0627 \u0628\u062E\u0634 \u06A9\u0648\u0686\u06A9\u06CC \u0627\u0632 \u0645\u0648\u0627\u0631\u062F \u0628\u0627 \u0645\u0631\u06AF\u200C\u0648\u0645\u06CC\u0631 \u062C\u0646\u06CC\u0646\u06CC \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062A \u0648 \u0634\u0641\u0627\u0641 \u0628\u0648\u062F\u0646 \u0645\u0627\u06CC\u0639 \u0646\u06CC\u0632 \u062A\u0636\u0645\u06CC\u0646 \u0633\u0644\u0627\u0645\u062A \u062C\u0646\u06CC\u0646 \u0646\u06CC\u0633\u062A."},{id:"p2ch18-q24",type:"short",prompt:"\u062F\u0631 \u0628\u0631\u062E\u0648\u0631\u062F \u0627\u0648\u0644\u06CC\u0647 \u0628\u0627 \u06CC\u06A9 \u0627\u0644\u06AF\u0648\u06CC FHR \u0646\u0627\u0645\u0637\u0645\u0626\u0646\u060C \u067E\u0646\u062C \u0627\u0642\u062F\u0627\u0645 \u06A9\u0644\u06CC\u062F\u06CC \u0631\u0627 \u0646\u0627\u0645 \u0628\u0628\u0631\u06CC\u062F.",answer:"\u0642\u0637\u0639 \u0647\u0631 \u0639\u0627\u0645\u0644 \u062A\u062D\u0631\u06CC\u06A9\u200C\u06A9\u0646\u0646\u062F\u0647\u200C\u06CC \u0632\u0627\u06CC\u0645\u0627\u0646 (\u0627\u06A9\u0633\u06CC\u200C\u062A\u0648\u0633\u06CC\u0646)\u060C \u0645\u0639\u0627\u06CC\u0646\u0647\u200C\u06CC \u0633\u0631\u0648\u06CC\u06A9\u0633 \u0628\u0631\u0627\u06CC \u0628\u0631\u0631\u0633\u06CC \u067E\u0631\u0648\u0644\u0627\u067E\u0633 \u0628\u0646\u062F\u0646\u0627\u0641 \u06CC\u0627 \u0646\u0632\u0648\u0644 \u0633\u0631\u06CC\u0639 \u0633\u0631\u060C \u062A\u063A\u06CC\u06CC\u0631 \u0648\u0636\u0639\u06CC\u062A \u0645\u0627\u062F\u0631 \u0628\u0647 \u067E\u0647\u0644\u0648\u06CC \u0686\u067E \u06CC\u0627 \u0631\u0627\u0633\u062A\u060C \u0628\u0631\u0631\u0633\u06CC \u0648 \u062F\u0631\u0645\u0627\u0646 \u0647\u06CC\u067E\u0648\u062A\u0627\u0646\u0633\u06CC\u0648\u0646 \u0645\u0627\u062F\u0631 (\u0628\u0647\u200C\u062E\u0635\u0648\u0635 \u0628\u0627 \u0628\u06CC\u200C\u062D\u0633\u06CC \u0645\u0646\u0637\u0642\u0647\u200C\u0627\u06CC)\u060C \u0648 \u0627\u0631\u0632\u06CC\u0627\u0628\u06CC \u0641\u0631\u06A9\u0627\u0646\u0633/\u0645\u062F\u062A \u0627\u0646\u0642\u0628\u0627\u0636\u0627\u062A \u0628\u0631\u0627\u06CC \u06A9\u0634\u0641 \u0647\u06CC\u067E\u0631\u0627\u0633\u062A\u06CC\u0645\u0648\u0644\u0627\u0633\u06CC\u0648\u0646 \u0631\u062D\u0645."},{id:"p2ch18-q25",type:"short",prompt:"\u06A9\u0627\u0647\u0634 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0636\u0631\u0628\u0627\u0646 \u0628\u0647 \u0636\u0631\u0628\u0627\u0646 \u062C\u0646\u06CC\u0646 \u0686\u0647 \u0639\u0644\u0644 \u0634\u0627\u06CC\u0639\u06CC \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u062F \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u062F (\u063A\u06CC\u0631 \u0627\u0632 \u0627\u0633\u06CC\u062F\u0645\u06CC)\u061F",answer:"\u062F\u0627\u0631\u0648\u0647\u0627\u06CC \u0636\u062F\u062F\u0631\u062F \u0632\u0627\u06CC\u0645\u0627\u0646\u06CC (\u0646\u0627\u0631\u06A9\u0648\u062A\u06CC\u06A9\u200C\u0647\u0627\u060C \u0628\u0627\u0631\u0628\u06CC\u062A\u0648\u0631\u0627\u062A\u200C\u0647\u0627\u060C \u0641\u0646\u0648\u062A\u06CC\u0627\u0632\u06CC\u0646\u200C\u0647\u0627\u060C \u0622\u0631\u0627\u0645\u200C\u0628\u062E\u0634\u200C\u0647\u0627 \u0648 \u0628\u06CC\u0647\u0648\u0634\u200C\u06A9\u0646\u0646\u062F\u0647\u200C\u0647\u0627\u06CC \u0639\u0645\u0648\u0645\u06CC)\u060C \u0633\u0648\u0644\u0641\u0627\u062A \u0645\u0646\u06CC\u0632\u06CC\u0645\u060C \u0648 \u062F\u0648\u0631\u0647\u200C\u0647\u0627\u06CC \u062E\u0648\u0627\u0628 \u0641\u06CC\u0632\u06CC\u0648\u0644\u0648\u0698\u06CC\u06A9 \u062C\u0646\u06CC\u0646."},{id:"p2ch18-q26",type:"mcq",vignette:!0,question:"\u0632\u0646\u06CC \u06F2\u06F8 \u0633\u0627\u0644\u0647 \u062F\u0631 \u0641\u0627\u0632 \u0641\u0639\u0627\u0644 \u0632\u0627\u06CC\u0645\u0627\u0646 \u0628\u0627 \u0628\u06CC\u200C\u062D\u0633\u06CC \u0627\u067E\u06CC\u062F\u0648\u0631\u0627\u0644 \u0627\u0633\u062A. \u062F\u0631 \u0646\u0648\u0627\u0631 FHR\u060C \u0627\u0641\u062A\u200C\u0647\u0627\u06CC \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u0647\u0645\u0648\u0627\u0631\u0647 \u067E\u0633 \u0627\u0632 \u0627\u0648\u062C \u0647\u0631 \u0627\u0646\u0642\u0628\u0627\u0636 \u0634\u0631\u0648\u0639 \u0634\u062F\u0647 \u0648 \u062A\u0646\u0647\u0627 \u067E\u0633 \u0627\u0632 \u067E\u0627\u06CC\u0627\u0646 \u0627\u0646\u0642\u0628\u0627\u0636 \u0628\u0647 \u062E\u0637 \u067E\u0627\u06CC\u0647 \u0628\u0627\u0632\u0645\u06CC\u200C\u06AF\u0631\u062F\u0646\u062F\u061B \u0641\u0634\u0627\u0631 \u062E\u0648\u0646 \u0645\u0627\u062F\u0631 \u06F9\u06F0/\u06F5\u06F5 \u0645\u06CC\u0644\u06CC\u200C\u0645\u062A\u0631 \u062C\u06CC\u0648\u0647 \u062B\u0628\u062A \u0634\u062F\u0647 \u0627\u0633\u062A. \u0645\u062D\u062A\u0645\u0644\u200C\u062A\u0631\u06CC\u0646 \u062A\u0634\u062E\u06CC\u0635 \u0648 \u0627\u0648\u0644\u06CC\u0646 \u0627\u0642\u062F\u0627\u0645 \u062F\u0631\u0645\u0627\u0646\u06CC \u06A9\u062F\u0627\u0645 \u0627\u0633\u062A\u061F",choices:["\u0627\u0641\u062A \u0632\u0648\u062F\u0631\u0633\u061B \u0646\u06CC\u0627\u0632\u06CC \u0628\u0647 \u0645\u062F\u0627\u062E\u0644\u0647 \u0646\u06CC\u0633\u062A","\u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633 \u0646\u0627\u0634\u06CC \u0627\u0632 \u0647\u06CC\u067E\u0648\u062A\u0627\u0646\u0633\u06CC\u0648\u0646 \u0627\u067E\u06CC\u062F\u0648\u0631\u0627\u0644\u061B \u062A\u063A\u06CC\u06CC\u0631 \u0648\u0636\u0639\u06CC\u062A \u0645\u0627\u062F\u0631 \u0648 \u062A\u062C\u0648\u06CC\u0632 \u0627\u0641\u062F\u0631\u06CC\u0646/\u0641\u0646\u06CC\u0644\u200C\u0627\u0641\u0631\u06CC\u0646","\u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631 \u0646\u0627\u0634\u06CC \u0627\u0632 \u0627\u0646\u0633\u062F\u0627\u062F \u0628\u0646\u062F\u0646\u0627\u0641\u061B \u0622\u0645\u0646\u06CC\u0648\u0627\u0646\u0641\u0648\u0632\u06CC\u0648\u0646 \u0641\u0648\u0631\u06CC","\u0627\u0644\u06AF\u0648\u06CC \u0633\u06CC\u0646\u0648\u0633\u06CC \u0646\u0627\u0634\u06CC \u0627\u0632 \u0645\u062E\u062F\u0631\u061B \u0642\u0637\u0639 \u0628\u06CC\u200C\u062D\u0633\u06CC \u0627\u067E\u06CC\u062F\u0648\u0631\u0627\u0644"],correctIndex:1,explanation:"\u0634\u0631\u0648\u0639\u060C \u062D\u062F\u0627\u0642\u0644 \u0648 \u0628\u0627\u0632\u06AF\u0634\u062A \u0627\u0641\u062A \u067E\u0633 \u0627\u0632 \u0634\u0631\u0648\u0639\u060C \u0627\u0648\u062C \u0648 \u067E\u0627\u06CC\u0627\u0646 \u0627\u0646\u0642\u0628\u0627\u0636\u060C \u0645\u0634\u062E\u0635\u0647\u200C\u06CC \u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633 \u0627\u0633\u062A\u061B \u0647\u0645\u0631\u0627\u0647\u06CC \u0628\u0627 \u0627\u0641\u062A \u0641\u0634\u0627\u0631 \u062E\u0648\u0646 \u0645\u0627\u062F\u0631\u060C \u0647\u06CC\u067E\u0648\u062A\u0627\u0646\u0633\u06CC\u0648\u0646 \u0646\u0627\u0634\u06CC \u0627\u0632 \u0628\u06CC\u200C\u062D\u0633\u06CC \u0627\u067E\u06CC\u062F\u0648\u0631\u0627\u0644 \u0631\u0627 \u0628\u0647\u200C\u0639\u0646\u0648\u0627\u0646 \u0634\u0627\u06CC\u0639\u200C\u062A\u0631\u06CC\u0646 \u0639\u0644\u062A \u0645\u0637\u0631\u062D \u0645\u06CC\u200C\u06A9\u0646\u062F. \u0627\u0642\u062F\u0627\u0645 \u0627\u0648\u0644\u06CC\u0647 \u062A\u063A\u06CC\u06CC\u0631 \u0648\u0636\u0639\u06CC\u062A \u0645\u0627\u062F\u0631 \u0628\u0647 \u067E\u0647\u0644\u0648 \u0648 \u062F\u0631\u0645\u0627\u0646 \u0647\u06CC\u067E\u0648\u062A\u0627\u0646\u0633\u06CC\u0648\u0646 \u0628\u0627 \u0627\u0641\u062F\u0631\u06CC\u0646 \u06CC\u0627 \u0641\u0646\u06CC\u0644\u200C\u0627\u0641\u0631\u06CC\u0646 \u0627\u0633\u062A."},{id:"p2ch18-q27",type:"mcq",question:"\u062F\u0631 \u0645\u0648\u0631\u062F \u0622\u0631\u06CC\u062A\u0645\u06CC \u0642\u0644\u0628 \u062C\u0646\u06CC\u0646\u060C \u06A9\u062F\u0627\u0645 \u06AF\u0632\u06CC\u0646\u0647 \u062F\u0631\u0633\u062A \u0627\u0633\u062A\u061F",choices:["\u0634\u0627\u06CC\u0639\u200C\u062A\u0631\u06CC\u0646 \u0639\u0644\u062A \u0622\u0646 \u0627\u06A9\u0633\u062A\u0631\u0627\u0633\u06CC\u0633\u062A\u0648\u0644 \u0628\u0637\u0646\u06CC \u0627\u0633\u062A","\u0628\u06CC\u0634\u062A\u0631 \u0622\u0631\u06CC\u062A\u0645\u06CC\u200C\u0647\u0627\u06CC \u0641\u0648\u0642\u200C\u0628\u0637\u0646\u06CC \u062E\u0648\u0634\u200C\u062E\u06CC\u0645\u200C\u0627\u0646\u062F \u0645\u06AF\u0631 \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u0646\u0627\u0631\u0633\u0627\u06CC\u06CC \u0642\u0644\u0628\u06CC \u0646\u0627\u0634\u06CC \u0627\u0632 \u0647\u06CC\u062F\u0631\u0648\u067E\u0633 \u0628\u0627\u0634\u0646\u062F","\u0647\u06CC\u062F\u0631\u0648\u067E\u0633 \u062C\u0646\u06CC\u0646\u06CC \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u0622\u0631\u06CC\u062A\u0645\u06CC \u0627\u0632 \u0646\u0638\u0631 \u067E\u06CC\u0634\u200C\u0622\u06AF\u0647\u06CC \u0628\u06CC\u200C\u0627\u0647\u0645\u06CC\u062A \u0627\u0633\u062A","\u0622\u0631\u06CC\u062A\u0645\u06CC \u0642\u0644\u0628 \u062C\u0646\u06CC\u0646 \u0647\u0645\u0648\u0627\u0631\u0647 \u0646\u06CC\u0627\u0632\u0645\u0646\u062F \u062E\u062A\u0645 \u0641\u0648\u0631\u06CC \u062D\u0627\u0645\u0644\u06AF\u06CC \u0627\u0633\u062A"],correctIndex:1,explanation:"\u0634\u0627\u06CC\u0639\u200C\u062A\u0631\u06CC\u0646 \u0639\u0644\u062A \u0622\u0631\u06CC\u062A\u0645\u06CC\u060C \u0627\u06A9\u0633\u062A\u0631\u0627\u0633\u06CC\u0633\u062A\u0648\u0644 \u062F\u0647\u0644\u06CC\u0632\u06CC \u0627\u0633\u062A (\u0646\u0647 \u0628\u0637\u0646\u06CC) \u0648 \u0627\u06A9\u0633\u062A\u0631\u0627\u0633\u06CC\u0633\u062A\u0648\u0644 \u0628\u0637\u0646\u06CC \u06A9\u0645\u062A\u0631\u06CC\u0646 \u0646\u0642\u0634 \u0631\u0627 \u062F\u0627\u0631\u062F. \u0628\u06CC\u0634\u062A\u0631 \u0622\u0631\u06CC\u062A\u0645\u06CC\u200C\u0647\u0627\u06CC \u0641\u0648\u0642\u200C\u0628\u0637\u0646\u06CC \u062E\u0648\u0634\u200C\u062E\u06CC\u0645 \u0647\u0633\u062A\u0646\u062F \u0645\u06AF\u0631 \u0628\u0627 \u0646\u0627\u0631\u0633\u0627\u06CC\u06CC \u0642\u0644\u0628\u06CC \u0646\u0627\u0634\u06CC \u0627\u0632 \u0647\u06CC\u062F\u0631\u0648\u067E\u0633 \u0647\u0645\u0631\u0627\u0647 \u0628\u0627\u0634\u0646\u062F \u06A9\u0647 \u062F\u0631 \u0627\u06CC\u0646 \u0635\u0648\u0631\u062A \u067E\u06CC\u0634\u200C\u0622\u06AF\u0647\u06CC \u0646\u0627\u0645\u0637\u0644\u0648\u0628 \u0627\u0633\u062A."},{id:"p2ch18-q28",type:"mcq",question:"\u062F\u0631 \u0645\u0631\u062D\u0644\u0647\u200C\u06CC \u062F\u0648\u0645 \u0632\u0627\u06CC\u0645\u0627\u0646\u060C \u06A9\u062F\u0627\u0645 \u06CC\u0627\u0641\u062A\u0647 \u062F\u0631 \u0646\u0648\u0627\u0631 FHR \u0628\u0647\u200C\u0637\u0648\u0631 \u062E\u0627\u0635 \u067E\u06CC\u0634\u200C\u06AF\u0648\u06CC\u06CC\u200C\u06A9\u0646\u0646\u062F\u0647\u200C\u06CC \u0627\u0633\u06CC\u062F\u0645\u06CC \u062C\u0646\u06CC\u0646 \u0645\u0639\u0631\u0641\u06CC \u0634\u062F\u0647 \u0627\u0633\u062A\u061F",choices:["\u0648\u062C\u0648\u062F \u062A\u0633\u0631\u06CC\u0639\u200C\u0647\u0627\u06CC \u0645\u062A\u0646\u0627\u0648\u0628 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628","\u0627\u0632 \u0628\u06CC\u0646\u200C\u0631\u0641\u062A\u0646 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0636\u0631\u0628\u0627\u0646 \u0628\u0647 \u0636\u0631\u0628\u0627\u0646 \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u0636\u0631\u0628\u0627\u0646 \u067E\u0627\u06CC\u0647 \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F9\u06F0 \u0636\u0631\u0628\u0647 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647","\u0627\u0641\u062A \u0632\u0648\u062F\u0631\u0633 \u0645\u06A9\u0631\u0631 \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0645\u062A\u0648\u0633\u0637","\u062A\u0627\u06A9\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC \u062E\u0641\u06CC\u0641 \u0628\u0627 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0637\u0628\u06CC\u0639\u06CC"],correctIndex:1,explanation:"\u0637\u0628\u0642 \u06CC\u06A9 \u0645\u0637\u0627\u0644\u0639\u0647\u060C \u0627\u0632 \u0628\u06CC\u0646\u200C\u0631\u0641\u062A\u0646 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0636\u0631\u0628\u0627\u0646 \u0628\u0647 \u0636\u0631\u0628\u0627\u0646 \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u067E\u0627\u06CC\u0647 \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F9\u06F0 \u0636\u0631\u0628\u0647 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647 \u062F\u0631 \u0645\u0631\u062D\u0644\u0647\u200C\u06CC \u062F\u0648\u0645 \u0632\u0627\u06CC\u0645\u0627\u0646 \u067E\u06CC\u0634\u200C\u06AF\u0648\u06CC\u06CC\u200C\u06A9\u0646\u0646\u062F\u0647\u200C\u06CC \u0627\u0633\u06CC\u062F\u0645\u06CC \u062C\u0646\u06CC\u0646 \u0628\u0648\u062F\u061B \u062F\u0631 \u0645\u0637\u0627\u0644\u0639\u0647\u200C\u0627\u06CC \u062F\u06CC\u06AF\u0631 \u06A9\u0627\u0647\u0634 \u0646\u0627\u06AF\u0647\u0627\u0646\u06CC \u0628\u0647 \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F1\u06F0\u06F0bpm \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u06A9\u0627\u0647\u0634 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0628\u0631\u0627\u06CC \u062D\u062F\u0648\u062F \u06F4 \u062F\u0642\u06CC\u0642\u0647 \u0646\u06CC\u0632 \u067E\u06CC\u0634\u200C\u06AF\u0648\u06CC\u06CC\u200C\u06A9\u0646\u0646\u062F\u0647 \u0628\u0648\u062F."},{id:"p2ch18-tf1",type:"truefalse",statement:"\u0627\u0641\u062A \u0632\u0648\u062F\u0631\u0633 (early deceleration) \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062C\u0646\u06CC\u0646 \u0645\u0639\u0645\u0648\u0644\u0627\u064B \u0628\u0627 \u0647\u06CC\u067E\u0648\u06A9\u0633\u06CC\u060C \u0627\u0633\u06CC\u062F\u0645\u06CC \u06CC\u0627 \u0646\u0645\u0631\u0647\u200C\u06CC \u0622\u067E\u06AF\u0627\u0631 \u067E\u0627\u06CC\u06CC\u0646 \u062F\u0631 \u0628\u062F\u0648 \u062A\u0648\u0644\u062F \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062A.",isTrue:!1,explanation:"\u0627\u0641\u062A \u0632\u0648\u062F\u0631\u0633 \u0645\u06A9\u0627\u0646\u06CC\u0633\u0645\u06CC \u0641\u06CC\u0632\u06CC\u0648\u0644\u0648\u0698\u06CC\u06A9 \u062F\u0627\u0631\u062F (\u0641\u0634\u0627\u0631 \u0628\u0647 \u0633\u0631 \u062C\u0646\u06CC\u0646 \u0648 \u062A\u062D\u0631\u06CC\u06A9 \u0648\u0627\u06AF \u0627\u0632 \u0637\u0631\u06CC\u0642 \u062A\u062D\u0631\u06CC\u06A9 \u062F\u0648\u0631\u0627) \u0648 \u0628\u0627 \u0647\u06CC\u067E\u0648\u06A9\u0633\u06CC\u060C \u0627\u0633\u06CC\u062F\u0645\u06CC \u06CC\u0627 \u0622\u067E\u06AF\u0627\u0631 \u067E\u0627\u06CC\u06CC\u0646 \u0647\u0645\u0631\u0627\u0647 \u0646\u06CC\u0633\u062A\u061B \u0628\u0631\u062E\u0644\u0627\u0641 \u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633 \u06A9\u0647 \u0628\u0627\u0632\u062A\u0627\u0628 \u06A9\u0627\u0647\u0634 \u0627\u06A9\u0633\u06CC\u0698\u0646\u0627\u0633\u06CC\u0648\u0646 \u0631\u062D\u0645\u06CC-\u062C\u0641\u062A\u06CC \u0627\u0633\u062A."},{id:"p2ch18-tf2",type:"truefalse",statement:"\u0647\u0631\u0686\u0647 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u067E\u0627\u06CC\u0647\u200C\u06CC \u062C\u0646\u06CC\u0646 \u0633\u0631\u06CC\u0639\u200C\u062A\u0631 \u0628\u0627\u0634\u062F\u060C \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0636\u0631\u0628\u0627\u0646 \u0628\u0647 \u0636\u0631\u0628\u0627\u0646 \u0627\u0632 \u0646\u0638\u0631 \u0641\u06CC\u0632\u06CC\u0648\u0644\u0648\u0698\u06CC\u06A9 \u06A9\u0645\u062A\u0631 \u0628\u0647 \u0646\u0638\u0631 \u0645\u06CC\u200C\u0631\u0633\u062F\u061B \u0648 \u0639\u06A9\u0633 \u0627\u06CC\u0646 \u0631\u0627\u0628\u0637\u0647 (\u06A9\u0627\u0647\u0634 \u0636\u0631\u0628\u0627\u0646 \u067E\u0627\u06CC\u0647 \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u0627\u0641\u0632\u0627\u06CC\u0634 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC) \u0646\u06CC\u0632 \u0635\u0627\u062F\u0642 \u0627\u0633\u062A.",isTrue:!0,explanation:"\u0628\u0627 \u06A9\u0648\u062A\u0627\u0647\u200C\u062A\u0631 \u0634\u062F\u0646 \u0641\u0627\u0635\u0644\u0647\u200C\u06CC \u0628\u06CC\u0646 \u0636\u0631\u0628\u0627\u0646\u200C\u0647\u0627\u06CC \u0645\u062A\u0648\u0627\u0644\u06CC (\u062A\u0627\u06A9\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC)\u060C \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u067E\u0627\u06CC\u0647\u200C\u0627\u06CC \u0641\u06CC\u0632\u06CC\u0648\u0644\u0648\u0698\u06CC\u06A9\u200C\u062A\u0631 \u0648 \u06A9\u0645\u062A\u0631 \u0628\u0647 \u0646\u0638\u0631 \u0645\u06CC\u200C\u0631\u0633\u062F\u061B \u06A9\u0627\u0647\u0634 \u0633\u0631\u0639\u062A \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u0628\u0631\u0639\u06A9\u0633\u060C \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u067E\u0627\u06CC\u0647\u200C\u0627\u06CC \u0631\u0627 \u0628\u06CC\u0634\u062A\u0631 \u0646\u0634\u0627\u0646 \u0645\u06CC\u200C\u062F\u0647\u062F."},{id:"p2ch18-tf3",type:"truefalse",statement:"\u0628\u06CC\u0634\u062A\u0631 \u0645\u0648\u0627\u0631\u062F \u0641\u0644\u062C \u0645\u063A\u0632\u06CC (CP) \u0646\u0627\u0634\u06CC \u0627\u0632 \u0631\u0648\u06CC\u062F\u0627\u062F\u0647\u0627\u06CC \u062D\u06CC\u0646 \u0632\u0627\u06CC\u0645\u0627\u0646 (\u0622\u0633\u0641\u06CC\u06A9\u0633\u06CC \u062D\u06CC\u0646 \u062A\u0648\u0644\u062F) \u0647\u0633\u062A\u0646\u062F \u0648 \u0628\u0646\u0627\u0628\u0631\u0627\u06CC\u0646 \u0628\u0627 \u0645\u0627\u0646\u06CC\u062A\u0648\u0631\u06CC\u0646\u06AF \u0627\u0644\u06A9\u062A\u0631\u0648\u0646\u06CC\u06A9 \u062C\u0646\u06CC\u0646 \u0642\u0627\u0628\u0644 \u067E\u06CC\u0634\u06AF\u06CC\u0631\u06CC\u200C\u0627\u0646\u062F.",isTrue:!1,explanation:"\u0628\u06CC\u0634\u062A\u0631 \u0641\u0644\u062C\u200C\u0647\u0627\u06CC \u0645\u063A\u0632\u06CC \u0627\u0631\u062A\u0628\u0627\u0637\u06CC \u0628\u0627 \u0627\u062A\u0641\u0627\u0642\u0627\u062A \u062D\u06CC\u0646 \u0632\u0627\u06CC\u0645\u0627\u0646 \u0646\u062F\u0627\u0631\u0646\u062F (\u062F\u0631 \u06CC\u06A9 \u0645\u0637\u0627\u0644\u0639\u0647 \u062A\u0646\u0647\u0627 \u06F5\u066A \u0627\u0637\u0641\u0627\u0644 \u062F\u0686\u0627\u0631 \u0635\u062F\u0645\u0647\u200C\u06CC \u0645\u063A\u0632\u06CC\u060C \u0641\u0627\u06A9\u062A\u0648\u0631\u0647\u0627\u06CC \u062D\u06CC\u0646 \u062A\u0648\u0644\u062F \u062F\u0627\u0634\u062A\u0646\u062F)\u061B \u0639\u0648\u0627\u0645\u0644 \u062F\u06CC\u06AF\u0631\u06CC \u0645\u0627\u0646\u0646\u062F \u0632\u0627\u06CC\u0645\u0627\u0646 \u0632\u0648\u062F\u0631\u0633\u060C \u0639\u0641\u0648\u0646\u062A \u062C\u0646\u06CC\u0646\u06CC\u060C \u0627\u062E\u062A\u0644\u0627\u0644\u0627\u062A \u0698\u0646\u062A\u06CC\u06A9 \u0648 \u0645\u062D\u062F\u0648\u062F\u06CC\u062A \u0631\u0634\u062F \u062F\u0627\u062E\u0644\u200C\u0631\u062D\u0645\u06CC \u0646\u0642\u0634 \u062F\u0627\u0631\u0646\u062F. \u0627\u0641\u0632\u0627\u06CC\u0634 \u0627\u0637\u0644\u0627\u0639\u0627\u062A \u062D\u0627\u0635\u0644 \u0627\u0632 \u0645\u0627\u0646\u06CC\u062A\u0648\u0631\u06CC\u0646\u06AF \u0627\u0644\u06A9\u062A\u0631\u0648\u0646\u06CC\u06A9 \u0644\u0632\u0648\u0645\u0627\u064B \u0628\u0647 \u0628\u0647\u0628\u0648\u062F \u067E\u06CC\u0627\u0645\u062F \u062C\u0646\u06CC\u0646 \u0645\u0646\u062C\u0631 \u0646\u0634\u062F\u0647 \u0627\u0633\u062A."},{id:"p2ch18-tf4",type:"truefalse",statement:"\u0627\u0644\u06AF\u0648\u06CC \u0644\u0627\u0645\u0628\u062F\u0627 (Lambda) \u0634\u0627\u0645\u0644 \u06CC\u06A9 \u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u0648 \u0628\u0647 \u062F\u0646\u0628\u0627\u0644 \u0622\u0646 \u06CC\u06A9 \u062A\u0633\u0631\u06CC\u0639 \u0627\u0633\u062A.",isTrue:!1,explanation:"\u0627\u06CC\u0646 \u062A\u0648\u0635\u06CC\u0641 \u0645\u0631\u0628\u0648\u0637 \u0628\u0647 \u0627\u0644\u06AF\u0648\u06CC \u0627\u0648\u0631\u0634\u0648\u062A (overshoot) \u0627\u0633\u062A. \u0644\u0627\u0645\u0628\u062F\u0627 \u0628\u0631\u0639\u06A9\u0633 \u0622\u0646 \u0627\u0633\u062A: \u0627\u0628\u062A\u062F\u0627 \u06CC\u06A9 \u062A\u0633\u0631\u06CC\u0639 \u0648 \u0633\u067E\u0633 \u06CC\u06A9 \u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631 \u0628\u062F\u0648\u0646 \u062A\u0633\u0631\u06CC\u0639 \u062F\u0631 \u0627\u0646\u062A\u0647\u0627\u06CC \u0627\u0641\u062A \u0631\u062E \u0645\u06CC\u200C\u062F\u0647\u062F."},{id:"p2ch18-fill1",type:"fill",textWithBlank:"\u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u0632\u0645\u0627\u0646\u06CC \xAB\u062E\u0637\u06CC\u0631\xBB (\u0646\u06AF\u0631\u0627\u0646\u200C\u06A9\u0646\u0646\u062F\u0647) \u062A\u0644\u0642\u06CC \u0645\u06CC\u200C\u0634\u0648\u062F \u06A9\u0647 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u0628\u0647 \u06A9\u0645\u062A\u0631 \u0627\u0632 ___ \u0636\u0631\u0628\u0647 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647 \u0628\u0631\u0633\u062F \u0648 \u0628\u06CC\u0634 \u0627\u0632 \u06F6\u06F0 \u062B\u0627\u0646\u06CC\u0647 \u062F\u0631 \u0627\u06CC\u0646 \u062D\u0627\u0644\u062A \u0628\u0627\u0642\u06CC \u0628\u0645\u0627\u0646\u062F.",answer:"\u06F7\u06F0",explanation:"\u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631 \u0646\u06AF\u0631\u0627\u0646\u200C\u06A9\u0646\u0646\u062F\u0647 \u0648\u0642\u062A\u06CC \u0627\u0633\u062A \u06A9\u0647 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u0628\u0647 \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F7\u06F0 \u0636\u0631\u0628\u0647 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647 \u0628\u0631\u0633\u062F \u0648 \u0628\u06CC\u0634 \u0627\u0632 \u06F6\u06F0 \u062B\u0627\u0646\u06CC\u0647 \u0637\u0648\u0644 \u0628\u06A9\u0634\u062F."},{id:"p2ch18-fill2",type:"fill",textWithBlank:"\u062F\u0631 \u062A\u062D\u0631\u06CC\u06A9 \u0627\u0631\u062A\u0639\u0627\u0634\u06CC \u0635\u0648\u062A\u06CC (vibroacoustic stimulation)\u060C \u0627\u06AF\u0631 \u0638\u0631\u0641 \u06F1\u06F5 \u062B\u0627\u0646\u06CC\u0647 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062C\u0646\u06CC\u0646 ___ \u0636\u0631\u0628\u0647 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647 \u0627\u0641\u0632\u0627\u06CC\u0634 \u06CC\u0627\u0628\u062F \u0648 \u0628\u0647 \u0647\u0645\u06CC\u0646 \u0645\u062F\u062A \u0628\u0627\u0642\u06CC \u0628\u0645\u0627\u0646\u062F\u060C \u067E\u0627\u0633\u062E \u0637\u0628\u06CC\u0639\u06CC \u062A\u0644\u0642\u06CC \u0645\u06CC\u200C\u0634\u0648\u062F.",answer:"\u06F1\u06F5",explanation:"\u0627\u0641\u0632\u0627\u06CC\u0634 \u2265\u06F1\u06F5 bpm \u0638\u0631\u0641 \u06F1\u06F5 \u062B\u0627\u0646\u06CC\u0647 \u06A9\u0647 \u0628\u0647 \u0645\u062F\u062A \u06F1\u06F5 \u062B\u0627\u0646\u06CC\u0647 \u0628\u0627\u0642\u06CC \u0628\u0645\u0627\u0646\u062F\u060C \u067E\u0627\u0633\u062E \u0637\u0628\u06CC\u0639\u06CC \u0628\u0647 \u062A\u062D\u0631\u06CC\u06A9 \u0627\u0631\u062A\u0639\u0627\u0634\u06CC \u0635\u0648\u062A\u06CC \u0627\u0633\u062A \u0648 \u062C\u0627\u06CC\u06AF\u0632\u06CC\u0646\u06CC \u0628\u0631\u0627\u06CC \u062E\u0648\u0646\u200C\u06AF\u06CC\u0631\u06CC \u0627\u0632 \u067E\u0648\u0633\u062A \u0633\u0631 \u062C\u0646\u06CC\u0646 \u0645\u062D\u0633\u0648\u0628 \u0645\u06CC\u200C\u0634\u0648\u062F."},{id:"p2ch18-fill3",type:"fill",textWithBlank:"\u062F\u0631 \u0627\u0644\u06AF\u0648\u06CC \u0633\u06CC\u0646\u0648\u0633\u06CC \u0646\u0627\u0634\u06CC \u0627\u0632 \u062A\u062C\u0648\u06CC\u0632 \u0645\u062E\u062F\u0631\u0647\u0627\u06CC\u06CC \u0645\u0627\u0646\u0646\u062F \u0645\u067E\u0631\u06CC\u062F\u06CC\u0646 \u0628\u0647 \u0645\u0627\u062F\u0631\u060C \u0627\u0645\u0648\u0627\u062C \u0633\u06CC\u0646\u0648\u0633\u06CC \u0645\u0639\u0645\u0648\u0644\u0627\u064B \u0628\u0627 \u062A\u0648\u0627\u062A\u0631 \u062D\u062F\u0648\u062F ___ \u0633\u06CC\u06A9\u0644 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647 \u062F\u06CC\u062F\u0647 \u0645\u06CC\u200C\u0634\u0648\u0646\u062F.",answer:"\u06F6",explanation:"\u0628\u0647\u200C\u062F\u0646\u0628\u0627\u0644 \u062A\u062C\u0648\u06CC\u0632 \u0645\u067E\u0631\u06CC\u062F\u06CC\u0646\u060C \u0645\u0648\u0631\u0641\u06CC\u0646\u060C \u0622\u0644\u0641\u0627\u067E\u0631\u0648\u062F\u06CC\u0646 \u06CC\u0627 \u0628\u0648\u062A\u0648\u0631\u0641\u0627\u0646\u0648\u0644\u060C \u0646\u0645\u0627\u06CC \u0633\u06CC\u0646\u0648\u0633\u06CC \u0628\u0627 \u062A\u0648\u0627\u062A\u0631 \u062D\u062F\u0648\u062F \u06F6 \u0633\u06CC\u06A9\u0644 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647 \u0627\u06CC\u062C\u0627\u062F \u0645\u06CC\u200C\u0634\u0648\u062F."},{id:"p2ch18-fill4",type:"fill",textWithBlank:"\u0637\u0628\u0642 \u062F\u0633\u062A\u0648\u0631\u0627\u0644\u0639\u0645\u0644 \u0632\u0627\u0644\u0627\u0631 \u0648 \u06A9\u0648\u06CC\u0644\u06CC\u06AF\u0627\u0646\u060C \u0627\u06AF\u0631 pH \u062E\u0648\u0646 \u067E\u0648\u0633\u062A \u0633\u0631 \u062C\u0646\u06CC\u0646 \u0628\u06CC\u0634\u062A\u0631 \u0627\u0632 ___ \u0628\u0627\u0634\u062F\u060C \u062A\u0646\u0647\u0627 \u0646\u06CC\u0627\u0632 \u0628\u0647 \u067E\u06CC\u06AF\u06CC\u0631\u06CC \u0633\u06CC\u0631 \u0632\u0627\u06CC\u0645\u0627\u0646 \u0648\u062C\u0648\u062F \u062F\u0627\u0631\u062F.",answer:"\u06F7.\u06F2\u06F5",explanation:"pH \u0628\u06CC\u0634\u062A\u0631 \u0627\u0632 \u06F7.\u06F2\u06F5 \u0641\u0642\u0637 \u0646\u06CC\u0627\u0632\u0645\u0646\u062F \u067E\u06CC\u06AF\u06CC\u0631\u06CC \u0633\u06CC\u0631 \u0632\u0627\u06CC\u0645\u0627\u0646 \u0627\u0633\u062A\u061B pH \u0628\u06CC\u0646 \u06F7.\u06F2\u06F0 \u062A\u0627 \u06F7.\u06F2\u06F5 \u0646\u06CC\u0627\u0632\u0645\u0646\u062F \u062A\u06A9\u0631\u0627\u0631 \u0646\u0645\u0648\u0646\u0647\u200C\u06AF\u06CC\u0631\u06CC \u0638\u0631\u0641 \u06F3\u06F0 \u062F\u0642\u06CC\u0642\u0647 \u0648 pH \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F7.\u06F2\u06F0 \u0646\u06CC\u0627\u0632\u0645\u0646\u062F \u0627\u0642\u062F\u0627\u0645 \u0641\u0648\u0631\u06CC \u0627\u0633\u062A."},{id:"p2ch18-match1",type:"match",prompt:"\u0647\u0631 \u0627\u0644\u06AF\u0648\u06CC \u0646\u0627\u0645\u06AF\u0630\u0627\u0631\u06CC\u200C\u0634\u062F\u0647\u200C\u06CC \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062C\u0646\u06CC\u0646 \u0631\u0627 \u0628\u0627 \u062A\u0639\u0631\u06CC\u0641 \u0635\u062D\u06CC\u062D \u0622\u0646 \u0645\u0637\u0627\u0628\u0642\u062A \u062F\u0647\u06CC\u062F.",pairs:[{left:"\u0627\u0641\u062A \u0648 \u062E\u06CC\u0632\u062F\u0627\u0631 (Saltatory)",right:"\u0632\u0648\u062C\u200C\u0647\u0627\u06CC \u0633\u0631\u06CC\u0639 \u0648 \u067E\u06CC\u200C\u062F\u0631\u067E\u06CC \u062A\u0633\u0631\u06CC\u0639 \u0648 \u0627\u0641\u062A \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u06A9\u0647 \u0646\u0648\u0633\u0627\u0646\u0627\u062A \u0648\u0633\u06CC\u0639\u06CC \u0646\u0633\u0628\u062A \u0628\u0647 \u062E\u0637 \u067E\u0627\u06CC\u0647 \u0627\u06CC\u062C\u0627\u062F \u0645\u06CC\u200C\u06A9\u0646\u062F\u061B \u062F\u0631 \u063A\u06CC\u0627\u0628 \u0633\u0627\u06CC\u0631 \u06CC\u0627\u0641\u062A\u0647\u200C\u0647\u0627 \u0628\u0647\u200C\u062A\u0646\u0647\u0627\u06CC\u06CC \u062F\u0627\u0644 \u0628\u0631 \u0628\u062F\u062D\u0627\u0644\u06CC \u062C\u0646\u06CC\u0646 \u0646\u06CC\u0633\u062A"},{left:"\u0644\u0627\u0645\u0628\u062F\u0627 (Lambda)",right:"\u06CC\u06A9 \u062A\u0633\u0631\u06CC\u0639 \u0648 \u0628\u0647 \u062F\u0646\u0628\u0627\u0644 \u0622\u0646 \u06CC\u06A9 \u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631 \u0628\u062F\u0648\u0646 \u062A\u0633\u0631\u06CC\u0639 \u062F\u0631 \u0627\u0646\u062A\u0647\u0627\u06CC \u0627\u0641\u062A"},{left:"\u0627\u0648\u0631\u0634\u0648\u062A (Overshoot)",right:"\u06CC\u06A9 \u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631 \u0648 \u0628\u0647 \u062F\u0646\u0628\u0627\u0644 \u0622\u0646 \u06CC\u06A9 \u062A\u0633\u0631\u06CC\u0639\u061B \u0627\u0647\u0645\u06CC\u062A \u0628\u0627\u0644\u06CC\u0646\u06CC \u0622\u0646 \u0645\u062D\u0644 \u0628\u062D\u062B \u0627\u0633\u062A"},{left:"\u0633\u06CC\u0646\u0648\u0633\u06CC \u0648\u0627\u0642\u0639\u06CC (True sinusoidal)",right:"\u0646\u0648\u0633\u0627\u0646\u0627\u062A \u0635\u0627\u0641 \u0648 \u0645\u0646\u0638\u0645 \u0628\u0627 \u062A\u0648\u0627\u062A\u0631 \u06F2 \u062A\u0627 \u06F5 \u0633\u06CC\u06A9\u0644 \u062F\u0631 \u062F\u0642\u06CC\u0642\u0647\u060C \u062F\u0627\u0645\u0646\u0647\u200C\u06CC \u06F5 \u062A\u0627 \u06F1\u06F5 bpm \u0648 \u0641\u0642\u062F\u0627\u0646 \u062A\u0633\u0631\u06CC\u0639"},{left:"\u067E\u0633\u0648\u062F\u0648\u0633\u06CC\u0646\u0648\u0632\u0648\u0626\u06CC\u062F\u0627\u0644 (Pseudosinusoidal)",right:"\u0646\u0645\u0627\u06CC\u06CC \u0634\u0628\u06CC\u0647 \u0633\u06CC\u0646\u0648\u0633\u06CC \u0627\u0645\u0627 \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u062F\u0648\u0631\u0647\u200C\u0647\u0627\u06CC\u06CC \u0627\u0632 \u0648\u0627\u06A9\u0646\u0634\u200C\u067E\u0630\u06CC\u0631\u06CC \u0637\u0628\u06CC\u0639\u06CC (\u062A\u0646\u062F\u0634\u062F\u0646) \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628"}]},{id:"p2ch18-match2",type:"match",prompt:"\u0647\u0631 \u062F\u0633\u062A\u0647 \u0627\u0632 \u0637\u0628\u0642\u0647\u200C\u0628\u0646\u062F\u06CC \u0633\u0647\u200C\u06AF\u0627\u0646\u0647\u200C\u06CC NICHD \u0631\u0627 \u0628\u0627 \u0648\u06CC\u0698\u06AF\u06CC \u062A\u0639\u0631\u06CC\u0641\u200C\u06A9\u0646\u0646\u062F\u0647\u200C\u06CC \u0622\u0646 \u0645\u0637\u0627\u0628\u0642\u062A \u062F\u0647\u06CC\u062F.",pairs:[{left:"\u062F\u0633\u062A\u0647 I (\u0637\u0628\u06CC\u0639\u06CC)",right:"\u0636\u0631\u0628\u0627\u0646 \u067E\u0627\u06CC\u0647 \u06F1\u06F1\u06F0 \u062A\u0627 \u06F1\u06F6\u06F0\u060C \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u0645\u062A\u0648\u0633\u0637\u060C \u0641\u0642\u062F\u0627\u0646 \u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633 \u06CC\u0627 \u0645\u062A\u063A\u06CC\u0631"},{left:"\u062F\u0633\u062A\u0647 II (\u0646\u0627\u0645\u0634\u062E\u0635)",right:"\u0634\u0627\u0645\u0644 \u062A\u0645\u0627\u0645 \u0646\u0648\u0627\u0631\u0647\u0627\u06CC\u06CC \u06A9\u0647 \u062F\u0631 \u062F\u0633\u062A\u0647 I \u06CC\u0627 III \u0646\u0645\u06CC\u200C\u06AF\u0646\u062C\u0646\u062F\u061B \u0645\u0645\u06A9\u0646 \u0627\u0633\u062A \u0628\u062E\u0634 \u0642\u0627\u0628\u0644\u200C\u062A\u0648\u062C\u0647\u06CC \u0627\u0632 \u0646\u0648\u0627\u0631\u0647\u0627\u06CC \u0628\u0627\u0644\u06CC\u0646\u06CC \u0631\u0627 \u062A\u0634\u06A9\u06CC\u0644 \u062F\u0647\u062F"},{left:"\u062F\u0633\u062A\u0647 III (\u063A\u06CC\u0631\u0637\u0628\u06CC\u0639\u06CC)",right:"\u0641\u0642\u062F\u0627\u0646 \u062A\u063A\u06CC\u06CC\u0631\u067E\u0630\u06CC\u0631\u06CC \u067E\u0627\u06CC\u0647 \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u0627\u0641\u062A \u062F\u06CC\u0631\u0631\u0633 \u06CC\u0627 \u0645\u062A\u063A\u06CC\u0631 \u0645\u06A9\u0631\u0631 \u06CC\u0627 \u0628\u0631\u0627\u062F\u06CC\u200C\u06A9\u0627\u0631\u062F\u06CC\u060C \u06CC\u0627 \u0627\u0644\u06AF\u0648\u06CC \u0633\u06CC\u0646\u0648\u0633\u06CC"}]},{id:"p2ch18-match3",type:"match",prompt:"\u0647\u0631 \u0631\u0648\u0634 \u062A\u06A9\u0645\u06CC\u0644\u06CC \u0627\u0631\u0632\u06CC\u0627\u0628\u06CC \u062C\u0646\u06CC\u0646 \u0631\u0627 \u0628\u0627 \u0622\u0633\u062A\u0627\u0646\u0647 \u06CC\u0627 \u06CC\u0627\u0641\u062A\u0647\u200C\u06CC \u0645\u0631\u062A\u0628\u0637 \u0628\u0627 \u0622\u0646 \u0645\u0637\u0627\u0628\u0642\u062A \u062F\u0647\u06CC\u062F.",pairs:[{left:"\u0646\u0645\u0648\u0646\u0647\u200C\u06AF\u06CC\u0631\u06CC pH \u067E\u0648\u0633\u062A \u0633\u0631 \u062C\u0646\u06CC\u0646",right:"pH \u0628\u06CC\u0646 \u06F7.\u06F2\u06F0 \u062A\u0627 \u06F7.\u06F2\u06F5 \u0646\u06CC\u0627\u0632\u0645\u0646\u062F \u062A\u06A9\u0631\u0627\u0631 \u0646\u0645\u0648\u0646\u0647\u200C\u06AF\u06CC\u0631\u06CC \u0638\u0631\u0641 \u06F3\u06F0 \u062F\u0642\u06CC\u0642\u0647 \u0627\u0633\u062A"},{left:"\u067E\u0627\u0644\u0633\u200C\u0627\u06A9\u0633\u06CC\u200C\u0645\u062A\u0631\u06CC \u062C\u0646\u06CC\u0646",right:"\u062D\u062F \u067E\u0627\u06CC\u06CC\u0646 \u0642\u0627\u0628\u0644\u200C\u0642\u0628\u0648\u0644 \u0627\u0634\u0628\u0627\u0639 \u0627\u06A9\u0633\u06CC\u0698\u0646 \u06F3\u06F0\u066A \u0627\u0633\u062A"},{left:"\u062A\u062D\u0631\u06CC\u06A9 \u0627\u0631\u062A\u0639\u0627\u0634\u06CC \u0635\u0648\u062A\u06CC",right:"\u0627\u0641\u0632\u0627\u06CC\u0634 \u2265\u06F1\u06F5 bpm \u0638\u0631\u0641 \u0648 \u0628\u0647 \u0645\u062F\u062A \u06F1\u06F5 \u062B\u0627\u0646\u06CC\u0647 \u067E\u0627\u0633\u062E \u0637\u0628\u06CC\u0639\u06CC \u062A\u0644\u0642\u06CC \u0645\u06CC\u200C\u0634\u0648\u062F"},{left:"\u0628\u0631\u0631\u0633\u06CC \u062A\u063A\u06CC\u06CC\u0631\u0627\u062A ST \u062C\u0646\u06CC\u0646 (\u0627\u0644\u06A9\u062A\u0631\u0648\u06A9\u0627\u0631\u062F\u06CC\u0648\u06AF\u0631\u0627\u0641\u06CC)",right:"\u0646\u062A\u0627\u06CC\u062C \u06A9\u0644\u06CC \u0646\u0648\u0632\u0627\u062F\u06CC \u0631\u0627 \u0628\u0647\u0628\u0648\u062F \u0646\u062F\u0627\u062F \u0627\u0645\u0627 \u0645\u06CC\u0632\u0627\u0646 \u0633\u0632\u0627\u0631\u06CC\u0646 \u0646\u0627\u0634\u06CC \u0627\u0632 \u062F\u06CC\u0633\u062A\u0631\u0633 \u0631\u0627 \u06A9\u0627\u0647\u0634 \u062F\u0627\u062F"}]},{id:"p2ch18-order1",type:"order",prompt:"\u062A\u0631\u062A\u06CC\u0628 \u0635\u062D\u06CC\u062D \u0627\u0642\u062F\u0627\u0645\u0627\u062A \u0627\u0648\u0644\u06CC\u0647 \u062F\u0631 \u0628\u0631\u062E\u0648\u0631\u062F \u0628\u0627 \u06CC\u06A9 \u0627\u0644\u06AF\u0648\u06CC \u0646\u0627\u0645\u0637\u0645\u0626\u0646 (non-reassuring) \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062C\u0646\u06CC\u0646 \u0637\u0628\u0642 \u0631\u0627\u0647\u0646\u0645\u0627\u06CC ACOG \u0631\u0627 \u0645\u0631\u062A\u0628 \u06A9\u0646\u06CC\u062F.",steps:["\u0642\u0637\u0639 \u0647\u0631 \u0639\u0627\u0645\u0644 \u062A\u062D\u0631\u06CC\u06A9\u200C\u06A9\u0646\u0646\u062F\u0647\u200C\u06CC \u0632\u0627\u06CC\u0645\u0627\u0646 (\u0645\u0627\u0646\u0646\u062F \u0627\u06A9\u0633\u06CC\u200C\u062A\u0648\u0633\u06CC\u0646)","\u0645\u0639\u0627\u06CC\u0646\u0647\u200C\u06CC \u0633\u0631\u0648\u06CC\u06A9\u0633 \u0628\u0631\u0627\u06CC \u0628\u0631\u0631\u0633\u06CC \u067E\u0631\u0648\u0644\u0627\u067E\u0633 \u0628\u0646\u062F\u0646\u0627\u0641 \u06CC\u0627 \u0646\u0632\u0648\u0644 \u0633\u0631\u06CC\u0639 \u0633\u0631 \u062C\u0646\u06CC\u0646","\u062A\u063A\u06CC\u06CC\u0631 \u0648\u0636\u0639\u06CC\u062A \u0645\u0627\u062F\u0631 \u0628\u0647 \u067E\u0647\u0644\u0648\u06CC \u0686\u067E \u06CC\u0627 \u0631\u0627\u0633\u062A","\u0628\u0631\u0631\u0633\u06CC \u0641\u0634\u0627\u0631 \u062E\u0648\u0646 \u0645\u0627\u062F\u0631 \u0648 \u062F\u0631\u0645\u0627\u0646 \u0647\u06CC\u067E\u0648\u062A\u0627\u0646\u0633\u06CC\u0648\u0646 \u062F\u0631 \u0635\u0648\u0631\u062A \u0648\u062C\u0648\u062F (\u0627\u0641\u062F\u0631\u06CC\u0646 \u06CC\u0627 \u0641\u0646\u06CC\u0644\u200C\u0627\u0641\u0631\u06CC\u0646)","\u0627\u0631\u0632\u06CC\u0627\u0628\u06CC \u0641\u0631\u06A9\u0627\u0646\u0633 \u0648 \u0645\u062F\u062A \u0627\u0646\u0642\u0628\u0627\u0636\u0627\u062A \u0631\u062D\u0645\u06CC \u0628\u0631\u0627\u06CC \u06A9\u0634\u0641 \u0647\u06CC\u067E\u0631\u0627\u0633\u062A\u06CC\u0645\u0648\u0644\u0627\u0633\u06CC\u0648\u0646","\u062F\u0631 \u0635\u0648\u0631\u062A \u062A\u062F\u0627\u0648\u0645 \u0645\u0634\u06A9\u0644\u060C \u062A\u0648\u06A9\u0648\u0644\u06CC\u0632 \u062D\u0627\u062F \u0628\u0627 \u062A\u0631\u0628\u0648\u062A\u0627\u0644\u06CC\u0646 \u06CC\u0627 \u0646\u06CC\u062A\u0631\u0648\u06AF\u0644\u06CC\u0633\u06CC\u0631\u06CC\u0646 \u0628\u0631\u0627\u06CC \u0628\u0647\u0628\u0648\u062F \u0627\u06A9\u0633\u06CC\u0698\u0646\u0627\u0633\u06CC\u0648\u0646 \u062C\u0646\u06CC\u0646"]},{id:"p2ch18-order2",type:"order",prompt:"\u0632\u0646\u062C\u06CC\u0631\u0647\u200C\u06CC \u0631\u0648\u06CC\u062F\u0627\u062F\u0647\u0627\u06CC \u0641\u06CC\u0632\u06CC\u0648\u0644\u0648\u0698\u06CC\u06A9 \u0645\u0646\u062C\u0631 \u0628\u0647 \u0627\u0641\u062A \u0645\u062A\u063A\u06CC\u0631 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u0628\u0647\u200C\u062F\u0646\u0628\u0627\u0644 \u0627\u0646\u0633\u062F\u0627\u062F \u0628\u0646\u062F\u0646\u0627\u0641 \u0631\u0627 \u0628\u0647 \u062A\u0631\u062A\u06CC\u0628 \u0645\u0631\u062A\u0628 \u06A9\u0646\u06CC\u062F.",steps:["\u0627\u0646\u0633\u062F\u0627\u062F \u0646\u0633\u0628\u06CC \u06CC\u0627 \u06A9\u0627\u0645\u0644 \u0628\u0646\u062F\u0646\u0627\u0641 \u0631\u062E \u0645\u06CC\u200C\u062F\u0647\u062F","\u067E\u0633\u200C\u0628\u0627\u0631 (afterload) \u0648 \u0641\u0634\u0627\u0631 \u062E\u0648\u0646 \u0634\u0631\u06CC\u0627\u0646\u06CC \u062C\u0646\u06CC\u0646 \u0627\u0641\u0632\u0627\u06CC\u0634 \u0645\u06CC\u200C\u06CC\u0627\u0628\u062F","\u0628\u0627\u0631\u0648\u0631\u0633\u067E\u062A\u0648\u0631\u0647\u0627 \u062A\u062D\u0631\u06CC\u06A9 \u0634\u062F\u0647 \u0648 \u0627\u0632 \u0637\u0631\u06CC\u0642 \u0639\u0635\u0628 \u0648\u0627\u06AF \u0627\u0641\u062A \u0627\u0648\u0644\u06CC\u0647\u200C\u06CC \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u0627\u06CC\u062C\u0627\u062F \u0645\u06CC\u200C\u0634\u0648\u062F","\u0628\u0627 \u062A\u062F\u0627\u0648\u0645 \u0627\u0646\u0633\u062F\u0627\u062F\u060C \u0645\u062D\u062A\u0648\u0627\u06CC \u0627\u06A9\u0633\u06CC\u0698\u0646 \u0634\u0631\u06CC\u0627\u0646\u06CC \u062C\u0646\u06CC\u0646 \u06A9\u0627\u0647\u0634 \u0645\u06CC\u200C\u06CC\u0627\u0628\u062F","\u062D\u062F\u0648\u062F \u06F3\u06F0 \u062B\u0627\u0646\u06CC\u0647 \u0628\u0639\u062F\u060C \u06A9\u0645\u0648\u0633\u0631\u067E\u062A\u0648\u0631\u0647\u0627 \u0646\u06CC\u0632 \u062A\u062D\u0631\u06CC\u06A9 \u0634\u062F\u0647 \u0648 \u0627\u0641\u062A \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062A\u0634\u062F\u06CC\u062F \u0645\u06CC\u200C\u0634\u0648\u062F","\u0628\u0627 \u0631\u0641\u0639 \u0627\u0646\u0633\u062F\u0627\u062F \u0628\u0646\u062F\u0646\u0627\u0641\u060C \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u0628\u0647\u200C\u062A\u062F\u0631\u06CC\u062C \u0628\u0647 \u062E\u0637 \u067E\u0627\u06CC\u0647 \u0628\u0627\u0632\u0645\u06CC\u200C\u06AF\u0631\u062F\u062F"]}]};export{e as chapter};
